do
 local cache={} local signals={} local nextScan=0 local collection=game:GetService("CollectionService")
 S.handlerScanStats={scans=0,hits=0,lastMs=0,maxMs=0}
 S.cachedHandlerTables=function(keys)
  local key=table.concat(keys,",") local now=os.clock() local entry=cache[key]
  if entry and now<entry.expires then S.handlerScanStats.hits+=1 return entry.rows end
    -- Spread cold queries over separate frames instead of freezing on several scans at once.
  if S.mobileLite and os.clock()<nextScan then task.wait(nextScan-os.clock()) end
  now=os.clock()
  entry=cache[key]
  if entry and now<entry.expires then S.handlerScanStats.hits+=1 return entry.rows end
  local started=os.clock() local rows=filtergc("table",{Keys=keys},false)
  nextScan=os.clock()+.5
  local elapsed=(os.clock()-started)*1000 local stats=S.handlerScanStats
  stats.scans+=1 stats.lastMs=elapsed stats.maxMs=math.max(stats.maxMs,elapsed)
  cache[key]={rows=rows,created=os.clock(),expires=os.clock()+(S.mobileLite and 60 or 60)}
  return rows
 end
 local function changed()
  local deadline=os.clock()+1
  -- Allow binders to construct their handler before the next discovery.
  for _,entry in cache do entry.expires=math.max(entry.created+(S.mobileLite and 30 or 1),math.min(entry.expires,deadline)) end
 end
 for _,tag in {"DropperBasePart","VariantTokenSpawn"} do
  table.insert(signals,collection:GetInstanceAddedSignal(tag):Connect(changed))
  table.insert(signals,collection:GetInstanceRemovedSignal(tag):Connect(changed))
 end
 task.spawn(function()
  while S.running and G.BlueFarm==S do task.wait(2) end
  for _,connection in signals do connection:Disconnect() end
  table.clear(cache)
 end)
end

