local localeExact={} for _,r in localeRows do localeExact[r[1]]=r end
local localized=setmetatable({},{__mode="k"})
local translate=(function()
local translationCache={th={},en={}} local translationCacheCount=0
return function(source)
 local cache=translationCache[language]
 if cache[source] then return cache[source] end
 local index=language=="en" and 3 or 2
 local exact=localeExact[source] if exact then return exact[index] or source end
 -- Match only the original string, never translated output (avoids cascading substitutions).
 local out={} local cursor=1
 while cursor<=#source do
 local first,last,row
 for _,r in localeRows do
 if r[index] then
 local a,b=string.find(source,r[1],cursor,true)
 if a and (r[1]=="ON" or r[1]=="OFF") and (string.sub(source,a-1,a-1):match("[%w_]") or string.sub(source,b+1,b+1):match("[%w_]")) then a=nil end
 if a and (not first or a<first or (a==first and b>last)) then first,last,row=a,b,r end
 end
 end
 if not first then table.insert(out,string.sub(source,cursor)) break end
 table.insert(out,string.sub(source,cursor,first-1)) table.insert(out,row[index]) cursor=last+1
 end
 local result=table.concat(out)
 if translationCacheCount>2048 then translationCache={th={},en={}} translationCacheCount=0 cache=translationCache[language] end
 cache[source]=result translationCacheCount+=1 return result
end
end)()
local function bindLanguage(o)
 if not (o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox")) then return end
 local property=o:IsA("TextBox") and "PlaceholderText" or "Text"
 local entry={source=o[property],rendered=nil,property=property} localized[o]=entry
 local function render()
 entry.rendered=translate(entry.source)
 if o[property]~=entry.rendered then o[property]=entry.rendered end
 end
 local connection=o:GetPropertyChangedSignal(property):Connect(function()
 if o[property]~=entry.rendered then entry.source=o[property] render() end
 end)
 table.insert(connections,connection)
 render()
end
local languageRefresh
local function setLanguage(value)
 if value~="th" and value~="en" then return end
 language=value G.BlueFarmLanguage=value S.language=value
 for o,e in localized do if o.Parent then e.rendered=translate(e.source) o[e.property or "Text"]=e.rendered end end
 if languageRefresh then languageRefresh() end
end
S.language=language
S.setLanguage=setLanguage

