 local requestedParent=parent
 local columns=pageColumns[parent]
 if columns and (class=="TextLabel" or class=="TextButton" or class=="Frame") then
 local index=columns.count==1 and 1 or (columns.heights[1]<=columns.heights[2] and 1 or 2)
 columns.heights[index]+=(props.Size and props.Size.Y.Offset or 30)+8
 parent=columns[index]
 end
 local o=Instance.new(class) for k,v in props do
 o[k]=v
 if typeof(v)=="Color3" and (v==blue or v==Color3.fromRGB(0,171,190)) then
 themeTargets[o]=themeTargets[o] or {} themeTargets[o][k]=true
 end
 end if o:IsA("UIStroke") and S.currentBorderColor then o.Color=S.currentBorderColor end
 o.Parent=parent bindLanguage(o) if S.uiPageEntries[requestedParent] then table.insert(S.uiPageEntries[requestedParent],o) end return o
end
local function round(o,r)
 make("UICorner",o,{CornerRadius=UDim.new(0,r or 8)})
 if o:IsA("TextButton") then
 -- Neutral shading multiplies the chosen theme instead of replacing its hue.
 make("UIGradient",o,{Name="DepthShading",Rotation=90,Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.new(1,1,1)),ColorSequenceKeypoint.new(0.48,Color3.fromRGB(242,244,247)),ColorSequenceKeypoint.new(1,Color3.fromRGB(207,212,222))})})
 local edge=make("UIStroke",o,{Name="SurfaceEdge",ApplyStrokeMode=Enum.ApplyStrokeMode.Border,Color=Color3.new(1,1,1),Thickness=1,Transparency=0.88})
 table.insert(connections,o.MouseEnter:Connect(function()if edge.Parent then edge.Transparency=0.62 end end))
 table.insert(connections,o.MouseLeave:Connect(function()if edge.Parent then edge.Transparency=0.88 end end))
 elseif o:IsA("TextBox") then
 make("UIStroke",o,{Name="InsetEdge",Color=Color3.new(0,0,0),Thickness=1,Transparency=0.40})
 make("UIGradient",o,{Rotation=90,Color=ColorSequence.new(Color3.fromRGB(215,218,225),Color3.new(1,1,1))})
 end
end
