note(langues,"UI Color • ลากบนวงล้อเพื่อเลือกสี / Drag to choose color")
do
 local holder=make("Frame",langues,{Name="ColorPicker",Size=UDim2.new(1,-6,0,254),BackgroundTransparency=1})
 local wheel=make("Frame",holder,{Name="ColorWheel",Position=UDim2.fromOffset(8,4),Size=UDim2.fromOffset(192,192),BackgroundTransparency=1,Active=true})
 local hue,saturation,value=Color3.fromRGB(X.themeR,X.themeG,X.themeB):ToHSV()
 -- Draw locally so the picker has no external image or network dependency.
 for y=0,191 do
 local dy=(y+0.5-96)/96
 local half=math.sqrt(math.max(0,1-dy*dy))
 local points={}
 for x=0,19 do
 local dx=(x/19*2-1)*half
 local radius=math.min(1,math.sqrt(dx*dx+dy*dy))
 table.insert(points,ColorSequenceKeypoint.new(x/19,Color3.fromHSV((math.atan2(dy,dx)/(2*math.pi))%1,radius,1)))
 end
 local strip=make("Frame",wheel,{Position=UDim2.fromOffset(96-half*96,y),Size=UDim2.fromOffset(half*192,1),BorderSizePixel=0,BackgroundColor3=Color3.new(1,1,1),Active=false})
 themeTargets[strip]=nil
 make("UIGradient",strip,{Color=ColorSequence.new(points)})
 end
 local cursor=make("Frame",wheel,{Name="Selection",AnchorPoint=Vector2.new(0.5,0.5),Size=UDim2.fromOffset(10,10),BackgroundTransparency=1,ZIndex=5}) round(cursor,5)
 make("UIStroke",cursor,{Color=Color3.new(1,1,1),Thickness=2})
 local preview=make("Frame",holder,{Name="Preview",Position=UDim2.fromOffset(222,16),Size=UDim2.fromOffset(70,70),BorderSizePixel=0}) round(preview,10)
 local hex=label(holder,"",60) hex.Position=UDim2.fromOffset(220,94) hex.Size=UDim2.fromOffset(190,60)
 local bar=make("Frame",holder,{Name="Brightness",Position=UDim2.fromOffset(8,218),Size=UDim2.new(1,-24,0,22),BackgroundColor3=Color3.new(1,1,1),BorderSizePixel=0,Active=true}) round(bar,5)
 local gradient=make("UIGradient",bar,{Color=ColorSequence.new(Color3.new(0,0,0),Color3.fromHSV(hue,saturation,1))})
 local marker=make("Frame",bar,{Size=UDim2.fromOffset(3,26),AnchorPoint=Vector2.new(0.5,0.5),BackgroundColor3=Color3.new(1,1,1),BorderSizePixel=0,ZIndex=5})
 local activePointer local mode local wasScrolling local lastRenderedColor
 local function render()
 local c=Color3.fromRGB(X.themeR,X.themeG,X.themeB)
 if c==lastRenderedColor then return end
 lastRenderedColor=c
 hue,saturation,value=c:ToHSV()
 cursor.Position=UDim2.fromScale(0.5+math.cos(hue*2*math.pi)*saturation*0.5,0.5+math.sin(hue*2*math.pi)*saturation*0.5)
 preview.BackgroundColor3=c
 hex.Text=string.format("#%02X%02X%02X\nBrightness / ความสว่าง",X.themeR,X.themeG,X.themeB)
 gradient.Color=ColorSequence.new(Color3.new(0,0,0),Color3.fromHSV(hue,saturation,1))
 marker.Position=UDim2.fromScale(value,0.5)
 end
 local function update(input)
 local p=Vector2.new(input.Position.X,input.Position.Y)
 if not gui.IgnoreGuiInset then local inset=game:GetService("GuiService"):GetGuiInset() p-=inset end
 if mode=="wheel" then
 local size=wheel.AbsoluteSize local centre=wheel.AbsolutePosition+size/2
 local delta=p-centre
 hue=(math.atan2(delta.Y,delta.X)/(2*math.pi))%1 saturation=math.clamp(delta.Magnitude/(size.X/2),0,1)
 else value=math.clamp((p.X-bar.AbsolutePosition.X)/bar.AbsoluteSize.X,0,1) end
 local c=Color3.fromHSV(hue,saturation,value)
 X.themeR=math.round(c.R*255) X.themeG=math.round(c.G*255) X.themeB=math.round(c.B*255)
 if S.applyUITheme then S.applyUITheme(c) end
 -- Keep hue when brightness is zero instead of converting black back to HSV.
 preview.BackgroundColor3=c cursor.Position=UDim2.fromScale(0.5+math.cos(hue*2*math.pi)*saturation*0.5,0.5+math.sin(hue*2*math.pi)*saturation*0.5)
 gradient.Color=ColorSequence.new(Color3.new(0,0,0),Color3.fromHSV(hue,saturation,1)) marker.Position=UDim2.fromScale(value,0.5)
 hex.Text=string.format("#%02X%02X%02X\nBrightness / ความสว่าง",X.themeR,X.themeG,X.themeB)
 end
 for _,entry in {{wheel,"wheel"},{bar,"brightness"}} do
 table.insert(connections,entry[1].InputBegan:Connect(function(input)
 if activePointer or (input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch) then return end
 activePointer=input mode=entry[2] wasScrolling=langues.ScrollingEnabled langues.ScrollingEnabled=false update(input)
 end))
 end
 table.insert(connections,UIS.InputChanged:Connect(function(input)
 if activePointer and (input==activePointer or (activePointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement)) then update(input) end
 end))
 table.insert(connections,UIS.InputEnded:Connect(function(input)
 if activePointer and (input==activePointer or (activePointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then update(input) activePointer=nil langues.ScrollingEnabled=wasScrolling end
 end))
 table.insert(pageRefresh,function()if not activePointer then render() end end) render()
end



