end)
S.styleSelection=function(target,selected)
 local background=selected and Color3.fromRGB(72,79,99) or Color3.fromRGB(29,33,44)
 if target.BackgroundColor3~=background then target.BackgroundColor3=background end
 local function linear(v)return v<=0.04045 and v/12.92 or ((v+0.055)/1.055)^2.4 end
 local l=0.2126*linear(background.R)+0.7152*linear(background.G)+0.0722*linear(background.B)
 target.TextColor3=(l+0.05)/0.05>=1.05/(l+0.05) and Color3.fromRGB(12,15,20) or Color3.fromRGB(244,248,252)
end
