local function choiceList(title,names,selectedKey)
 label(farm,title,26)
 local row=make("Frame",farm,{Name="FarmChoices_"..selectedKey,Size=UDim2.new(1,-6,0,math.ceil(#names/3)*30),BackgroundTransparency=1})
 for i,name in names do
 local b=make("TextButton",row,{Name=name,Size=UDim2.new(1/3,-5,0,27),Position=UDim2.new((i-1)%3/3,0,0,math.floor((i-1)/3)*30),TextSize=10,Font=Enum.Font.Gotham,TextColor3=blue,BackgroundColor3=Color3.fromRGB(17,28,42),BorderSizePixel=0}) round(b,4)
 themeTargets[b]=nil
 local function refresh()
 local enabled=config[selectedKey][name]~=false
 local h,s,v=blue:ToHSV()
 local bright=Color3.fromHSV(h,s,math.max(0.65,v))
 b.Text=name
 b.BackgroundColor3=enabled and bright or Color3.fromRGB(36,38,44)
 if enabled then
 local function linear(n)return n<=0.04045 and n/12.92 or ((n+0.055)/1.055)^2.4 end
 local l=0.2126*linear(bright.R)+0.7152*linear(bright.G)+0.0722*linear(bright.B)
 b.TextColor3=(l+0.05)/0.05>=1.05/(l+0.05) and Color3.fromRGB(12,15,20) or Color3.fromRGB(248,250,252)
 else b.TextColor3=Color3.fromRGB(143,147,157) end
 end
 b.Activated:Connect(function() config[selectedKey][name]=config[selectedKey][name]==false refresh() end) refresh() table.insert(pageRefresh,refresh)
 end
end
