local selectedUnit=label(training,"ยังไม่ได้เลือก Striker",52)
S.refreshSelectedUnit=function()
 if not selectedUnit.Parent then return end
 local data=D.GetData()
 local u=X.unit and data and data.PlayerUnits and data.PlayerUnits[X.unit]
 local text=u and (tostring(u.PlayerUnitName).." • Lv."..tostring(u.Level or 1).." • "..tostring(u.Grade or "F").." / "..tostring(u.Trait or "None")) or "ยังไม่ได้เลือก Striker สำรอง"
 if selectedUnit.Text~=text then selectedUnit.Text=text end
 S.trainingLabelText=text
end
S.refreshSelectedUnit()
do
 for _,name in {"PlayerUnitGradeChanged","PlayerUnitGradePityChanged","PlayerUnitTraitChanged","PlayerUnitTraitPityChanged","PlayerUnitLevelChanged","PlayerUnitBallSkinChanged"} do
  if D.Signals[name] then table.insert(connections,D.Signals[name]:Connect(function(id)
   if id==X.unit then S.refreshSelectedUnit() task.defer(function() if S.running then S.refreshSelectedUnit() end end) end
  end)) end
 end
 task.spawn(function()
  while S.running and selectedUnit.Parent do
   S.refreshSelectedUnit()
   task.wait(0.15)
  end
 end)
end
