 local list=make("ScrollingFrame",group,{Name="TrainingQueueList",Size=UDim2.new(1,0,0,260),CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=3})
 make("UIListLayout",list,{Padding=UDim.new(0,7),SortOrder=Enum.SortOrder.LayoutOrder})
 local cards={}
 local function find(id)for i,e in X.trainingQueue do if e.id==id then return i end end end
 local function summary(map)local names={} for name,on in map do if on then table.insert(names,name) end end table.sort(names) return table.concat(names,", ") end
 table.insert(pageRefresh,function()
  local q=S.trainingQueueState
  local selected=X.unit and D.GetData().PlayerUnits[X.unit]
  info.Text=(q and q.status or "Queue empty").." • "..#X.trainingQueue.."\nSelected: "..(selected and selected.PlayerUnitName.." • "..tostring(selected.Variant or "Normal") or "None selected")
  local seen={}
  for i,entry in X.trainingQueue do
   local id=entry.id seen[id]=true local card=cards[id]
   if not card then
    local frame=make("Frame",list,{Size=UDim2.new(1,-6,0,104),BackgroundColor3=Color3.fromRGB(27,30,41),BorderSizePixel=0}) round(frame,8)
    local title=label(frame,"",66) title.Position=UDim2.fromOffset(9,2) title.Size=UDim2.new(1,-18,0,66) title.TextSize=12
    local up=action(frame,"↑",function()local index=find(id) if index and S.moveTrainingQueue then S.moveTrainingQueue(index,-1) end end) up.Position=UDim2.fromOffset(8,70) up.Size=UDim2.fromOffset(42,27)
    local down=action(frame,"↓",function()local index=find(id) if index and S.moveTrainingQueue then S.moveTrainingQueue(index,1) end end) down.Position=UDim2.fromOffset(56,70) down.Size=UDim2.fromOffset(42,27)
    local remove=action(frame,"Remove",function()local index=find(id) if index and S.removeTrainingQueue then S.removeTrainingQueue(index) end end) remove.Position=UDim2.fromOffset(105,70) remove.Size=UDim2.fromOffset(110,27)
    card={frame=frame,title=title} cards[id]=card
   end
   local u=D.GetData().PlayerUnits[id]
   card.frame.LayoutOrder=i
   card.title.Text=i..". "..(u and u.PlayerUnitName or "Unavailable").."\nGrade: "..summary(entry.grades).."\nTrait: "..summary(entry.traits)
  end
  for id,card in cards do if not seen[id] then card.frame:Destroy() cards[id]=nil end end
 end)
end)() end

