local tweenSpeedField=make("Frame",collectModes,{Name="TweenSpeed",Position=UDim2.fromOffset(0,44),Size=UDim2.new(1,-6,0,82),BackgroundTransparency=1})
do
 local title=label(tweenSpeedField,"",30) title.Size=UDim2.new(1,-8,0,30)
 local track=make("Frame",tweenSpeedField,{Name="SpeedSlider",Position=UDim2.fromOffset(8,44),Size=UDim2.new(1,-24,0,12),BackgroundColor3=Color3.fromRGB(60,62,69),BorderSizePixel=0,Active=true}) round(track,6)
 local fill=make("Frame",track,{Name="Fill",Size=UDim2.fromScale(0,1),BackgroundColor3=blue,BorderSizePixel=0}) round(fill,6)
 local knob=make("Frame",track,{Name="Knob",AnchorPoint=Vector2.new(0.5,0.5),Size=UDim2.fromOffset(19,19),BackgroundColor3=Color3.fromRGB(245,247,250),BorderSizePixel=0,ZIndex=3}) round(knob,10)
 local help=label(tweenSpeedField,"Drag / Scroll • 5–2000 studs/s",22) help.Position=UDim2.fromOffset(8,61) help.TextSize=10
 local pointer local hovering=false
 local function render()
 local speed=math.clamp(tonumber(X.collectTweenSpeed) or 600,5,2000)
 local fraction=(speed-5)/1995
 fill.Size=UDim2.fromScale(fraction,1) knob.Position=UDim2.fromScale(fraction,0.5)
 title.Text="Fast Tween • "..math.round(speed).." studs/s"
 end
 local function update(input)
 X.collectTweenSpeed=math.round(5+math.clamp((input.Position.X-track.AbsolutePosition.X)/track.AbsoluteSize.X,0,1)*1995) render()
 end
 table.insert(connections,tweenSpeedField.MouseEnter:Connect(function()hovering=true S.travelPage.ScrollingEnabled=false end))
 table.insert(connections,tweenSpeedField.MouseLeave:Connect(function()hovering=false if not pointer then S.travelPage.ScrollingEnabled=true end end))
 table.insert(connections,track.InputBegan:Connect(function(input)
 if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then pointer=input S.travelPage.ScrollingEnabled=false update(input) end
 end))
 table.insert(connections,UIS.InputChanged:Connect(function(input)
 if hovering and tweenSpeedField.Visible and pages.Travel.Visible and input.UserInputType==Enum.UserInputType.MouseWheel then
 X.collectTweenSpeed=math.clamp(math.round(X.collectTweenSpeed+input.Position.Z*25),5,2000) render()
 elseif pointer and (input==pointer or (pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement)) then update(input) end
 end))
 table.insert(connections,UIS.InputEnded:Connect(function(input)
 if pointer and (input==pointer or (pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then pointer=nil S.travelPage.ScrollingEnabled=not hovering end
 end))
 table.insert(pageRefresh,function()
 render() if not tweenSpeedField.Visible or not pages.Travel.Visible then hovering=false pointer=nil S.travelPage.ScrollingEnabled=true end
 end) render()
end
