     local status=make("TextLabel",button,{Position=UDim2.new(1,-56,0,13),Size=UDim2.fromOffset(44,23),Text="",Font=Enum.Font.GothamBold,TextSize=10,BorderSizePixel=0,ZIndex=44}) round(status,7) themeTargets[status]=nil
     state.rows[id]={key=key,name=name,button=button,stroke=stroke,description=info,switch=status}
     table.insert(connections,button.Activated:Connect(function()X[key][name]=not (X[key][name]~=false) state.render()end))
    end
   end
   overlay.Visible=true state.render()
  end
  S.closeEventSelector=closePopup
  table.insert(connections,close.Activated:Connect(closePopup))
  table.insert(connections,done.Activated:Connect(closePopup))
