do (function()
 S.uiGroups={} S.uiCoverage={before=0,after=0,pages=0}
 local names={Overview="Home",Farm="Farm & Team",Boosts="Boosts & Processing",Market="Inventory & Shop",Training="Grade & Trait",Tower="Tower",Events="Halloween & World",Travel="Movement",Setting="Settings"}
 S.uiPageNames=names
 local order={Overview={"Live dashboard","Activity & diagnostics"},Farm={"Team management","Buying filters","Locker automation"},Boosts={"Polisher","Potion permissions"},Market={"Inventory & Shop"},Training={"Selected Striker","Training queue","Roll controls","Grade & Trait targets"},Tower={"Stage & battle","Team selection"},Events={"Tournament","World collection","Collection filters","Missions"},Travel={"Movement mode","Route settings","Diagnostics"},Setting={"Appearance","Language","Window & input","Configuration"}}
 local function content(obj)
  local parts={obj.Name}
  if obj:IsA("TextLabel") or obj:IsA("TextButton") then parts[#parts+1]=obj.Text end
  for _,v in obj:QueryDescendants("TextLabel, TextBox") do parts[#parts+1]=v.Name if v:IsA("TextLabel") then parts[#parts+1]=v.Text end end
  return table.concat(parts," "):lower()
 end
 local function category(page,obj,previous)
  local key=obj.Name:lower() local text=content(obj)
  if page=="Training" and key=="trainingqueuecontrols" then return "Training queue" end
  if page=="Training" and (key=="selectbestbasestriker" or key=="selectbasestriker" or key=="basetrainingchoices") then return "Selected Striker" end
  if page=="Overview" then return obj.Name=="FeatureStatus" and "Activity & diagnostics" or "Live dashboard" end
  if page=="Farm" then
   if key=="variantfilter" or key:find("farmchoices") or text=="variants" or text=="lockers" then return "Buying filters" end
   if key=="autoequip" or key=="strikerupgrade" or key=="sellsparestrikers" or key=="upgrades" then return "Team management" end
   if key=="stopatfilter" or key=="autobuy" or key=="spawnbestlocker" or key=="autoselllockers" or key=="fastopen" or key=="autosellcrates" then return "Locker automation" end
  elseif page=="Boosts" then
   if key=="polisher" or key=="autosellpolishedcrates" or key=="polisherpickupdelay" or key=="polishergoldenhouronly" then return "Polisher" end
   return "Potion permissions"
  elseif page=="Market" then
   return "Inventory & Shop"
  elseif page=="Training" then
   if key=="grade" or key=="trait" or key=="norolllimit" or text:find("rolllimit") or text:find("gradecash") then return "Roll controls" end
   if key=="bluetooth" or key=="trainingtp" or text:find("station") then return "Roll controls" end
   if text:find("trait") and key~="textlabel" then return "Grade & Trait targets" end
   if text:find("grade") and key~="textlabel" then return "Grade & Trait targets" end
  elseif page=="Tower" then
   if key=="manualtowerteam" or key=="towerbest" then return "Team selection" end
   return "Stage & battle"
  elseif page=="Events" then
    if key=="autotournament" or key:find("^tournament") then return "Tournament" end
   if key=="automissions" or key:find("^mission") then return "Missions" end
   if key:find("eventcategory") then return "Collection filters" end
   if key=="esp" or key=="events" or key=="mapcollect" or key=="autoobby" then return "World collection" end
  elseif page=="Travel" then
   if key:find("diagnostic") or text:find("diagnostic") or text:find("paused travel") then return "Diagnostics" end
   if key=="toggleadvancedtravelsettings" or text:find("interval") or text:find("speed") or text:find("return") then return "Route settings" end
   return "Movement mode"
  elseif page=="Setting" then
   if key=="thai" or key=="english" or key=="currentlanguage" or text:find("language") then return "Language" end
   if key=="configstatus" or key=="resetconfig" or text:find("config") then return "Configuration" end
   if key=="binduikey" or key=="showicon" or key=="antiafk" or text:find("fps") or text:find("window") then return "Window & input" end
   return "Appearance"
  end
  return previous or order[page][1]
 end
 for pageName,page in pages do
  S.uiCoverage.pages+=1
  local entries=S.uiPageEntries[page] or {}
  local buckets={} local previous
  for _,obj in entries do
   if obj.Parent then
    local name=category(pageName,obj,previous) previous=name
    buckets[name]=buckets[name] or {} table.insert(buckets[name],obj) S.uiCoverage.before+=1
   end
  end
  local layout=page:FindFirstChildOfClass("UIListLayout") layout.FillDirection=Enum.FillDirection.Vertical layout.Padding=UDim.new(0,12)
  local groups={} S.uiGroups[pageName]=groups
  for index,name in order[pageName] do
   local objects=buckets[name]
   if objects and #objects>0 then
    local card=Instance.new("Frame") card.Name="Group_"..index card.LayoutOrder=index card.Size=UDim2.new(1,-6,0,0) card.AutomaticSize=Enum.AutomaticSize.Y card.BackgroundColor3=Color3.fromRGB(21,22,38) card.BackgroundTransparency=0.14 card.BorderSizePixel=0 card.Parent=page
    round(card,12) make("UIStroke",card,{Color=Color3.fromRGB(72,67,101),Transparency=0.45,Thickness=1})
    make("UIListLayout",card,{Padding=UDim.new(0,0),SortOrder=Enum.SortOrder.LayoutOrder})
    local head=make("TextButton",card,{Name="AccordionHeader",LayoutOrder=0,Size=UDim2.new(1,0,0,48),BackgroundTransparency=1,Text="",AutoButtonColor=false})
    local title=label(head,name,26) title.Font=Enum.Font.BuilderSansBold title.TextSize=15 title.Position=UDim2.fromOffset(17,10) title.Size=UDim2.new(1,-140,0,26) title.TextColor3=Color3.fromRGB(235,232,249)
    local count=label(head,#objects.." controls",22) count.Position=UDim2.new(1,-118,0,12) count.Size=UDim2.fromOffset(80,22) count.TextSize=11 count.TextColor3=Color3.fromRGB(148,147,174)
    local arrow=label(head,"−",24) arrow.Position=UDim2.new(1,-32,0,10) arrow.Size=UDim2.fromOffset(20,24) arrow.TextSize=19
    local body=make("Frame",card,{Name="Content",LayoutOrder=1,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,Visible=index==1})
    make("UIListLayout",body,{Padding=UDim.new(0,7),SortOrder=Enum.SortOrder.LayoutOrder})
    make("UIPadding",body,{PaddingLeft=UDim.new(0,12),PaddingRight=UDim.new(0,12),PaddingBottom=UDim.new(0,12)})
    local group={body=body,header=head,objects=objects,expanded=index==1,card=card,name=name,baseline={}}
    table.insert(groups,group)
    for i,obj in objects do obj.Parent=body obj.LayoutOrder=i group.baseline[obj]=obj.Visible S.uiCoverage.after+=1 end
    head.Activated:Connect(function()group.expanded=not group.expanded body.Visible=group.expanded arrow.Text=group.expanded and "−" or "+" end)
    arrow.Text=group.expanded and "−" or "+"
   end
  end
  for _,column in pageColumns[page] do if typeof(column)=="Instance" then column:Destroy() end end
  pageColumns[page]=nil
 end
 local search=make("TextBox",panel,{Name="FeatureSearch",Position=UDim2.fromOffset(430,66),Size=UDim2.new(1,-450,0,32),BackgroundColor3=Color3.fromRGB(23,23,40),BackgroundTransparency=0.2,Text="",PlaceholderText="Search features…",ClearTextOnFocus=false,TextSize=13,TextColor3=Color3.fromRGB(229,226,243),PlaceholderColor3=Color3.fromRGB(136,135,160),Font=Enum.Font.BuilderSans,BorderSizePixel=0}) round(search,8)
