 local function filter()
  local term=search.Text:lower()
  for pageName,groups in S.uiGroups do
   for _,group in groups do
    local matches=0
    for _,obj in group.objects do
     if obj.Parent then
      if term=="" then obj.Visible=group.baseline[obj]~=false
      else obj.Visible=content(obj):find(term,1,true)~=nil end
      if obj.Visible then matches+=1 end
     end
    end
    group.card.Visible=term=="" or matches>0 group.body.Visible=term~="" or group.expanded
   end
  end
 end
