  local value=label(tile,"—",38) value.Position=UDim2.fromOffset(12,38) value.Size=UDim2.new(1,-20,0,38) value.Font=Enum.Font.BuilderSansBold value.TextSize=25 value.TextColor3=Color3.fromRGB(245,241,255) metrics[i]=value
 end
