-- Debounced auto-save with stable fingerprints and a last-good backup.
do
local lastFingerprint local lastGoodRaw
local function copySettings()
 local options={}
 for key,kind in optionKinds do
 local value=X[key]
 if kind=="table" and type(value)=="table" then
 local map={}
 if key=="trainingQueue" then for _,entry in value do table.insert(map,{id=entry.id,grades=table.clone(entry.grades),traits=table.clone(entry.traits)}) end
 elseif key=="towerTeam" then for slot=1,require(RS.Shared.Constants).InfinityTowerUnitSlots do if type(value[slot])=="string" then map[tostring(slot)]=value[slot] end end
 else for k,v in value do if type(k)=="string" and type(v)=="boolean" then map[k]=v end end end
 options[key]=map
 elseif kind=="boolean" and type(value)=="boolean" or kind=="string" and type(value)=="string" or kind=="number" and validNumber(value) then options[key]=value end
 end
 local conveyor={}
 for _,key in {"autoBuy","spawnBestLocker","warnings","variantFilter","autoSellLockers"} do conveyor[key]=config[key] end
 conveyor.variants=table.clone(config.variants) conveyor.boxes=table.clone(config.boxes)
 return {schema=1,freshStartVersion=1,cleanupPending=S.legacyCleanup and S.legacyCleanup.pending or false,placeId=game.PlaceId,userId=P.UserId,deviceId=S.device.id,enabled=S.enabled,language=G.BlueFarmLanguage or "th",options=options,conveyor=conveyor,ui={x=panel.Position.X.Offset,y=panel.Position.Y.Offset,minimized=minimized,width=panel.Size.X.Offset,height=panel.Size.Y.Offset}}
end
local function canonical(value)
 if type(value)~="table" then return http:JSONEncode(value) end
 local keys={} for key in value do table.insert(keys,key) end table.sort(keys,function(a,b)return tostring(a)<tostring(b)end)
 local rows={} for _,key in keys do table.insert(rows,http:JSONEncode(tostring(key))..":"..canonical(value[key])) end
 return "{"..table.concat(rows,",").."}"
end
S.saveConfig=function()
 if G.BlueFarm~=S then return false end
 local ok,result=pcall(function()
 local snapshot=copySettings()
 local fingerprint=canonical(snapshot)
 if fingerprint==lastFingerprint then return true end
 G.BlueFarmConfigSessions[configPath]=snapshot
 if type(writefile)~="function" then
 lastFingerprint=fingerprint configState.status="Config: session only" return true
 end
 local raw=http:JSONEncode(snapshot)
 -- Retain the previous valid content before updating the primary file.
 if not lastGoodRaw and type(readfile)=="function" then
 local readOK,previous=pcall(readfile,configPath)
 if readOK and type(previous)=="string" and #previous<250000 then
 local parseOK,parsed=pcall(function()return http:JSONDecode(previous)end)
 if parseOK and validEnvelope(parsed) then lastGoodRaw=previous end
 end
 end
 -- Last-good settings stay in memory.
 writefile(configPath,raw)
 lastGoodRaw=raw lastFingerprint=fingerprint configState.saves+=1 configState.lastError="" configState.status="Config: saved"
 return true
 end)
 if not ok then configState.lastError=tostring(result) configState.status="Config: save failed" return false end
 return result
end
table.insert(connections,gui.Destroying:Connect(function()S.saveConfig()end))
S.resetConfig=function()
 if G.BlueFarm~=S or not S.running then return false end
 S.enabled=false
 if S.stopCollectionTravel then pcall(S.stopCollectionTravel) end
 for key in X do X[key]=nil end
 for key,value in S.defaultSettings.options do X[key]=type(value)=="table" and table.clone(value) or value end
 for key in config do config[key]=nil end
 for key,value in S.defaultSettings.conveyor do config[key]=type(value)=="table" and table.clone(value) or value end
 X.fastTweenConfigured=true X.iconVisibilityConfigured=true
 for key in S.potionConsent do S.potionConsent[key]=false X[key]=false end
 table.clear(S.reservedUnits) table.clear(S.towerProtected)
 if S.restoreFPSTextures then S.restoreFPSTextures() end
 if S.trainingStops then table.clear(S.trainingStops) end
 bindingKey=false
 setLanguage("en")
 S.applyUITheme(Color3.fromRGB(X.themeR,X.themeG,X.themeB))
 panel.Position=S.defaultPanelPosition
 setMinimized(false)
 for _,refresh in pageRefresh do refresh() end
 if S.refreshSelectedUnit then S.refreshSelectedUnit() end
 S.enabled=true
 if S.refreshMasterStatus then S.refreshMasterStatus() end
 lastFingerprint=nil
 local saved=S.saveConfig()
 -- Reset both copies so the backup cannot restore old preferences.
 -- No backup file is created.
 return saved
end
S.saveConfig()
task.spawn(function()
 while S.running and gui.Parent do task.wait(S.mobileLite and 10 or 0.75) if S.running and gui.Parent then S.saveConfig() end end
end)
end


return UIS,connections,blue,make,label,panel,pageRefresh,home,farm,market,tower,events,configInfo,stats,detail,conveyorBuyRow,variants,boxes,potionInfo,skinBuyRow,stockInfo,marketInfo,selectedUnit,trainingInfo,towerNames,towerChoice,towerSlotButtons,towerInfo,eventInfo,hint,setMinimized
end)()

local function safe(f,scope)
 local ok,err=pcall(f) if not ok then
 if scope=="Base" and S.restoreDisplacedLocker then pcall(S.restoreDisplacedLocker) end
 S.errors+=1 S.lastError=tostring(err)
 end
end
-- Compare every striker at level 1, keeping variant, grade and trait bonuses.
local function unitBase(unit)
 return U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unit.PlayerUnitName,PlayerUnitVariant=unit.Variant,PlayerUnitLevel=1,PlayerUnitGrade=unit.Grade,PlayerUnitTrait=unit.Trait,PlayerUnitBallSkin=unit.BallSkin})
end
local function partBase(part)
 local a=part:GetAttributes()
 return U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=a.PlayerUnitName,PlayerUnitVariant=a.PlayerUnitVariant,PlayerUnitLevel=1,PlayerUnitGrade=a.PlayerUnitGrade,PlayerUnitTrait=a.PlayerUnitTrait,PlayerUnitBallSkin=a.PlayerUnitBallSkin})
end
local objectCache={}
local failedPlacement={}
local function canPlace(id) return not S.reservedUnits[id] and not S.tournamentProtected[id] and not S.trainingQueueProtected[id] and G.BlueFarmSpareSale.pending~=id and os.clock()>=(failedPlacement[id] or 0) end
S.autoEquipScore=function(unit)
 return U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unit.PlayerUnitName,PlayerUnitVariant=unit.Variant,PlayerUnitLevel=unit.Level or 1,PlayerUnitGrade=unit.Grade,PlayerUnitTrait=unit.Trait,PlayerUnitBallSkin=unit.BallSkin})
end
S.autoEquipBetter=function(a,al,b,bl)
 local tolerance=math.max(1,math.abs(a),math.abs(b))*1e-7
 return a>b+tolerance
end
S.bestAutoEquipSpare=function()
 local best
 for id,unit in D.GetData().PlayerUnits do
 if not unit.Equipped and canPlace(id) then
 local score=S.autoEquipScore(unit) local level=unit.Level or 1
 if not best or S.autoEquipBetter(score,level,best.score,best.level) or (score==best.score and (level>best.level or (level==best.level and id<best.id))) then best={id=id,score=score,level=level} end
 end
 end
 return best
end
S.autoEquipOccupant=function(part)
 local a=part:GetAttributes() local chosen
 for id,unit in D.GetData().PlayerUnits do
 if unit.Equipped and unit.PlayerUnitName==a.PlayerUnitName and (unit.Variant or "Normal")== (a.PlayerUnitVariant or "Normal") and (unit.Level or 1)==(a.PlayerUnitLevel or 1) and unit.Grade==a.PlayerUnitGrade and unit.Trait==a.PlayerUnitTrait and unit.BallSkin==a.PlayerUnitBallSkin then
 -- Favorite prevents selling, but does not lock a unit into its base slot.
 if S.reservedUnits[id] or S.tournamentProtected[id] or S.trainingQueueProtected[id] then return id,true end
 if not chosen or id<chosen then chosen=id end
 end
 end
 return chosen,false
end
S.canSellLocker=function(name,variant)
 if B.IsBoxFavorited(P,name,variant) then return false end
 local rows={}
 for boxName,variants in D.GetData().Inventory.Boxes do for var,entry in variants do
 if (entry.Amount or 0)>0 and BL[boxName] then
 local score=0
 for unitName in BL[boxName].PlayerUnits do score=math.max(score,U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unitName,PlayerUnitVariant=var,PlayerUnitLevel=1})) end
 table.insert(rows,{name=boxName,variant=var,amount=entry.Amount,score=score})
 end end end
 table.sort(rows,function(a,b)if a.score~=b.score then return a.score>b.score end if a.name~=b.name then return a.name<b.name end return a.variant<b.variant end)
 local remaining=config.keepLockers
 for _,entry in rows do
 local keep=math.min(remaining,entry.amount) remaining-=keep
 if entry.name==name and entry.variant==variant then return entry.amount>keep end
 end
 return false
end
S.restoreDisplacedLocker=function()
 local displaced=S.lockerDisplaced
 if not displaced then return end
 local original=D.GetData().PlayerUnits[displaced.id]
 if S.running and displaced.part.Parent and not displaced.part:GetAttribute("Type") and original and not original.Equipped then R.PlacePlayerUnitOnDropper:FireServer(displaced.part,displaced.id) end
 S.lockerDisplaced=nil
end
local timers={}
local function due(key,interval)
 local now=os.clock()
 if now<(timers[key] or 0) then return false end
 timers[key]=now+interval
 return true
end
local function objects(keys,plot)
 local key=table.concat(keys,",")
 local cached=objectCache[key]
 if cached and cached.plot==plot and os.clock()-cached.at<2 then return cached.items end
 local isDropper=keys[2]=="_activeHandlerType"
 local searchKeys=isDropper and {"Part","IsClientOwnedPlot"} or keys
 local seen={}
 local out={} for _,v in S.cachedHandlerTables(searchKeys) do
 if typeof(v.Part)=="Instance" and v.Part:IsDescendantOf(plot) and (not isDropper or type(v._computeAction)=="function") and not seen[v.Part] then
 seen[v.Part]=true table.insert(out,v)
 end end
 objectCache[key]={plot=plot,at=os.clock(),items=out}
 return out
end
-- Conveyor requests do not depend on the proximity UI's active client object.
task.spawn(function()
 local pending local completedKey local attemptKey local attempts=0
 local nextPurchaseAt=0 local nextRollAt=0 local observedPart local observedRoll
 local ownsLock=false
 local function release()
 if ownsLock then S.releaseInventory("Conveyor") ownsLock=false end
 end
 local function amount(name,var)
 local boxes=D.GetData().Inventory.Boxes local entry=boxes[name] and boxes[name][var]
 return entry and entry.Amount or 0
 end
 S.conveyorDiagnostics={phase="Starting"}
 local function check()
 if pending then
 S.conveyorDiagnostics.phase="Confirming purchase"
 if amount(pending.name,pending.variant)>pending.before then
 S.bought+=1 completedKey=pending.key
 S.lastLockerBought={name=pending.name,variant=pending.variant}
 S.buyStatus="Bought "..pending.variant.." "..pending.name
 pending=nil release()
 elseif os.clock()<pending.deadline then S.buyStatus="Confirming purchase • "..pending.variant.." "..pending.name.." • Attempt "..attempts return
 else
 S.buyStatus="Purchase unconfirmed; retrying after cooldown"
 pending=nil release() nextPurchaseAt=os.clock()+1.5
 end
 end
 if not S.running or not S.enabled then return end
 
 if not config.autoBuy then S.buyStatus="Auto Buy is OFF" return end
 if config.autoSellLockers then
  local total=0
  for _,variants in D.GetData().Inventory.Boxes do for _,entry in variants do total+=entry.Amount or 0 end end
  if total>config.keepLockers+3 then S.lockerBackpressure=true end
  if total<=config.keepLockers+1 then S.lockerBackpressure=false end
  if S.lockerBackpressure then
   local sellable=false
   for name,variants in D.GetData().Inventory.Boxes do
    for variant in variants do if S.canSellLocker(name,variant) then sellable=true break end end
    if sellable then break end
   end
   if not sellable then S.lockerBackpressure=false end
  end
  if S.lockerSale.pending or S.lockerBackpressure then S.buyStatus="Clearing surplus lockers before buying more" return end
 else S.lockerBackpressure=false end
 local home=workspace.Map.PlotModels:FindFirstChild(P.Name)
 local systems=home and home:FindFirstChild("Systems") local station=systems and systems:FindFirstChild("RollStation")
 local part=station and station:FindFirstChild("ConveyorPart")
 if not part then S.buyStatus="Waiting for your conveyor" return end
 local id=part:GetAttribute("RollId")
 if part~=observedPart or id~=observedRoll then
 observedPart=part observedRoll=id nextRollAt=os.clock()+math.max(0.2,B.GetConveyorRollCooldown(P))
 end
 local name=part:GetAttribute("BoxName") local var=part:GetAttribute("Variant") or "Normal"
 local key=tostring(id)..":"..tostring(name)..":"..var
 local selected=name and BL[name] and config.boxes[name]~=false and (not config.variantFilter or config.variants[var]~=false)
 S.conveyorFilterHold=X.stopAtFilter and selected and completedKey~=key and {key=key,name=name,variant=var} or nil
 if not selected then S.buyStatus="Skipped by filters • Select allowed lockers / variants in Farm" end
 if attemptKey~=key then attemptKey=key attempts=0 nextPurchaseAt=0 end
 S.conveyorDiagnostics.name=name S.conveyorDiagnostics.variant=var S.conveyorDiagnostics.rollId=id
 S.conveyorDiagnostics.selected=selected==true S.conveyorDiagnostics.stopAtFilter=X.stopAtFilter
 S.conveyorDiagnostics.lockers=B.GetTotalBoxInventoryAmount(P) S.conveyorDiagnostics.lockerMax=B.GetMaxBoxInventorySpace(P)
 S.conveyorDiagnostics.total=S.inventoryCapacity().count S.conveyorDiagnostics.totalMax=S.inventoryCapacity().maximum
 S.conveyorDiagnostics.cash=D.GetData().Currency.Cash or 0
 S.conveyorDiagnostics.price=selected and B.GetConveyorBoxPrice(name,var) or nil
 S.conveyorDiagnostics.phase="Checking roll"

 if not B.HasBoxInventorySpace(P,1) then
  S.buyStatus="Locker storage full • "..B.GetTotalBoxInventoryAmount(P).." / "..B.GetMaxBoxInventorySpace(P).." • Open or place a locker to continue"
  return
 end
 if S.inventoryCapacity().free<1 then
  local capacity=S.inventoryCapacity()
  S.buyStatus="Total inventory full • "..capacity.count.." / "..capacity.maximum.." • Resumes when space is available"
  return
 end
 if selected and completedKey~=key then
 local price=B.GetConveyorBoxPrice(name,var)
 if price<=(D.GetData().Currency.Cash or 0) then
 if S.baseBusy then S.buyStatus="Waiting for base operations" return end
 if os.clock()<nextPurchaseAt then return end
 if not S.acquireInventory("Conveyor") then S.buyStatus="Queued for inventory" return end
 attempts+=1 ownsLock=true
 pending={name=name,variant=var,key=key,before=amount(name,var),deadline=os.clock()+2.5}
 S.buyStatus="Buying "..var.." "..name
 R.PurchaseConveyorRoll:FireServer(name,var,price)
 return
 else
  S.conveyorDiagnostics.phase="Insufficient cash"
  S.buyStatus="Not enough cash • "..var.." "..name.." • Have "..tostring(D.GetData().Currency.Cash or 0).." / Need "..tostring(price)
  if S.conveyorFilterHold then return end
 end
 end
 if S.conveyorFilterHold then
  S.conveyorDiagnostics.phase="Waiting for selected purchase"
  S.buyStatus="Filter match • Waiting to buy "..var.." "..name
  return
 end
 if P:GetAttribute("TutorialConveyorLock") then S.buyStatus="Finish the conveyor tutorial first" return end
 local untilTime=part:GetAttribute("RollCooldownUntil") or 0
 if workspace:GetServerTimeNow()<untilTime or os.clock()<nextRollAt then return end
 local warning=require(RS.Client.Core.Gui.WarningNewBoxGuiClient)
 if warning.IsOpen() then warning.Close() end
 nextRollAt=os.clock()+math.max(1,B.GetConveyorRollCooldown(P))
 S.conveyorDiagnostics.phase="Requesting next roll"
 S.buyStatus="Rolling • "..(selected and "Previous purchase complete / unaffordable item skipped" or "Current locker excluded by filters")
 R.NewRequestConveyorRoll:FireServer()
 S.conveyorRollRequests=(S.conveyorRollRequests or 0)+1
 if not name then S.buyStatus="Spawning conveyor locker" end
 end
 S.checkConveyor=check
 while S.running and gui.Parent do
 local ok,err=pcall(check)
