-- Discover every cash upgrade, including entries hidden from the general menu.
task.spawn(function()
 local retryAt={}
 local preferred={"PlayerUnitExpansion","Luck","ConveyorLuck","OpenTimeBoost","CrateCashBoost","WalkSpeed","CratePolisherUnlock","CratePolisher"}
 local names={} local seen={}
 for _,name in preferred do if UL[name] then table.insert(names,name) seen[name]=true end end
 for name,def in UL do if not seen[name] and type(def)=="table" and type(def.GetPrice)=="function" then table.insert(names,name) end end
 S.upgradeTypes=#names
 local cursor=0
 while S.running and gui.Parent do
 if S.enabled and X.upgrades then safe(function()
 for offset=1,#names do
 local index=(cursor+offset-1)%#names+1
 local name=names[index] local def=UL[name]
 local count=US.GetTimesPurchased(P,name)
 local eligible=not def.MaxPurchases or count<def.MaxPurchases
 if name=="CratePolisher" and US.GetTimesPurchased(P,"CratePolisherUnlock")<1 then eligible=false end
 if eligible and def.CanPurchase then
 local ok,allowed=pcall(def.CanPurchase,{Player=P})
 eligible=ok and allowed==true
 end
 if eligible and os.clock()>=(retryAt[name] or 0) then
 local price=def.GetPrice(count)
 if type(price)=="number" and price>=0 and price<math.huge and price<=(D.GetData().Currency.Cash or 0) then
 cursor=index
 R.PurchaseUpgrade:FireServer(name)
 local deadline=os.clock()+0.8
 repeat task.wait() until not S.running or US.GetTimesPurchased(P,name)>count or os.clock()>=deadline
 local after=US.GetTimesPurchased(P,name)
 if after>count then
 S.gameUpgrades+=after-count
 if name=="Luck" or name=="ConveyorLuck" then S.luckUpgrades+=after-count end
 S.lastUpgrade={name=name,level=after,price=price}
 objectCache={}
 else retryAt[name]=os.clock()+3 end
 break
 end end
 end
 end) end
 task.wait(0.15)
 end
end)
-- React to newly collected crates without waiting for a polling tick.
task.spawn(function()
 local pickupAt=0
