 local collectPart
 local collectConnection local nextCollectAt=0
 local function collect()
 if os.clock()<nextCollectAt then return end
 nextCollectAt=os.clock()+0.1
 if busy or not S.running or not S.enabled or not gui.Parent then return end
 busy=true
 safe(function()
 local plot=workspace.Map.PlotModels:FindFirstChild(P.Name)
 if not plot then return end
 local systems=plot:FindFirstChild("Systems")
 local conveyor=systems and systems:FindFirstChild("TycoonConveyor")
 local part=conveyor and conveyor:FindFirstChild("CollectPart")
 if not part or not part:IsA("BasePart") then S.ballCollectStatus="Waiting for conveyor collect point" return end
 S.ballCollectStatus="Collecting / selling balls"
 if collectPart~=part then
 if collectConnection then collectConnection:Disconnect() end
 collectPart=part
 collectConnection=part:GetAttributeChangedSignal("PendingBallCount"):Connect(function() task.defer(collect) end)
 table.insert(connections,collectConnection)
 end
 local now=os.clock()
 local pickupReady=S.polisherPickupAllowed(part)
 if not pickupReady then S.ballCollectStatus=string.format("Waiting %.1fs before Polisher pickup",S.polisherPickupRemaining or 0) end
 if pickupReady and not S.polisherFinishedWaiting and require(RS.Shared.Services.InventoryService).HasInventorySpace(P,1) and (X.autoSellCrates or S.polisherWantsCrates and S.polisherWantsCrates()) and (part:GetAttribute("PendingBallCount") or 0)>0 and now-pickupAt>=0.4 then
 pickupAt=now S.notePolisherPickup(part) R.PickupCrateBox:FireServer(part)
 end
 local crates=D.GetData().Crates
 for id in crates do
 if S.canSellCrate and S.canSellCrate(id) then
 local attempt=sales[id]
 if not attempt or now>=attempt.nextAt then
  if attempt then S.ballSales.retries+=1 end
  local tries=attempt and attempt.tries+1 or 1
  sales[id]={tries=tries,nextAt=now+math.min(1,0.2+math.max(0,tries-3)*0.15)}
  -- Only disappearance from replicated inventory confirms the sale.
  if S.running and S.enabled and D.GetData().Crates[id] and S.canSellCrate(id) then R.SellCrate:FireServer(id) end
 end
 end
 end
 S.ballSales.pending=0
 for id in sales do
 if not D.GetData().Crates[id] then
 sales[id]=nil S.sold+=1 S.ballSales.confirmed+=1
 if S.shinyCrates and S.shinyCrates[id] then S.ballSales.polished+=1 S.shinyCrates[id]=nil end
 else S.ballSales.pending+=1 end
 end
 S.ballCollectStatus=(X.autoSellCrates or X.polisher or X.autoSellPolishedCrates or X.polisherGoldenHourOnly) and not require(RS.Shared.Services.InventoryService).HasInventorySpace(P,1) and ("Cannot pick up balls • "..S.inventoryBlockedMessage()) or not X.autoSellCrates and (S.polisherWantsCrates and S.polisherWantsCrates() and "Feeding Polisher • Normal sales OFF" or "Auto Sell Crate OFF • Waiting for enabled Polisher or manual crates") or S.ballSales.pending>0 and ("Verifying ball sales: "..S.ballSales.pending.." pending • "..S.ballSales.retries.." retries") or ("Ball sales confirmed: "..S.ballSales.confirmed)
 end)
 busy=false
 end
 table.insert(connections,D.Signals.CrateDataChanged:Connect(function() task.defer(collect) end))
 while S.running and gui.Parent do collect() task.wait(S.mobileLite and 0.3 or 0.1) end
end)
