 end end
 if previous and previous.Parent and humanoid.Parent then humanoid:EquipTool(previous) end

 end
 else sale.status=total<=config.keepLockers and "Keeping best 10 lockers" or "Extra lockers are favorited" end
 end
 end
   end)
   S.releaseInventory("Locker Sales")
   if not ok then S.errors+=1 S.lastError="Locker sales: "..tostring(err) S.lockerSale.status=S.lastError end
  end
  task.wait(0.05)
