-- Additional systems share the main lifecycle, inventory lock and reservation set.
do
local services=RS.Shared.Services
local PS=require(services.PotionService)
local POL=require(services.PolisherService)
local MS=require(services.MarketService)
local BS=require(services.BallSkinService)
local INV=require(services.InventoryService)
local GS=require(services.GradeService)
local TS=require(services.TraitService)
local IT=require(services.InfinityTowerService)
local OB=require(services.ObbyBonusService)
local CS=game:GetService("CollectionService")
local status=S.featureStatus
local cooldown={}
local function ready(key,seconds)
 local now=os.clock() if now<(cooldown[key] or 0) then return false end cooldown[key]=now+seconds return true
end
S.resetReady=function(key)cooldown[key]=nil end
local function alive() return S.running and G.BlueFarm==S and gui.Parent~=nil end
do (function()
 local character local saved={} local leases={} local nextLease=0 local partAdded
 local function restore()
  if partAdded then partAdded:Disconnect() partAdded=nil end
  for part,value in saved do if part.Parent then pcall(function()part.CanCollide=value end) end end
  table.clear(saved) table.clear(leases) character=nil S.travelNoclipActive=false
 end
 S.restoreTravelCollision=restore
 local function apply(part)
  if part:IsA("BasePart") then
   if saved[part]==nil then saved[part]=part.CanCollide end
   part.CanCollide=false
  end
 end
 S.beginTravelNoclip=function(char)
  if character~=char then
   restore() character=char
   partAdded=char.DescendantAdded:Connect(function(part)if next(leases) and part:IsA("BasePart") then apply(part) end end)
  end
  nextLease+=1 local id=nextLease leases[id]=true S.travelNoclipActive=true
  for _,part in char:QueryDescendants("BasePart") do apply(part) end
  local released=false
  return function()
   if released then return end released=true leases[id]=nil
   if not next(leases) then restore() end
  end
 end
 table.insert(connections,game:GetService("RunService").PreSimulation:Connect(function()
  if not next(leases) then return end
  local human=character and character:FindFirstChildOfClass("Humanoid")
  if not alive() or not S.enabled or G.BlueFarm~=S or P.Character~=character or not human or human.Health<=0 then restore() return end
  for part in saved do if part.Parent then apply(part) end end
 end))
 table.insert(connections,P.CharacterRemoving:Connect(restore))
 table.insert(connections,gui.Destroying:Connect(restore))
end)() end

local function waitFor(predicate,seconds,pollInterval)
 local finish=os.clock()+(seconds or 2)
 repeat if predicate() then return true end task.wait(pollInterval or 0.05) until not alive() or os.clock()>=finish
 return predicate()
end
local function cashAllowed(price)
 local cash=D.GetData().Currency.Cash or 0
 if type(price)~="number" or price~=price or price<0 or price==math.huge or price>cash then return false end
 if X.fullMarketBalance then return true end
 return price<=cash*X.spendPercent/100 and cash-price>=X.reserveCash
end
local function ownedBox(name,variant)
 local b=D.GetData().Inventory.Boxes[name] local e=b and b[variant] return e and e.Amount or 0
end
local function plot() return workspace.Map.PlotModels:FindFirstChild(P.Name) end
local function baseParts()
 local home=plot() local out={}
 if home then for _,p in CS:GetTagged("DropperBasePart") do if p:IsDescendantOf(home) and p:GetAttribute("Unlocked") then table.insert(out,p) end end end return out
end
local toolFor=(function()
local toolIndex={} local toolIndexAt=-math.huge local toolIndexCharacter
S.toolLookupPerformance={lookups=0,rebuilds=0}
return function(kind,id)
 local char=P.Character local backpack=P:FindFirstChildOfClass("Backpack")
 S.toolLookupPerformance.lookups+=1
 if char~=toolIndexCharacter or os.clock()-toolIndexAt>=0.1 then
  toolIndex={} toolIndexAt=os.clock() toolIndexCharacter=char S.toolLookupPerformance.rebuilds+=1
  for _,container in {char,backpack} do if container then for _,t in container:GetChildren() do
   if t:IsA("Tool") then
    local category=t:GetAttribute("InventoryType") local key=t:GetAttribute("InventoryKey")
    if category and key then toolIndex[category]=toolIndex[category] or {} toolIndex[category][key]=t end
   end
  end end end
 end
 local tool=toolIndex[kind] and toolIndex[kind][id]
 if tool and (tool.Parent==char or tool.Parent==backpack) and tool:GetAttribute("InventoryType")==kind and tool:GetAttribute("InventoryKey")==id then return tool end
end
end)()

S.workerHealth={}
local function worker(name,period,fn)
 task.spawn(function()
 while alive() do
 if S.enabled or name=="Training" and S.trainingTrip then
 local health=S.workerHealth[name] or {runs=0,errors=0} S.workerHealth[name]=health
 health.started=os.clock() health.active=true
 local ok,err=pcall(fn)
 health.active=false health.finished=os.clock() health.runs+=1
 if not ok then health.errors+=1 health.lastError=tostring(err) end
 if not ok then status[name]="ERROR: "..tostring(err) S.errors+=1 S.lastError=name..": "..tostring(err) task.wait(3) end
 end
 task.wait(S.workerInterval(name,period))
 end
 end)
end
-- Auto Tournament owns only its own switches, native selections and timing input.
do (function()
 local state={status="OFF",matches=0,wins=0,decisions=0,perfectInputs=0,goodInputs=0,emergencyInputs=0,qteSeen=0,qtePressed=0,score={Your=0,Enemy=0},quarter=0}
 S.tournament=state
 local UI,Match,Field,Service,Mini,miniMaid
 local active,field,equip,start,pendingPrompt,chooseCallback,inputCallback
 local lastScan,lastAttempt,lastRender=0,0,0
 local wheelToken,wheelHandled,submittedPrompt
 local wheelStarted,wheelTurns,wheelPrevious,nextInputScan=0,0,0,0
 local lastWon=(D.GetData().Tournament or {}).LastWonSeed
 local function enabled()return alive() and S.enabled and X.autoTournament end
 local function render()
  if S.tournamentInfo and S.tournamentInfo.Parent then
   S.tournamentInfo.Text=state.status.."\nScore: "..state.score.Your.." - "..state.score.Enemy.." • Quarter: "..state.quarter.." / 4\nMatches: "..state.matches.." • Wins confirmed: "..state.wins.."\nChoices: "..state.decisions.." • Perfect inputs: "..state.perfectInputs.." • Good: "..state.goodInputs
  end
 end
 -- Same forward-pass / shot policy used in the comparative MCP trials.
 S.tournamentChoose=function(sim)
  local prompt=sim:GetPrompt()
  if not prompt then return nil end
  local best,bestValue=1,-math.huge
  for i,option in prompt.Options do
   local chance=sim:_applyPower(math.min(option.Chance*(X.tournamentPerfect and 1.25 or 1),0.95),"Your")
   local value
   if option.Kind=="Shoot" then value=chance*35
   elseif option.Kind=="Pass" then
    local target=sim._players[option.Target]
    if target then
     local distance=sim:_getDistanceToGoal(target)/sim._pitchScale
     value=(option.Open and 1 or chance)*(40-distance)*0.7+(option.Utility or 0)*0.15
    else value=-math.huge end
   else value=chance*15 end
   if value>bestValue then best,bestValue=i,value end
  end
  return best
 end
 local function initialize()
  if UI then return true end
  local classes=RS.Client.Core.Classes local modules=RS.Client.Core.Gui
  if not classes:FindFirstChild("TournamentMatchClient") or not modules:FindFirstChild("TournamentGuiClient") then
   state.status="Tournament is unavailable on this server" return false
  end
  if type(filtergc)~="function" then state.status="Tournament requires filtergc support" return false end
  UI=require(modules.TournamentGuiClient)
  Match=require(classes.TournamentMatchClient) Field=require(classes.SoccerFieldClient)
  Service=require(RS.Shared.Services.TournamentService) Mini=require(modules.TournamentMinigameClient)
  for _,value in debug.getupvalues(Mini.Play) do
   if type(value)=="table" and type(rawget(value,"_tasks"))=="table" then miniMaid=value break end
  end
  assert(miniMaid,"Native Tournament timing state unavailable")
  return true
 end
 local function bindMatch()
  if not UI.IsInMatch() then
   if active then active=nil pendingPrompt=nil chooseCallback=nil table.clear(S.tournamentProtected) end
   return nil
  end
  if active and not active._Destroyed then return active end
  local matches=filtergc("table",{Metatable=Match},false)
  for _,candidate in matches do
   if not candidate._Destroyed and candidate.Folder and candidate.Folder.Parent and candidate._sim then
    active=candidate state.matches+=1 pendingPrompt=nil chooseCallback=nil
    table.clear(S.tournamentProtected)
    for id in candidate._guids do S.tournamentProtected[id]=true end
    return active
   end
  end
 end
 local function findChoice(prompt,index)
  local candidates=filtergc("function",{Constants={"HideLetters","Play"},Upvalues={prompt}},false)
  for _,callback in candidates do
   for _,value in debug.getupvalues(callback) do
    if type(value)=="number" and value==index then return callback end
   end
  end
 end
 local function playWheel()
  local screen=P.PlayerGui:FindFirstChild("TournamentSelectionGui")
  local wheel=screen and screen:FindFirstChild("RotationMinigame")
  local input=miniMaid and miniMaid._tasks.Input
  if not wheel or not wheel.Visible or not input then
   wheelToken=nil wheelHandled=false inputCallback=nil return
  end
  if not X.tournamentPerfect then return end
  local target=wheel.PerfectZone.Rotation
  local tick=wheel.RotatingTick.Rotation
  if wheelToken~=input then
   wheelToken=input wheelHandled=false inputCallback=nil
   wheelStarted=os.clock() wheelTurns=0 wheelPrevious=tick
   state.qteSeen+=1
  end
  if wheelHandled then return end
  if tick+180<wheelPrevious then wheelTurns+=1 end
  wheelPrevious=tick
  if not inputCallback and os.clock()>=nextInputScan then
   nextInputScan=os.clock()+0.2
   -- Read the currently connected handler; old completed QTE closures are excluded.
   if type(getconnections)=="function" then
    for _,connection in getconnections(UIS.InputBegan) do
     local callback=connection.Function
     if type(callback)=="function" and connection.Enabled~=false then
      local foundClick,foundPerfect=false,false
      for _,value in debug.getconstants(callback) do
       if value=="TournamentClick" then foundClick=true elseif value=="TournamentPerfect" then foundPerfect=true end
      end
      if foundClick and foundPerfect then inputCallback=callback break end
     end
    end
   end
   if not inputCallback then
    for _,callback in filtergc("function",{Constants={"TournamentClick","TournamentPerfect"}},false) do
     for _,value in debug.getupvalues(callback) do
      if type(value)=="boolean" and value==false then inputCallback=callback break end
     end
     if inputCallback then break end
    end
   end
  end
  if inputCallback then
   local angle=math.abs((tick-target+180)%360-180)
   local elapsed=os.clock()-wheelStarted
   -- Native QTE lasts three turns. Prefer Perfect on turns 1/2; take Good on turn 3.
   local fallback=wheelTurns>=2 or elapsed>=1.85
   if angle<=2.5 or fallback and angle<=30 or elapsed>=2.85 then
    inputCallback({UserInputType=Enum.UserInputType.MouseButton1})
    -- The game's handler clears Input after accepting a press. Do not count stale callbacks.
    if miniMaid._tasks.Input~=input then
     wheelHandled=true state.qtePressed+=1
     if angle<=2.5 then state.perfectInputs+=1
     elseif angle<=30 then state.goodInputs+=1 else state.emergencyInputs+=1 end
    else inputCallback=nil nextInputScan=0 end
   end
  end
 end
 local function attemptStart()
  if not X.tournamentAutoStart then state.status="Ready • Start a Tournament manually" return end
  local seed=Service.GetSeed()
  if (D.GetData().Tournament or {}).LastWonSeed==seed then
   state.status="Won this rotation • Next opponent in "..math.ceil(Service.GetTimeUntilNextRotation()).."s" return
  end
  if os.clock()-lastAttempt<15 then return end
  if S.nativeMenuRequested or S.selectingTraining or S.inventoryBusy or S.characterTaskBusy() then state.status="Waiting for current task" return end
  lastAttempt=os.clock()
  if not field or not field.Model or not field.Model.Parent then field=filtergc("table",{Metatable=Field},true) end
  if not field then state.status="Waiting for Tournament field" return end
  equip=equip or filtergc("function",{Constants={"You don't have any units!","TournamentUnitSlots"}},true)
  start=start or filtergc("function",{Constants={"Your team is too weak to play!"}},true)
  if not equip or not start then state.status="Tournament controls unavailable • Start manually" return end
  state.status="Selecting best team • Starting Tournament"
  local selection=P.PlayerGui:FindFirstChild("TournamentSelectionGui")
  local main=selection and selection:FindFirstChild("UnitsSelectionMainFrame")
  -- Open initializes the field geometry and excludes units already in a Tower.
  if not main or not main.Visible then UI.Open(field) end
  if not enabled() then return end
  equip()
  if not enabled() then return end
  start()
  if not UI.IsInMatch() then state.status="Start not confirmed • Check available team / game notice" end
 end
 S.tournamentStep=function()
  if not initialize() then return end
  local match=bindMatch()
  local won=(D.GetData().Tournament or {}).LastWonSeed
  if won~=lastWon then
   if lastWon~=nil and type(won)=="number" and won>=0 then state.wins+=1 end
   lastWon=won
  end
  if not enabled() then
   state.status=not X.autoTournament and "OFF" or "PAUSED • Resume the script to continue"
   return
  end
  if not match then attemptStart() return end
  local sim=match._sim
  state.score=table.clone(sim:GetScore()) state.quarter=sim:GetQuarter()
  state.status="Playing • Forward passes / goal opportunities"
  local prompt=sim:GetPrompt()
  if prompt and submittedPrompt~=prompt then
   if pendingPrompt~=prompt then pendingPrompt=prompt chooseCallback=nil lastScan=0 end
   if not chooseCallback and os.clock()-lastScan>=0.5 then
    lastScan=os.clock()
    chooseCallback=findChoice(prompt,S.tournamentChoose(sim))
   end
   if chooseCallback then
    local callback=chooseCallback chooseCallback=nil
    -- Invoke the native option handler: it cleans the prompt and starts the real minigame.
    callback() submittedPrompt=prompt state.decisions+=1
   end
  else pendingPrompt=nil chooseCallback=nil end
 end
 table.insert(connections,game:GetService("RunService").RenderStepped:Connect(function()
  if active and enabled() and miniMaid then
   local ok,err=pcall(playWheel)
   if not ok and state.timingError~=tostring(err) then
    state.timingError=tostring(err) S.errors+=1 S.lastError="Tournament timing: "..tostring(err)
   end
  end
 end))
 task.spawn(function()
  while alive() do
   if X.autoTournament or active then
    local ok,err=pcall(S.tournamentStep)
    if not ok then
     local message=tostring(err)
     if state.lastError~=message then S.errors+=1 S.lastError="Tournament: "..message end
     state.lastError=message state.status="Tournament error • "..message
     task.wait(2)
    end
   else state.status="OFF" end
   if os.clock()-lastRender>=0.5 then lastRender=os.clock() render() end
   if active and enabled() then task.wait(0.1) else task.wait(0.5) end
  end
  table.clear(S.tournamentProtected)
 end)
 table.insert(connections,gui.Destroying:Connect(function() active=nil table.clear(S.tournamentProtected) end))
end)() end


do (function()
 local module=RS.Shared.Services:FindFirstChild("MissionService")
 local libraryModule=RS.Shared.Core.Storage.Game:FindFirstChild("MissionLibrary")
 local state={status="Checking missions",confirmed=0,requests=0,rows={},pending={},ledger={}}
 S.missions=state
 if not module or not libraryModule then state.status="Missions unavailable on this server" return end
 local service=require(module) local library=require(libraryModule)
 local ids={} for id in library do table.insert(ids,id) end
 table.sort(ids,function(a,b)
  local x,y=library[a],library[b]
  if x.ResetGroup~=y.ResetGroup then return x.ResetGroup=="Daily" end
  return (x.LayoutOrder or 0)<(y.LayoutOrder or 0) or x.LayoutOrder==y.LayoutOrder and a<b
 end)
 local function selected(group)return group=="Daily" and X.missionDaily or group=="Event" and X.missionEvent or false end
 S.renderMissions=function()
  if not S.missionInfo or not S.missionInfo.Parent then return end
  local lines={state.status.." • Confirmed: "..state.confirmed}
  local seconds=service.GetResetGroupTimeRemaining("Daily")
  table.insert(lines,string.format("Daily reset: %02d:%02d:%02d",math.floor(seconds/3600),math.floor(seconds/60)%60,math.floor(seconds)%60))
  for _,row in state.rows do
   table.insert(lines,"["..row.group.."] "..row.name.." • "..row.progress.." • "..row.status)
  end
  S.missionInfo.Text=table.concat(lines,"\n")
 end
 S.refreshMissions=function()
  local now=os.clock() local rows={} local readyCount=0 local waiting=0 local retryLimit=false
  local remote=R:FindFirstChild("TryClaimMission")
  for _,id in ids do
   local def=library[id] local group=def.ResetGroup
   local seed=service.GetResetGroupSeed(group)
   local record=state.ledger[id]
   if not record or record.seed~=seed then
    record={seed=seed,attempts=0,nextAt=0} state.ledger[id]=record state.pending[id]=nil
   end
   local data=service.GetStoredMissionData(P,id)
   local complete=service.IsMissionComplete(P,id)
   local claimable=service.IsMissionClaimable(P,id)
   local pending=state.pending[id]
   if pending and complete then
    state.confirmed+=1 state.lastConfirmed=id state.pending[id]=nil pending=nil
   elseif pending and now-pending.sentAt>=4 then
    state.pending[id]=nil pending=nil record.nextAt=now+6
   end
   local progress={}
   for index,taskDef in def.Tasks do
    local taskData=data and data.Tasks and data.Tasks[index]
    local current=tonumber(taskData and taskData.Amount) or 0 local target=tonumber(taskDef.Amount) or 0
    table.insert(progress,tostring(math.min(current,target)).."/"..target)
   end
   local row={id=id,group=group,name=def.DisplayName or id,progress=table.concat(progress,", "),status=complete and "Claimed" or claimable and "Ready" or "In progress"}
   if pending then row.status="Confirming reward" waiting+=1 end
   if claimable and not complete and selected(group) then
    readyCount+=1
    if record.attempts>=3 and not pending then row.status="Claim unconfirmed • Check mission menu" retryLimit=true end
    -- One outstanding claim per mission. Only server completion confirms it.
    if X.autoMissions and S.enabled and remote and not pending and now>=record.nextAt and record.attempts<3 and not S.inventoryBusy and not S.nativeMenuRequested then
     record.attempts+=1 record.nextAt=now+4
     state.pending[id]={sentAt=now,seed=seed} state.requests+=1
     remote:FireServer(id) row.status="Confirming reward" waiting+=1
    end
   end
   table.insert(rows,row)
  end
  state.rows=rows state.ready=readyCount
  state.status=not X.autoMissions and "Auto Mission OFF" or not S.enabled and "Auto Mission PAUSED" or not remote and "Mission claim unavailable" or waiting>0 and "Confirming mission rewards" or retryLimit and "Some claims need review" or readyCount>0 and "Rewards ready • Waiting for active task" or "Tracking missions • Farming uses existing settings"
  S.renderMissions()
 end
 worker("Missions",0.75,S.refreshMissions)
end)() end

local heldSince={}
S.shinyCrates={}
S.polisherDepositing={}
S.isPolishedCrate=function(id)
 local crate=D.GetData().Crates[id]
 if not crate then return nil end
 if S.shinyCrates[id] or type(crate)=="table" and crate.Shiny==true then S.shinyCrates[id]=true return true end
 local tool=toolFor("Crate",id)
 if not tool then return nil end -- Wait for replication rather than guess a sale category.
 if tool:GetAttribute("Shiny")==true then S.shinyCrates[id]=true return true end
 return false
end
S.polishedSalesAllowed=function()
 if not X.polisherGoldenHourOnly then return X.autoSellPolishedCrates==true end
 local ok,weather=pcall(function()return require(RS.Shared.Services.WeatherService).GetCurrentWeather()end)
 return ok and weather=="GoldenHour"
end
S.canSellCrate=function(id)
 if S.polisherDepositing[id] then return false end
 local polished=S.isPolishedCrate(id)
 if polished==nil then return false end
 if polished then return S.polishedSalesAllowed() end
 return X.autoSellCrates==true and (not S.shouldPolish or not S.shouldPolish(id))
end
S.polisherWantsCrates=function()
 return X.polisher and POL.IsUnlocked(P) and S.polisherAvailable==true and INV.HasInventorySpace(P,1)
end
S.canDepositPolisher=function(id)
 if not X.polisher or not POL.IsUnlocked(P) then return false end
 local crate=D.GetData().Crates[id]
 if not crate then heldSince[id]=nil return false end
 if type(crate)=="table" and crate.Shiny then heldSince[id]=nil S.shinyCrates[id]=true return false end
 local tool=toolFor("Crate",id)
 if tool and tool:GetAttribute("Shiny") then heldSince[id]=nil S.shinyCrates[id]=true return false end
 return S.polisherAvailable~=false
end
S.shouldPolish=function(id)
 if not S.canDepositPolisher(id) then return false end
 if S.polisherDepositing[id] then return true end
 heldSince[id]=heldSince[id] or os.clock()
 -- Failed deposits must not reserve a crate forever and block all sales.
 return S.polisherAvailable~=false and os.clock()-heldSince[id]<8
end
worker("Polisher",0.35,function()
 S.polisherFinishedWaiting=false
 if not X.polisher and not X.autoSellPolishedCrates and not X.polisherGoldenHourOnly then status.Polisher="OFF" return end
 if not POL.IsUnlocked(P) then status.Polisher="รอปลดล็อก • ขายบอลตามปกติ" return end
 local home=plot() local part
 for _,p in CS:GetTagged("PolisherCollectPart") do if home and p:IsDescendantOf(home) then part=p break end end
 S.polisherAvailable=part~=nil
 if not part then status.Polisher="Polisher unavailable; selling crates normally" return end
 status.Polisher=string.format("รอขัด %.0f • ขัดแล้ว %.0f",POL.GetPendingCash(P),POL.GetPolishedCash(P))
 local canSellPolished=S.polishedSalesAllowed()
 if X.polisherGoldenHourOnly and not canSellPolished then
  status.Polisher="Waiting for Golden Hour • Polished crates held"
 end
 S.polisherFinishedWaiting=canSellPolished and (part:GetAttribute("PolishedBallCount") or 0)>0
 if canSellPolished and (part:GetAttribute("PolishedBallCount") or 0)>0 and INV.HasInventorySpace(P,1) and ready("polisherCollect",0.5) and S.polishedSalesAllowed() then R.CollectPolisherCrate:FireServer(part) end
 if not X.polisher then return end
 
 local queue={}
 for id in D.GetData().Crates do if S.canDepositPolisher(id) then table.insert(queue,id) end end
 if #queue>0 then
  local char=P.Character local human=char and char:FindFirstChildOfClass("Humanoid")
  if not human or human.Health<=0 or S.selectingTraining then return end
  local previous=char:FindFirstChildOfClass("Tool") local lastTool
  local batch={total=#queue,confirmed=0,skipped=0} S.polisherBatch=batch
  for _,id in queue do
   if not alive() or not S.enabled or not X.polisher or P.Character~=char or human.Health<=0 or S.selectingTraining then break end
   local tool=toolFor("Crate",id)
   if not tool or not S.canDepositPolisher(id) or tool:GetAttribute("Shiny") then batch.skipped+=1 continue end
   -- Continue this inventory snapshot without the worker delay between crates.
   -- Yield ownership between items so Grave, Training and other inventory work
   -- can finish without having their equipped tool replaced mid-action.
   local deadline=os.clock()+15 local acquired=false
   repeat
    if not alive() or not S.enabled or not X.polisher or P.Character~=char or human.Health<=0 or S.selectingTraining then break end
    acquired=S.acquireInventory("Polisher")
    if not acquired then status.Polisher="Batch queued for inventory" task.wait(0.02) end
   until acquired or os.clock()>deadline
   if not acquired then S.releaseInventory("Polisher") break end
   S.polisherDepositing[id]=true lastTool=tool
   local ok,err=pcall(function()
    if not S.canDepositPolisher(id) or not tool.Parent or tool:GetAttribute("Shiny") then return end
    human:EquipTool(tool)
    if not waitFor(function()return tool.Parent==char or not tool.Parent end,0.7) or tool.Parent~=char then return end
    task.wait(0.18)
    if not alive() or not S.enabled or not X.polisher or P.Character~=char or human.Health<=0 or char:FindFirstChildOfClass("Tool")~=tool or not S.canDepositPolisher(id) then return end
    R.DepositCrate:FireServer(part)
    if waitFor(function()return D.GetData().Crates[id]==nil or P.Character~=char end,1) and D.GetData().Crates[id]==nil then
     S.confirmed.polishedDeposits=(S.confirmed.polishedDeposits or 0)+1 batch.confirmed+=1 heldSince[id]=nil
    end
   end)
   S.polisherDepositing[id]=nil S.releaseInventory("Polisher")
   status.Polisher="Depositing batch • "..batch.confirmed.." / "..batch.total.." confirmed"
   if not ok then
    if previous and previous.Parent and human.Parent and P.Character==char and char:FindFirstChildOfClass("Tool")==lastTool then pcall(human.EquipTool,human,previous) end
    error(err)
   end
   task.wait(0.02)
  end
  if previous and previous.Parent and human.Parent and P.Character==char and char:FindFirstChildOfClass("Tool")==lastTool then pcall(human.EquipTool,human,previous) end
 end
 if not INV.HasInventorySpace(P,1) then status.Polisher="Waiting for inventory space • "..S.inventoryBlockedMessage() end
 for id in heldSince do if not D.GetData().Crates[id] then heldSince[id]=nil end end
end)
worker("Potions",0.75,function()
 local rolling=(X.grade and S.hasSelectedTargets(X.gradeTargets)) or (X.trait and S.hasSelectedTargets(X.traitTargets))
 local requests={{"luckPotion","LuckPotion"},{"cashPotion","CashPotion"},{"speedPotion","GradeSpeedPotion"},{"bluetooth","BluetoothPotion"}}
 for _,r in requests do
 if not alive() or not S.enabled then return end
 local key,name=r[1],r[2]
 local needed=X[key]==true and S.potionConsent[key]==true and (key=="luckPotion" or key=="cashPotion" or (rolling and X.unit~=nil))
 if key=="bluetooth" then needed=needed and ((X.grade and not GS.IsInRollRange(P,GS.HITBOX_TAG)) or (X.trait and not GS.IsInRollRange(P,TS.HITBOX_TAG))) end
 local before=D.GetData().Potions[name] or 0
 if needed and before>0 and not PS.IsPotionActive(P,name) and ready(name,8) then
 if not S.tryUseOptInPotion(key,name) then continue end
 if waitFor(function()return PS.IsPotionActive(P,name) or (D.GetData().Potions[name] or 0)<before end,2) then status.Potions="ใช้ "..name.." แล้ว" S.confirmed.potions=(S.confirmed.potions or 0)+1 else status.Potions="ยังไม่ยืนยัน "..name end
 end
 end
end)
local function boxScore(name,var)
 local score=0
 for unit in BL[name].PlayerUnits do score=math.max(score,U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unit,PlayerUnitVariant=var,PlayerUnitLevel=1})) end return score
end
worker("Market",1.5,function()
 if not X.market then status.Market="OFF" return end
 local purchaseRemote=R:FindFirstChild("MarketPurchaseCash")
 if not purchaseRemote then status.Market="Unavailable: เซิร์ฟเวอร์นี้ไม่มีระบบซื้อ Market" return end
 
 local seed=MS.GetSeed() local entries=MS.GetBoxes(seed)
 table.sort(entries,function(a,b)return boxScore(a.BoxName,a.Variant)>boxScore(b.BoxName,b.Variant) end)
 local total,lowest=0,math.huge
 for name,vars in D.GetData().Inventory.Boxes do for var,e in vars do if (e.Amount or 0)>0 and BL[name] then total+=e.Amount lowest=math.min(lowest,boxScore(name,var)) end end end
 if total>config.keepLockers then status.Market="รอขายส่วนเกินก่อนซื้อ" return end
 status.Market="รอสต็อก / งบ / กล่องที่ดีกว่า"
 for _,e in entries do
 local name,var=e.BoxName,e.Variant local purchase=D.GetData().Market[name.."_"..var]
 local count=purchase and purchase.Seed==seed and purchase.AmountPurchased or 0
 local price=MS.GetPrice(e.BoxData,var)
 if e.Stock>count and config.boxes[name]~=false and (not config.variantFilter or config.variants[var]~=false) and (total<config.keepLockers or boxScore(name,var)>lowest) and cashAllowed(price) and B.HasBoxInventorySpace(P,1) and S.purchaseSpace() and ready("market:"..name..var,8) then
 local before=ownedBox(name,var)
 if not S.acquireInventory("Market") then status.Market="Queued for inventory" return end
 local ok,err=pcall(function()
 purchaseRemote:FireServer(name,var)
 if waitFor(function()return ownedBox(name,var)>before end,2) then status.Market="ซื้อ "..var.." "..name.." แล้ว" S.confirmed.market=(S.confirmed.market or 0)+1 else status.Market="คำสั่งซื้อยังไม่ยืนยัน" end
 end)
 S.releaseInventory("Market") if not ok then error(err) end return
 end
 end
end)
local function checkBallSkins()
 if not X.skinEquip and not X.skinBuy then status.Skins="OFF" S.skinEquipStatus="OFF" return end
 
 local parts=baseParts()
 local ranked={}
 for _,p in parts do if p:GetAttribute("Type")=="PlayerUnit" then
 local current=BS.GetMultiplier(p:GetAttribute("PlayerUnitBallSkin"))
 table.insert(ranked,{part=p,base=partBase(p)/current,level=p:GetAttribute("PlayerUnitLevel") or 1,current=current})
 end end
 table.sort(ranked,function(a,b)
 if a.base~=b.base then return a.base>b.base end
 if a.level~=b.level then return a.level>b.level end
 return a.part:GetFullName()<b.part:GetFullName()
 end)
 local function bestTarget(name)
 local mult=BS.GetMultiplier(name)
 for rank,entry in ranked do if mult>entry.current then return entry.part,rank end end
 end
 local function skinTransaction(fn,retryKey)
 if not S.acquireInventory("Ball Skins") then
 if retryKey then cooldown[retryKey]=nil end
 S.skinEquipStatus="Queued for inventory" return false end
 local ok,err=pcall(fn)
 S.releaseInventory("Ball Skins")
 if not ok then error(err) end
 end
 local skins={} for name,n in D.GetData().Inventory.BallSkins do if n>0 and not BS.IsBallSkinFavorited(P,name) then table.insert(skins,name) end end
 table.sort(skins,function(a,b)local am,bm=BS.GetMultiplier(a),BS.GetMultiplier(b) if am==bm then return a<b end return am>bm end)
 S.skinPlan={}
 for i=1,math.min(3,#ranked) do local entry=ranked[i] table.insert(S.skinPlan,{rank=i,name=entry.part:GetAttribute("PlayerUnitName"),baseWithoutSkin=entry.base,level=entry.level,currentMultiplier=entry.current}) end
 if X.skinEquip then for _,name in skins do
 local p,rank=bestTarget(name)
 if p and ready("skinEquip",5) then
 skinTransaction(function()
 if not alive() or not S.enabled or not X.skinEquip or not p.Parent or p:GetAttribute("Type")~="PlayerUnit" or BS.GetOwnedAmount(P,name)<=0 or BS.IsBallSkinFavorited(P,name) or BS.GetMultiplier(name)<=BS.GetMultiplier(p:GetAttribute("PlayerUnitBallSkin")) then return end
 R.ApplyBallSkinToDropper:FireServer(p,name)
 if waitFor(function()return p:GetAttribute("PlayerUnitBallSkin")==name end,2) then
 status.Skins="ใส่ "..name.." ให้ "..tostring(p:GetAttribute("PlayerUnitName")).." • อันดับ "..rank
 S.confirmed.skins=(S.confirmed.skins or 0)+1
 S.lastSkinEquip={skin=name,striker=p:GetAttribute("PlayerUnitName"),rank=rank}
 else status.Skins="ใส่สกินยังไม่ยืนยัน" end
 S.skinEquipStatus=status.Skins
 end,"skinEquip") return
 end
 end end
 if not X.skinEquip then S.skinEquipStatus="OFF"
 elseif #ranked==0 then S.skinEquipStatus="No Strikers in base"
 elseif #skins==0 then S.skinEquipStatus="No usable Ball Skins in inventory (or all are Favorite)"
 else
 local improvement=false for _,name in skins do if bestTarget(name) then improvement=true break end end
 S.skinEquipStatus=improvement and "Waiting for equip cooldown" or "Already equipped: all inventory skins are equal or weaker"
 end
 if X.skinBuy then
 if not S.hasSelectedTargets(X.skinBuyTypes) then S.skinBuyStatus="Choose Ball Skins to Buy • No types selected" status.Skins=S.skinBuyStatus return end
 local entries=BS.GetStock(BS.GetSeed()) table.sort(entries,function(a,b)return BS.GetMultiplier(a.BallSkinName)>BS.GetMultiplier(b.BallSkinName) end)
 local hasStock,hasBudget=false,false
 for _,e in entries do
 local name=e.BallSkinName
 if not S.canBuyBallSkinType(name) then continue end
 if BS.GetRemainingStock(P,e)>0 then
 hasStock=true
 if cashAllowed(BS.GetPrice(name)) then hasBudget=true end
 end
 if BS.GetRemainingStock(P,e)>0 and not (X.skinSell and X.skinSellTypes[name]==true) and cashAllowed(BS.GetPrice(name)) and S.purchaseSpace() and ready("skinBuy:"..name,8) then
 local before=BS.GetOwnedAmount(P,name)
 local purchasedBefore=BS.GetAmountPurchased(P,name)
 skinTransaction(function()
 if not alive() or not S.enabled or not X.skinBuy or not S.canBuyBallSkinType(name) or not cashAllowed(BS.GetPrice(name)) or not S.purchaseSpace() then return end
 R.BallSkinPurchaseCash:FireServer(name)
 if waitFor(function()return BS.GetOwnedAmount(P,name)>before or BS.GetAmountPurchased(P,name)>purchasedBefore end,2) then
 status.Skins="ซื้อ "..name.." แล้ว" S.confirmed.skinBuys=(S.confirmed.skinBuys or 0)+1
 cooldown["skinBuy:"..name]=os.clock()+0.35
 else status.Skins="ซื้อสกินยังไม่ยืนยัน" end
 S.skinBuyStatus=status.Skins
 end,"skinBuy:"..name) return
 end
 end
 if not hasStock then S.skinBuyStatus="สินค้าหมด • รอร้านเติมอัตโนมัติ"
 elseif not S.purchaseSpace() then S.skinBuyStatus=S.inventoryBlockedMessage()
 elseif not hasBudget then S.skinBuyStatus="เงินไม่พอ หรือเกินงบที่ตั้งไว้"
 else S.skinBuyStatus="กำลังตรวจสต็อกสกิน" end
 else S.skinBuyStatus="OFF"
 end
 status.Skins=X.skinBuy and S.skinBuyStatus or "รอสกินที่ดีกว่า / สต็อก / งบ"
end
S.checkBallSkins=checkBallSkins
worker("Ball Skin",0.35,checkBallSkins)
do (function()
 local merchant=require(RS.Shared.Services.MerchantService)
 local state={sold=0,status="OFF"} S.skinSale=state
 S.canSellBallSkin=function(name)
  return X.skinSellTypes[name]==true and BS.GetOwnedAmount(P,name)>0 and not BS.IsBallSkinFavorited(P,name) and merchant.GetBallSkinSellPrice(name)>0
 end
 worker("Ball Skin Sales",0.25,function()
  if not X.skinSell then state.status="OFF" return end
  if S.selectingTraining then state.status="Waiting for selection" return end
  local name
  for candidate in X.skinSellTypes do if S.canSellBallSkin(candidate) then name=candidate break end end
  if not name then state.status="No selected sellable skins • Select types; Favorites are kept" return end
  if not ready("skinSell:"..name,2) then state.status="Waiting for sale confirmation / retry" return end
  local char=P.Character local human=char and char:FindFirstChildOfClass("Humanoid")
  local tool=toolFor("BallSkin","BallSkin_"..name)
  if not human or human.Health<=0 or not tool then state.status="Waiting for Ball Skin tool" return end
  if not S.acquireInventory("Ball Skin Sales") then cooldown["skinSell:"..name]=nil state.status="Queued for inventory" return end
  local previous=char:FindFirstChildOfClass("Tool")
  local ok,err=pcall(function()
   human:EquipTool(tool)
   if not waitFor(function()return tool.Parent==char end,0.7) then return end
   task.wait(0.18)
   if not alive() or not S.enabled or not X.skinSell or not S.canSellBallSkin(name) or P.Character~=char or char:FindFirstChildOfClass("Tool")~=tool then return end
   local before=BS.GetOwnedAmount(P,name)
   state.status="Selling "..name.." ×"..before
   R.MerchantSell:FireServer("HeldItem",name,before)
   if waitFor(function()return BS.GetOwnedAmount(P,name)<before end,1.5) then
    local sold=before-BS.GetOwnedAmount(P,name) state.sold+=sold
    state.status="Confirmed: "..sold.." "..name.." sold • Total "..state.sold
   else state.status="Sale not confirmed • Will retry" end
  end)
  if previous and previous.Parent and human.Parent and P.Character==char then pcall(human.EquipTool,human,previous) end
  S.releaseInventory("Ball Skin Sales")
  if not ok then state.status=tostring(err) error(err) end
 end)
end)() end

S.pickTrainingUnit=function(nextOne)
 if S.trainingQueueState and S.trainingQueueState.running then status.Training="Stop Queue before changing Striker" return end
 if X.grade or X.trait then status.Training="ปิดการสุ่มก่อนเปลี่ยนตัว" return end
 local units={}
 for id,u in D.GetData().PlayerUnits do if not u.Equipped and not S.towerProtected[id] and not (S.towerActiveUnits[id] or S.tournamentProtected[id]) and not U.IsPlayerUnitFavorited(P,id) then table.insert(units,{id=id,score=unitBase(u)}) end end
 table.sort(units,function(a,b)if a.score==b.score then return a.id<b.id end return a.score>b.score end)
 if #units==0 then status.Training="ไม่มีตัวสำรอง • นำตัวออกจาก Base ก่อน" return end
 local index=1 if nextOne then for i,u in units do if u.id==X.unit then index=i%#units+1 break end end end
 table.clear(S.reservedUnits) X.unit=units[index].id S.reservedUnits[X.unit]=true S.refreshSelectedUnit()
 status.Training="เลือกตัวแล้ว • พร้อมตั้งเป้าหมาย"
end
local rollCounts={grade=0,trait=0} local enabledBefore={}
S.trainingStops={}
S.trainingPending={} S.trainingFailures={} S.trainingTiming={confirmed=0,timeouts=0}
S.finishTrainingTrip=function()
 local trip=S.trainingTrip S.trainingTrip=nil
 if trip and S.enabled and P.Character==trip.char and trip.root.Parent and trip.human.Health>0 then
  pcall(S.returnTrainingSafe,trip.origin,true)
 end
 S.trainingTravel=false
end

local gradeRevisions={}
for _,signalName in {"PlayerUnitGradeChanged","PlayerUnitGradePityChanged","PlayerUnitTraitChanged","PlayerUnitTraitPityChanged"} do
 local prefix=string.find(signalName,"Grade",1,true) and "Grade:" or "Trait:"
 if D.Signals[signalName] then table.insert(connections,D.Signals[signalName]:Connect(function(id) if id then local key=prefix..id gradeRevisions[key]=(gradeRevisions[key] or 0)+1 end end)) end
end
S.trainingResultConfirmed=function(entry)
 local data=D.GetData() local unit=data.PlayerUnits[entry.id]
 if not unit then return false end
 if unit[entry.token]~=entry.old or (gradeRevisions[entry.token..":"..entry.id] or 0)>entry.revision then return true end
 if entry.useTokens and (data.Tokens[entry.token] or 0)<entry.tokens then return true end
 local pity=unit[entry.token.."Pity"] or {}
 for key,value in pity do if entry.pity[key]~=value then return true end end
 for key in entry.pity do if pity[key]==nil then return true end end
 return false
end
S.openTrainingPicker=function()
 if S.trainingQueueState and S.trainingQueueState.running then status.Training="Stop Queue before changing Striker" return end
 if S.selectingTraining or (S.characterTaskBusy() or S.inventoryBusy) and not S.nativeMenuRequested then return end
 X.grade=false X.trait=false
 S.selectingTraining=true
 status.Training="รอเลือกตัวจากหน้าของเกม"
 task.spawn(function()
 local oldVisible=panel.Visible local closeConnection
 local function restore()
 S.selectingTraining=false
 if panel.Parent then if S.setMinimized then S.setMinimized(false,true) else panel.Visible=true end end
 if closeConnection then closeConnection:Disconnect() closeConnection=nil end
 end
 local ok,err=pcall(function()
 if not alive() then status.Training="ตัวนี้ไม่พร้อมเลือกแล้ว • กรุณาเปิด Select ใหม่" restore() return end
 local nativeGui=P.PlayerGui:FindFirstChild("SelectGui")
 local frame=nativeGui and nativeGui:FindFirstChild("MainFrame")
 if not frame then status.Training="ไม่พบหน้าเลือกตัวของเกม" restore() return end
 local picker=require(RS.Client.Core.Gui.SelectGuiClient)
 local excluded={}
 for id in D.GetData().PlayerUnits do if S.towerProtected[id] or (S.towerActiveUnits[id] or S.tournamentProtected[id]) or U.IsPlayerUnitFavorited(P,id) or G.BlueFarmSpareSale.pending==id then excluded[id]=true end end
 panel.Visible=false
 picker.Open(function(id)
 if not alive() then return end
 local unit=D.GetData().PlayerUnits[id]
 if not unit or unit.Equipped or S.towerProtected[id] or (S.towerActiveUnits[id] or S.tournamentProtected[id]) or U.IsPlayerUnitFavorited(P,id) or G.BlueFarmSpareSale.pending==id then
 status.Training="ตัวนี้ไม่พร้อมเลือกแล้ว • กรุณาเปิด Select ใหม่" restore() return
 end
 table.clear(S.reservedUnits) X.unit=id S.reservedUnits[id]=true S.refreshSelectedUnit()
 status.Training="เลือกตัวแล้ว • พร้อมตั้งเป้าหมาย"
 restore()
 end,nil,excluded,{IncludeEquipped=false,ExcludePercentageUnits=true})
 closeConnection=frame:GetPropertyChangedSignal("Visible"):Connect(function()if not frame.Visible then restore() end end)
 table.insert(connections,closeConnection)
 end)
 if not ok then status.Training=tostring(err) restore() end
 end)
end
do (function()
 local function matches(part,u)
  return part:GetAttribute("Type")=="PlayerUnit" and u.PlayerUnitName==part:GetAttribute("PlayerUnitName") and (u.Variant or "Normal")== (part:GetAttribute("PlayerUnitVariant") or "Normal") and (u.Level or 1)==(part:GetAttribute("PlayerUnitLevel") or 1) and u.Grade==part:GetAttribute("PlayerUnitGrade") and u.Trait==part:GetAttribute("PlayerUnitTrait") and u.BallSkin==part:GetAttribute("PlayerUnitBallSkin")
 end
 S.getBaseTrainingUnits=function()
  local rows={} local parts=baseParts()
  for id,u in D.GetData().PlayerUnits do
   if u.Equipped and not U.IsPercentageUnit(u.PlayerUnitName) and not (S.towerActiveUnits[id] or S.tournamentProtected[id]) then
    for _,part in parts do if matches(part,u) then table.insert(rows,{id=id,unit=u,part=part,score=S.autoEquipScore(u)}) break end end
   end
  end
  table.sort(rows,function(a,b)if a.score~=b.score then return a.score>b.score end if (a.unit.Level or 1)~=(b.unit.Level or 1) then return (a.unit.Level or 1)>(b.unit.Level or 1) end return a.id<b.id end)
  return rows
 end
 S.restoreTrainingBase=function(clearSelection)
  if S.trainingBasePreparing or S.trainingBaseRestoring or not S.trainingBaseUnit then return end
  S.trainingBaseRestoring=true
  task.spawn(function()
   local id=S.trainingBaseUnit local part=S.trainingBaseSlot local acquired=false
   local ok,err=pcall(function()
    local deadline=os.clock()+15
    repeat acquired=S.acquireInventory("Training Base") if not acquired then task.wait(.05) end until acquired or not alive() or os.clock()>=deadline
    if not acquired then status.Training="Base return queued • Click Release to retry" return end
    local u=D.GetData().PlayerUnits[id]
    if not u then status.Training="Selected Striker no longer available" return end
    if not u.Equipped then
     if not part or not part.Parent or part:GetAttribute("Type") then status.Training="Original base slot unavailable • Striker kept protected" return end
     R.PlacePlayerUnitOnDropper:FireServer(part,id)
     if not waitFor(function()local unit=D.GetData().PlayerUnits[id] return unit and unit.Equipped end,2) then status.Training="Base return unconfirmed • Striker kept protected" return end
    end
    S.reservedUnits[id]=nil S.trainingBaseUnit=nil S.trainingBaseSlot=nil S.trainingBaseArmed=nil G.BlueFarmTrainingBaseSession=nil
    if clearSelection then X.unit=nil end
    status.Training="Striker returned to base" S.refreshSelectedUnit() S.saveConfig()
   end)
   if acquired then S.releaseInventory("Training Base") end
   S.trainingBaseRestoring=false
   if not ok then status.Training="Base return: "..tostring(err) end
  end)
 end
 S.selectBaseTraining=function(id)
  if S.trainingBasePreparing or S.trainingBaseRestoring or S.selectingTraining or X.grade or X.trait then status.Training="Stop rerolling before changing Striker" return end
  if S.trainingBaseUnit then status.Training="Release the current base Striker first" return end
  local chosen
  for _,entry in S.getBaseTrainingUnits() do if entry.id==id then chosen=entry break end end
  if not chosen then status.Training="Choose a Striker currently in your base" return end
  S.trainingBasePreparing=true S.reservedUnits[id]=true
  task.spawn(function()
   local acquired=false local selected=false local original=X.unit
   local ok,err=pcall(function()
    local deadline=os.clock()+15
    repeat acquired=S.acquireInventory("Training Base") if not acquired then task.wait(.05) end until acquired or not alive() or os.clock()>=deadline
    if not acquired then status.Training="Base selection queued • Try again" return end
    local u=D.GetData().PlayerUnits[id]
    if not u or not u.Equipped then return end
    if not INV.HasInventorySpace(P,1) then status.Training="Inventory full • Free one slot before selecting from base" return end
    for _,part in baseParts() do
     if not matches(part,u) then continue end
     local before={} for uid,unit in D.GetData().PlayerUnits do if unit.Equipped then before[uid]=true end end
     S.trainingBaseSlot=part
     R.RemovePlayerUnitFromDropper:FireServer(part)
     local removed
     waitFor(function()for uid in before do local unit=D.GetData().PlayerUnits[uid] if unit and not unit.Equipped then removed=uid return true end end return false end,2)
     if removed==id then
      table.clear(S.reservedUnits) S.reservedUnits[id]=true X.unit=id S.trainingBaseUnit=id S.trainingBaseArmed=false selected=true
      G.BlueFarmTrainingBaseSession={id=id,part=part,job=game.JobId,user=P.UserId,armed=false}
      status.Training="Selected from base • Set targets, then enable Grade / Trait" S.refreshSelectedUnit() S.saveConfig() return
     end
     -- Identical base copies cannot be distinguished by visual attributes. Restore
     -- any other copy immediately; never reroll a different inventory ID.
     if removed then
      R.PlacePlayerUnitOnDropper:FireServer(part,removed)
      if not waitFor(function()local unit=D.GetData().PlayerUnits[removed] return unit and unit.Equipped end,2) then S.reservedUnits[removed]=true status.Training="Could not restore identical copy • Kept protected" return end
     elseif part:GetAttribute("Type")~="PlayerUnit" then status.Training="Base removal unconfirmed • Stopped safely" return end
    end
    status.Training="Base removal not confirmed • Try again"
   end)
   if acquired then S.releaseInventory("Training Base") end
   if not selected then S.trainingBaseSlot=nil if original~=id then S.reservedUnits[id]=nil end end
   S.trainingBasePreparing=false
   if not ok then status.Training="Base selection: "..tostring(err) end
  end)
 end
 -- Replacing a base selection first returns the old unit; the user need not
 -- release it manually before choosing another one.
 do
  local prepare=S.selectBaseTraining
  S.selectBaseTraining=function(id)
   if S.trainingBaseSwitching then status.Training="Preparing base Striker" return end
   if S.trainingBaseUnit==id then status.Training="Selected from base • Set targets, then enable Grade / Trait" return end
   if not S.trainingBaseUnit then prepare(id) return end
   S.trainingBaseSwitching=true
   task.spawn(function()
    X.grade=false X.trait=false
    S.restoreTrainingBase(false)
    local deadline=os.clock()+18
    repeat task.wait(.05) until not S.trainingBaseRestoring or not alive() or os.clock()>=deadline
    S.trainingBaseSwitching=false
    if not alive() then return end
    if S.trainingBaseUnit then status.Training="Previous Striker return not confirmed • Selection unchanged" return end
    prepare(id)
   end)
  end
 end
 S.openBaseTrainingPicker=function()
 if S.trainingQueueState and S.trainingQueueState.running then status.Training="Stop Queue before changing Striker" return end
  if S.selectingTraining or S.trainingBasePreparing or S.trainingBaseRestoring or S.trainingBaseSwitching then return end
  local native=P.PlayerGui:FindFirstChild("SelectGui") local frame=native and native:FindFirstChild("MainFrame")
  if not frame then status.Training="Native Striker picker unavailable" return end
  local allowed={} for _,entry in S.getBaseTrainingUnits() do allowed[entry.id]=true end
  if not next(allowed) then status.Training="No eligible Strikers in your base" return end
  local excluded={} for id in D.GetData().PlayerUnits do if not allowed[id] then excluded[id]=true end end
  X.grade=false X.trait=false S.selectingTraining=true
  local connection local finished=false
  local function restore()
   if finished then return end finished=true S.selectingTraining=false
   if connection then connection:Disconnect() connection=nil end
   S.basePickerCallback=nil
   if panel.Parent and S.setMinimized then S.setMinimized(false,true) end
  end
  local ok,err=pcall(function()
   local client=require(RS.Client.Core.Gui.SelectGuiClient)
   local function picked(id)
    -- A unit may have moved while the popup was open. Validate against the
    -- current owned base again, rather than accepting a stale card.
    local valid=false for _,entry in S.getBaseTrainingUnits() do if entry.id==id then valid=true break end end
    restore()
    if valid and allowed[id] then S.selectBaseTraining(id) else status.Training="Choose a Striker currently in your base" end
   end
   S.basePickerCallback=picked
   panel.Visible=false
   client.Open(picked,nil,excluded,{IncludeEquipped=true,ExcludePercentageUnits=true})
   connection=frame:GetPropertyChangedSignal("Visible"):Connect(function()if not frame.Visible then restore() end end)
   table.insert(connections,connection)
  end)
  if not ok then restore() status.Training="Base picker: "..tostring(err) end
 end
 S.selectBestBaseTraining=function()
 if S.trainingQueueState and S.trainingQueueState.running then status.Training="Stop Queue before changing Striker" return end
  local rows=S.getBaseTrainingUnits()
  if rows[1] then S.selectBaseTraining(rows[1].id) else status.Training="No eligible Strikers in your base" end
 end
end)() end

do (function()
 local q={running=false,index=1,phase="idle",status="Queue ready",completed=0}
 S.trainingQueueState=q
 local function protect()
  table.clear(S.trainingQueueProtected)
  for _,entry in X.trainingQueue do S.trainingQueueProtected[entry.id]=true end
 end
 local function changed()protect() S.saveConfig() end
 local function goals(entry,u)return u and entry.grades[u.Grade or "F"]==true and entry.traits[u.Trait or "None"]==true end
 S.trainingQueueGoalsReached=goals
 S.addTrainingQueue=function(id)
  if q.running or q.stopping then q.status="Stop Queue before editing" return false end
  local u=id and D.GetData().PlayerUnits[id]
  if not u or U.IsPercentageUnit(u.PlayerUnitName) then q.status="Select an eligible base Striker first" return false end
  local inBase=S.trainingBaseUnit==id
  for _,entry in S.getBaseTrainingUnits() do if entry.id==id then inBase=true break end end
  if u.Equipped and not inBase or (S.towerActiveUnits[id] or S.tournamentProtected[id]) then q.status="This Striker is unavailable for the queue" return false end
  if not S.hasSelectedTargets(X.gradeTargets) or not S.hasSelectedTargets(X.traitTargets) then q.status="Choose both Grade and Trait targets before adding" return false end
  for i,entry in X.trainingQueue do if entry.id==id then
   entry.grades=table.clone(X.gradeTargets) entry.traits=table.clone(X.traitTargets)
   q.status="Updated queue targets • "..i..". "..u.PlayerUnitName changed() return true
  end end
  if #X.trainingQueue>=64 then q.status="Queue limit: 64" return false end
  table.insert(X.trainingQueue,{id=id,grades=table.clone(X.gradeTargets),traits=table.clone(X.traitTargets)})
  q.status="Added to queue • "..#X.trainingQueue..". "..u.PlayerUnitName changed() return true
 end
 S.stopTrainingQueue=function(reason)
  if X.trainingQueueRunning then X.noRollLimit=X.trainingQueuePreviousNoLimit X.trainingQueueRunning=false end
  local preparing=q.phase=="preparing" or q.phase=="rolling"
  q.running=false q.status=reason or "Queue stopped" q.phase="idle" q.activeId=nil
  X.grade=false X.trait=false
  if preparing then
   q.stopping=true
   task.spawn(function()
    local deadline=os.clock()+40
    repeat task.wait(.05) until not S.trainingBasePreparing and not S.trainingBaseSwitching and not S.trainingBaseRestoring or not alive() or os.clock()>=deadline
    if alive() and not q.running and S.trainingBaseUnit and S.trainingQueueProtected[S.trainingBaseUnit] then
     S.restoreTrainingBase()
     repeat task.wait(.05) until not S.trainingBaseRestoring or not alive() or os.clock()>=deadline
    end
    q.stopping=false
   end)
  elseif S.trainingBaseArmed then S.restoreTrainingBase() end
 end
 S.startTrainingQueue=function()
  if q.running or q.stopping then return end
  if #X.trainingQueue==0 then q.status="Queue empty" return end
  for _,entry in X.trainingQueue do if not S.hasSelectedTargets(entry.grades) or not S.hasSelectedTargets(entry.traits) then q.status="Queue entry needs both target lists" return end end
  X.trainingQueuePreviousNoLimit=X.noRollLimit X.noRollLimit=true X.trainingQueueRunning=true
  X.grade=false X.trait=false q.running=true q.index=1 q.completed=0 q.phase="idle" q.activeId=nil q.status="Queue started" protect()
 end
 S.removeTrainingQueue=function(index)
  if q.running or q.stopping then q.status="Stop Queue before editing" return end
  table.remove(X.trainingQueue,index) changed()
 end
 S.moveTrainingQueue=function(index,delta)
  if q.running or q.stopping then q.status="Stop Queue before editing" return end
  local other=index+delta if other<1 or other>#X.trainingQueue then return end
  X.trainingQueue[index],X.trainingQueue[other]=X.trainingQueue[other],X.trainingQueue[index] changed()
 end
 S.clearTrainingQueue=function()
  if q.running or q.stopping then q.status="Stop Queue before editing" return end
  table.clear(X.trainingQueue) q.index=1 q.completed=0 q.status="Queue empty" changed()
 end
 S.openTrainingQueuePicker=function(mode)
   if not S.hasSelectedTargets(X.gradeTargets) or not S.hasSelectedTargets(X.traitTargets) then
    q.status="เลือกเป้าหมาย Grade และ Trait อย่างน้อยอย่างละ 1 รายการก่อนเพิ่ม Striker"
    if S.queueFeedback then S.queueFeedback.Text=q.status end
    return
   end
  if q.running or q.stopping or S.selectingTraining then q.status="Stop Queue before editing" return end
  local allowed={}
  if mode=="base" then
   for _,entry in S.getBaseTrainingUnits() do allowed[entry.id]=true end
  else
   for id,u in D.GetData().PlayerUnits do if not u.Equipped and not U.IsPercentageUnit(u.PlayerUnitName) and not (S.towerActiveUnits[id] or S.tournamentProtected[id]) then allowed[id]=true end end
  end
  for _,entry in X.trainingQueue do allowed[entry.id]=nil end
  if not next(allowed) then q.status=mode=="base" and "No unqueued Strikers in your base" or "No unqueued Strikers outside your base" return end
  local excluded={} for id in D.GetData().PlayerUnits do if not allowed[id] then excluded[id]=true end end
  local native=P.PlayerGui:FindFirstChild("SelectGui") local frame=native and native:FindFirstChild("MainFrame")
  if not frame then q.status="Native Striker picker unavailable" return end
  S.selectingTraining=true local c local finished=false
  local function restore()if finished then return end finished=true S.selectingTraining=false if c then c:Disconnect() c=nil end if S.setMinimized then S.setMinimized(false,true) end end
  local ok,err=pcall(function()
   panel.Visible=false
   require(RS.Client.Core.Gui.SelectGuiClient).Open(function(id)restore() if allowed[id] then S.addTrainingQueue(id) end end,nil,excluded,{IncludeEquipped=mode=="base",ExcludePercentageUnits=true})
   c=frame:GetPropertyChangedSignal("Visible"):Connect(function()if not frame.Visible then restore() end end) table.insert(connections,c)
  end)
  if not ok then restore() q.status="Queue picker: "..tostring(err) end
 end
 S.trainingQueueTick=function()
  if not q.running or not S.enabled or S.nativeMenuRequested or S.selectingTraining or S.trainingBasePreparing or S.trainingBaseRestoring or S.trainingBaseSwitching then return end
  local entry=X.trainingQueue[q.index]
  if not entry then S.stopTrainingQueue("Queue complete") return end
  local u=D.GetData().PlayerUnits[entry.id]
  if not u then S.stopTrainingQueue("Queued Striker unavailable") return end
  if goals(entry,u) then
   X.grade=false X.trait=false q.completed+=1 q.activeId=nil q.phase="idle"
   table.remove(X.trainingQueue,q.index)
   if X.unit==entry.id then X.unit=nil S.refreshSelectedUnit() end
   q.status="Targets reached • Removed from queue"
   if S.trainingBaseUnit==entry.id then S.restoreTrainingBase() else S.reservedUnits[entry.id]=nil end
   changed()
   return
  end
  if q.activeId~=entry.id then
   X.grade=false X.trait=false
   if not u.Equipped and S.trainingBaseUnit and S.trainingBaseUnit~=entry.id then
    S.restoreTrainingBase(false) q.status="Returning previous base Striker" return
   end
   if q.phase=="preparing" then
    if S.trainingBaseUnit~=entry.id or u.Equipped then S.stopTrainingQueue("Could not prepare queued Striker • Check Training status") return end
   elseif u.Equipped then
    q.phase="preparing" q.status="Preparing queued Striker" S.selectBaseTraining(entry.id) return
   end
   X.unit=entry.id S.reservedUnits[entry.id]=true
   table.clear(X.gradeTargets) for name,on in entry.grades do X.gradeTargets[name]=on end
   table.clear(X.traitTargets) for name,on in entry.traits do X.traitTargets[name]=on end
   S.trainingStops.grade=nil S.trainingStops.trait=nil q.activeId=entry.id q.phase="rolling"
   S.refreshSelectedUnit()
  end
  if X.unit~=entry.id then S.stopTrainingQueue("Selection changed • Queue stopped") return end
  for _,kind in {"grade","trait"} do
   local stop=S.trainingStops[kind]
   if stop=="Tokens depleted" or stop=="Not enough cash" or stop=="Roll limit reached" then S.stopTrainingQueue("Queue stopped • "..stop) return end
  end
  X.grade=entry.grades[u.Grade or "F"]~=true X.trait=entry.traits[u.Trait or "None"]~=true
  q.status="Queue "..q.index.." / "..#X.trainingQueue.." • "..u.PlayerUnitName
 end
end)() end

worker("Training",0.02,function()
 if S.trainingQueueTick then S.trainingQueueTick() end
 if S.trainingTrip and (not S.enabled or not X.grade and not X.trait or X.unit~=S.trainingTrip.unit or P.Character~=S.trainingTrip.char) then S.finishTrainingTrip() end
 if not S.enabled or S.nativeMenuRequested or S.selectingTraining then return end
 if type(S.checkCollectionGround)~="function" or type(S.returnTrainingSafe)~="function" then return end
 -- Rerolls do not use the character or equipped tool. Only station travel
 -- waits for movement ownership; remote-capable rolls may run concurrently.
 for _,kind in {"grade","trait"} do
 if X[kind] and not enabledBefore[kind] then rollCounts[kind]=0 S.trainingStops[kind]=nil end
 enabledBefore[kind]=X[kind]
 end
 if not X.grade and not X.trait then S.finishTrainingTrip() if S.trainingBaseArmed and S.restoreTrainingBase then S.restoreTrainingBase() end return end
 if S.trainingBaseUnit==X.unit then S.trainingBaseArmed=true if G.BlueFarmTrainingBaseSession then G.BlueFarmTrainingBaseSession.armed=true end end
 if S.trainingBasePreparing or S.trainingBaseRestoring then status.Training="Preparing base Striker" return end
 local id=X.unit local unit=id and D.GetData().PlayerUnits[id]
 if not unit then S.finishTrainingTrip() status.Training="เลือก Striker สำรองก่อน" return end
 if U.IsPercentageUnit(unit.PlayerUnitName) then X.grade=false X.trait=false S.finishTrainingTrip() status.Training="This Striker cannot be rerolled • Choose a supported spare" return end
 if unit.Equipped then status.Training="นำตัวที่เลือกออกจาก Base ก่อน" return end
 if U.IsPlayerUnitFavorited(P,id) and S.trainingBaseUnit~=id and not S.trainingQueueProtected[id] then X.grade=false X.trait=false status.Training="หยุด: ตัวนี้เป็น Favorite" return end
 for _,kind in {"grade","trait"} do
 if X[kind] then
 if not alive() or not S.enabled then return end
 local service=kind=="grade" and GS or TS
 local token=kind=="grade" and "Grade" or "Trait"
 local targets=kind=="grade" and X.gradeTargets or X.traitTargets
 local waiting=S.trainingPending[kind]
 if waiting and waiting.id~=id then S.trainingPending[kind]=nil waiting=nil end
 if waiting then
 if S.trainingResultConfirmed(waiting) then
 rollCounts[kind]+=1 S.confirmed.rolls=(S.confirmed.rolls or 0)+1
 S.trainingPending[kind]=nil S.trainingFailures[kind]=0 S.trainingStops[kind]=nil cooldown["roll:"..kind]=math.max(waiting.nextAt or 0,os.clock()+0.08) S.trainingTiming.confirmed+=1
 elseif os.clock()<waiting.deadline then
 status.Training=token.." • Waiting for server confirmation" continue
 else
 S.trainingPending[kind]=nil
 S.trainingFailures[kind]=(S.trainingFailures[kind] or 0)+1 S.trainingTiming.timeouts+=1
 cooldown["roll:"..kind]=os.clock()+math.min(3,0.5*S.trainingFailures[kind])
 status.Training=token.." • Server delayed; retrying after cooldown"
 continue
 end
 end
 if not S.hasSelectedTargets(targets) then X[kind]=false S.trainingStops[kind]="No targets selected" status.Training="เลือกรายการเป้าหมายก่อนเปิดสุ่ม" continue end
 local result=kind=="grade" and (unit.Grade or "F") or unit.Trait
 local reached=result~=nil and targets[result]==true
 if reached then X[kind]=false S.trainingStops[kind]="Target reached" status.Training=token.." ถึงเป้าหมายแล้ว" continue end
 if not X.noRollLimit and rollCounts[kind]>=X.rollLimit then X[kind]=false S.trainingStops[kind]="Roll limit reached" status.Training=token.." ครบจำนวนที่กำหนด" continue end
 local useTokens=kind~="grade" or not X.gradeCash
 local before=D.GetData().Tokens[token] or 0
 if useTokens then
 if before<=0 then X[kind]=false S.trainingStops[kind]="Tokens depleted" status.Training=token.." Token หมด" continue end
 else
 local cost=U.GetGradeRerollCost(P,{PlayerUnitName=unit.PlayerUnitName,PlayerUnitVariant=unit.Variant,PlayerUnitLevel=unit.Level,PlayerUnitTrait=unit.Trait})
 if type(cost)~="number" or cost<0 or cost==math.huge or cost>(D.GetData().Currency.Cash or 0) then X.grade=false S.trainingStops.grade="Not enough cash" status.Training="เงินไม่พอสุ่ม Grade" continue end
 end
 local needsTravel=not GS.CanReachRollStation(P,service.HITBOX_TAG)
 if needsTravel and ((S.collect and S.collect.walking) or S.tpReturnActive or S.sharedTravelActive or S.obbyTravel or S.shopOpen) then
  status.Training=token.." • Waiting for station travel; Auto remains ON" continue
 end
 if needsTravel and not X.trainingTP then
 status.Training="Out of station range • Enable station travel in Roll controls, or move to the station" continue
 end
 if os.clock()>=(cooldown["roll:"..kind] or 0) then
 local trip
 local function restoreTraining()
 if trip and P.Character==trip.char and trip.root.Parent and trip.human.Health>0 then
  if alive() and S.enabled and (X.grade or X.trait) and X.unit==id and GS.CanReachRollStation(P,service.HITBOX_TAG) then
   S.trainingTrip=trip S.trainingTravel=true return
  end
  if S.returnTrainingSafe then S.returnTrainingSafe(trip.origin,true) end
 end
 if not S.trainingTrip then S.trainingTravel=false end
 end
 local rollOK,rollError=pcall(function()
 if needsTravel then
 S.trainingTravel=true
 if S.stopCollectionTravel then S.stopCollectionTravel() end
 local char=P.Character local root=char and char:FindFirstChild("HumanoidRootPart") local human=char and char:FindFirstChildOfClass("Humanoid")
 if not root or not human or human.Health<=0 or root.Anchored or human.Sit then status.Training="Waiting for character" return end
 local origin=S.checkCollectionGround and S.checkCollectionGround(root.Position)
 local destination
 for _,station in CS:GetTagged(service.HITBOX_TAG) do
 if station:IsA("BasePart") then
 for _,offset in {Vector3.new(0,0,16),Vector3.new(16,0,0),Vector3.new(-16,0,0),Vector3.new(0,0,-16),Vector3.zero} do
 local sample=station.Position+offset+Vector3.new(0,-station.Size.Y/2+3,0)
 local point=S.checkCollectionGround(sample)
 if point and (point-station.Position).Magnitude<20 then destination=point break end
 end
 end
 if destination then break end
 end
 if not origin or not destination then status.Training="No safe station travel point" return end
 trip={char=char,root=root,human=human,unit=id,origin=S.trainingTrip and S.trainingTrip.origin or CFrame.new(origin)*root.CFrame.Rotation}
 status.Training=X.collectMode.." • Travelling to roll station"
 local travelled=S.travelTo and S.travelTo(CFrame.new(destination)*root.CFrame.Rotation,function()return alive() and X[kind] and X.unit==id and P.Character==char end,true)
 if not travelled then status.Training="No safe route to rolling station" return end
 local arrived=waitFor(function()return P.Character~=char or (GS.IsInRollRange(P,service.HITBOX_TAG) and (root.Position-destination).Magnitude<8) end,1.2,0.01)
 if not arrived or not alive() or not S.enabled or not X[kind] or P.Character~=char or human.Health<=0 or not GS.CanReachRollStation(P,service.HITBOX_TAG) then status.Training="Station travel cancelled or out of range" return end
 S.trainingTrips=(S.trainingTrips or 0)+1
 task.wait(math.max(0.2,S.travelValue("travelSettle")))
 end
 unit=D.GetData().PlayerUnits[id]
 if not unit or unit.Equipped or not X[kind] or not S.enabled or U.IsPlayerUnitFavorited(P,id) and S.trainingBaseUnit~=id and not S.trainingQueueProtected[id] then return end
 if targets[unit[token]] then X[kind]=false S.trainingStops[kind]="Target reached" return end
 local request={id=id,token=token,old=unit[token],revision=gradeRevisions[token..":"..id] or 0,useTokens=useTokens,tokens=D.GetData().Tokens[token] or 0,pity=table.clone(unit[token.."Pity"] or {}),deadline=os.clock()+3}
 request.sentAt=os.clock() request.nextAt=request.sentAt+service.GetRerollCooldown(P,useTokens)+0.12
 S.trainingPending[kind]=request
 if kind=="grade" then R.NewRerollPlayerUnitGrade:FireServer(id,useTokens,unit.Grade) else R.RerollPlayerUnitTrait:FireServer(id,unit.Trait) end
 -- Server response and cooldown run concurrently; never add a second full cooldown after acknowledgement.
 cooldown["roll:"..kind]=request.nextAt
 local changed=waitFor(function()return not S.running or S.trainingResultConfirmed(request) end,1.5,0.01)
 if not S.running then return end
 if changed then
 rollCounts[kind]+=1 S.confirmed.rolls=(S.confirmed.rolls or 0)+1
 S.trainingPending[kind]=nil S.trainingFailures[kind]=0 S.trainingStops[kind]=nil cooldown["roll:"..kind]=math.max(request.nextAt,os.clock()+0.08) S.trainingTiming.confirmed+=1
 status.Training=token.." "..rollCounts[kind].."/"..(X.noRollLimit and "∞" or tostring(math.floor(X.rollLimit))).." • ยืนยันแล้ว"
 else status.Training=token.." • Waiting for server confirmation; Auto remains ON" end
 end)
 restoreTraining()
 if not rollOK then error(rollError) end
 break
 end
 end
 end
end)
local function latestTower()
 for i=#towerNames,1,-1 do
 if not IT.GetPlayBlockReason(P,towerNames[i].name) then return towerNames[i].name end
 end
 return towerNames[1].name
end
