local towerManaged=false local towerActive=nil
worker("Tower",3,function()
 if X.towerLatest then X.towerName=latestTower() end
 if not X.tower then
 if towerManaged and towerActive then R.SetInfinityTowerAutoBattle:FireServer(towerActive,false) towerManaged=false end
 table.clear(S.towerActiveUnits) status.Tower="OFF" return
 end
 local current=R.GetInfinityTowerBattleState:InvokeServer()
 if not alive() or not S.enabled or not X.tower then return end
 if current then
 towerActive=current.TowerName
 if not current.AutoBattle then R.SetInfinityTowerAutoBattle:FireServer(current.TowerName,true) end
 towerManaged=true status.Tower=current.TowerName.." • ชั้น "..tostring(current.Floor).." • Auto Battle" return
 end
 local reason=IT.GetPlayBlockReason(P,X.towerName) if reason then status.Tower=reason return end
 if not ready("towerStart",12) then return end
 local team={}
 if X.towerBest then
 local battle=require(RS.Shared.Services.InfinityTowerBattleService)
 local units={} for id in D.GetData().PlayerUnits do if not S.reservedUnits[id] and not S.tournamentProtected[id] then table.insert(units,{id=id,score=battle.GetDamageFromCashPerDrop(U.GetDamageBasis(P,id))*battle.GetHealthFromCashPerDrop(U.GetHealthBasis(P,id))}) end end
 table.sort(units,function(a,b)if a.score==b.score then return a.id<b.id end return a.score>b.score end)
 for i=1,math.min(#units,require(RS.Shared.Constants).InfinityTowerUnitSlots) do table.insert(team,units[i].id) end
 else
 local seen={}
 for i=1,require(RS.Shared.Constants).InfinityTowerUnitSlots do
 local id=X.towerTeam[i]
 if id and D.GetData().PlayerUnits[id] and not seen[id] and not S.reservedUnits[id] and not S.tournamentProtected[id] then table.insert(team,id) seen[id]=true end
 end
 end
 if #team==0 then status.Tower="ยังไม่ได้เลือกทีมหอคอย" return end
 table.clear(S.towerActiveUnits) for _,id in team do S.towerActiveUnits[id]=true end
 local result=R.StartInfinityTowerBattle:InvokeServer(X.towerName,team)
 if type(result)=="table" and result.TowerName then
 towerActive=result.TowerName towerManaged=true
 if alive() and S.enabled and X.tower then R.SetInfinityTowerAutoBattle:FireServer(result.TowerName,true) end
 status.Tower=result.TowerName.." • เริ่มทีม "..#team.." ตัว" S.confirmed.towerStarts=(S.confirmed.towerStarts or 0)+1
 else table.clear(S.towerActiveUnits) status.Tower="เริ่มรอบยังไม่ยืนยัน" end
end)
