local function mark(key,part,pos,text)
 local m=markers[key]
 if not m then
 local anchor=part
 if not anchor then anchor=make("Part",workspace,{Name="BlueFarmMarker",Size=Vector3.new(0.1,0.1,0.1),Anchored=true,CanCollide=false,CanTouch=false,CanQuery=false,Transparency=1,Position=pos}) end
 local bb=make("BillboardGui",gui,{Adornee=anchor,Size=UDim2.fromOffset(175,38),StudsOffsetWorldSpace=Vector3.new(0,3,0),AlwaysOnTop=true})
 local l=label(bb,text,38) l.Size=UDim2.fromScale(1,1) l.TextColor3=blue l.TextStrokeTransparency=0.3 l.TextXAlignment=Enum.TextXAlignment.Center
 m={billboard=bb,anchor=not part and anchor or nil,label=l} markers[key]=m
 end
 m.seen=true m.label.Text=text if m.anchor then m.anchor.Position=pos end
end
local function clearMarkers()
 for key,m in markers do m.billboard:Destroy() if m.anchor then m.anchor:Destroy() end markers[key]=nil end
end
table.insert(connections,gui.Destroying:Connect(clearMarkers))
