local collect={available={},confirmed=0,requests=0,walking=false,target=nil,status="",mapCount=0,rainCount=0,variantCount=0}
S.collect=collect
local candidates={} local pending={} local watched={}
local tpTrip local returnFromTP
local routeBlocked={} local manualUntil=0 local walkingHumanoid
S.attemptedTargets=setmetatable({},{__mode="k"})
S.attemptedRain={}
S.pickupVisuals={}
S.collectionReceipts={}
S.confirmCollectionReceipt=function(key)
 if S.collectionReceipts[key] then return end
 S.collectionReceipts[key]=true S.collectionRecoveries=0 collect.confirmed+=1 S.confirmed.mapAndEventItems=collect.confirmed
end
S.recordTravelAttempt=function(c)
 local entries=c.node and S.attemptedTargets or S.attemptedRain
 local key=c.node or c.id
 local previous=entries[key]
 entries[key]={count=(type(previous)=="table" and previous.count or 0)+1,nextAt=os.clock()+(c.kind=="variant" and 0.75 or S.travelValue("travelRetryDelay"))}
end
S.canTravelTarget=function(c)
 local entry=c.node and S.attemptedTargets[c.node] or S.attemptedRain[c.id]
 return not entry or (type(entry)=="table" and (entry.count<(c.kind=="variant" and 8 or math.floor(S.travelValue("travelMaxAttempts")))) and os.clock()>=entry.nextAt and (not c.node or (c.kind=="variant" or c.visual and c.visual.Parent~=nil)))
end
local function manualControl()
 for _,key in {Enum.KeyCode.W,Enum.KeyCode.A,Enum.KeyCode.S,Enum.KeyCode.D,Enum.KeyCode.Space} do
 if UIS:IsKeyDown(key) then manualUntil=os.clock()+S.travelValue("travelManualPause") return true end
 end
 return os.clock()<manualUntil
end
local function ownedItem(name)
 local data=D.GetData()
 return (tonumber((data.Tokens or {})[name]) or 0)+(tonumber((data.Potions or {})[name]) or 0)+(tonumber((data.VariantTokens or {})[name]) or 0)
end
local function confirmPickup(key)
 local entry=pending[key] if not entry or entry.checking then return end
 entry.checking=true
 task.spawn(function()
 if waitFor(function()return pending[key]~=entry or entry.serverConfirmed or ownedItem(entry.item)>entry.before end,1.5) and pending[key]==entry and (entry.serverConfirmed or ownedItem(entry.item)>entry.before) then
 S.confirmCollectionReceipt(key)
 if tpTrip and tpTrip.key==key and returnFromTP then returnFromTP(true) end
 end
 if pending[key]==entry then pending[key]=nil end
 end)
end
-- Each observable spawn owns its requests, retries and receipt state.
S.variantSpawns=setmetatable({},{__mode="k"})
if not G.BlueFarmVariantEvidence or G.BlueFarmVariantEvidence.session~=game.JobId then G.BlueFarmVariantEvidence={session=game.JobId,events={}} end
S.variantEvidence=G.BlueFarmVariantEvidence.events
local variantLibrary=require(RS.Shared.Core.Storage.Game.VariantTokensLibrary)
local function resetSpawn(node)
 local old=S.variantSpawns[node]
 local item=node:GetAttribute("Variant")
 S.variantSpawns[node]={generation=(old and old.generation or 0)+1,item=item,
  observedAt=workspace:GetServerTimeNow(),expiresAt=workspace:GetServerTimeNow()+((variantLibrary[item] or {}).DespawnTime or 25)}
 S.attemptedTargets[node]=nil routeBlocked[node]=nil S.collectionReceipts[node]=nil
 pending[node]=nil
 if S.resetReady then S.resetReady(node) end
end
local function watchNode(node)
 if watched[node] then return end watched[node]=true
 local variant=CS:HasTag(node,"VariantTokenSpawn")
 if variant then resetSpawn(node) end
 table.insert(connections,node:GetAttributeChangedSignal("Occupied"):Connect(function()
  if node:GetAttribute("Occupied")~=true then confirmPickup(node)
  elseif variant then resetSpawn(node)
  else S.attemptedTargets[node]=nil routeBlocked[node]=nil S.collectionReceipts[node]=nil end
 end))
 if variant then
  table.insert(connections,node:GetAttributeChangedSignal("Variant"):Connect(function()resetSpawn(node)end))
 end
end
for _,node in CS:GetTagged("VariantTokenSpawn") do watchNode(node) end
table.insert(connections,CS:GetInstanceAddedSignal("VariantTokenSpawn"):Connect(watchNode))
-- Server announcements are evidence of the collector, not an assumed receipt for a node.
if R:FindFirstChild("VariantTokenFound") then
 table.insert(connections,R.VariantTokenFound.OnClientEvent:Connect(function(who,item)
  table.insert(S.variantEvidence,{at=workspace:GetServerTimeNow(),collector=tostring(who),item=item,
   ours=tostring(who)==P.Name or tostring(who)==tostring(P.UserId)})
  if #S.variantEvidence>100 then table.remove(S.variantEvidence,1) end
  if tostring(who)==P.Name or tostring(who)==tostring(P.UserId) then
   local matches={}
   for node,entry in pending do
    local spawn=S.variantSpawns[node]
    if spawn and spawn.generation==entry.generation and entry.item==item and entry.sentAt and os.clock()-entry.sentAt<=5 then table.insert(matches,{node=node,entry=entry}) end
   end
   -- A type-only announcement cannot identify multiple same-type pending requests.
   if #matches==1 then matches[1].entry.serverConfirmed=true confirmPickup(matches[1].node) end
  end
 end))
end
local function requestPickup(key,item,callback)
 local spawn=S.variantSpawns and S.variantSpawns[key]
 local previous=pending[key]
 if previous and spawn and previous.generation~=spawn.generation then pending[key]=nil previous=nil end
 if previous and (previous.checking or os.clock()-(previous.sentAt or previous.at)<S.travelValue("pickupRetry")) then return end
 if not previous then pending[key]={item=item,before=ownedItem(item),at=os.clock(),generation=spawn and spawn.generation} end
 pending[key].sentAt=os.clock()
 callback() collect.requests+=1
end
table.insert(connections,R.ItemRainRemoved.OnClientEvent:Connect(function(id) confirmPickup("rain:"..tostring(id)) end))
local function enabledTarget(c)
 if c.kind=="map" then return X.mapCollect and (S.variantCatalog[c.name] and X.collectVariants or X.collectItems)[c.name]~=false end
 if c.kind=="variant" then return (X.events) and X.eventKinds.variant~=false and X.collectVariants[c.name]~=false end
 if not X.events then return false end
 return X.eventKinds.rain~=false and (S.variantCatalog[c.name] and X.collectVariants or X.collectItems)[c.name]~=false
end
S.isCollectionTargetEnabled=enabledTarget
do
 S.eventDiscovery={placeVersion=game.PlaceVersion,status="Checking",schedule={},systems={}}
 S.scanEventStatus=function()
  if S.eventDiscovery.scanning or not alive() then return end
  S.eventDiscovery.scanning=true
  task.spawn(function()
   local report=S.eventDiscovery
   local ok,err=pcall(function()
    report.systems={}
    for name,remoteName in {Map="CollectCollectableObject",Variant="CollectVariantTokenSpawn",Rain="CollectItemRainItem",Obby="ClaimObbyBonus",Jackpot="JackpotSpin"} do
     report.systems[name]=R:FindFirstChild(remoteName)~=nil
    end
    report.admin=RS.Shared.Services:FindFirstChild("AdminAbuseService")~=nil
    local module=RS.Shared.Services:FindFirstChild("RobloxGameEventsService")
    if module then
     local service=require(module)
     if type(service.GetUpcomingEventsAsync)=="function" then report.schedule=service.GetUpcomingEventsAsync() end
    end
    report.checkedAt=os.clock() report.status="Supported systems checked"
   end)
   if not ok then report.status="Discovery unavailable: "..tostring(err) end
   report.scanning=false
  end)
 end
 S.scanEventStatus()
 worker("Event status",1,function()
  local report=S.eventDiscovery
  local lines={"Game version: "..report.placeVersion.." • "..report.status}
  local names={} for name,available in report.systems do if available then table.insert(names,name) end end table.sort(names)
  table.insert(lines,"Detected: "..table.concat(names,", "))
  local module=RS.Shared.Services:FindFirstChild("WeatherService")
  if module then
   local ok,name,remaining=pcall(function()
    local weather=require(module)
    return weather.GetCurrentWeather(),weather.GetSecondsUntilNextWeather()
   end)
   if ok then table.insert(lines,"Weather: "..tostring(name or "None").." • Next cycle: "..math.ceil(remaining or 0).."s") end
  end
  local folder=RS:FindFirstChild("AdminAbuse") local boosts={}
  if folder then for name,endsAt in folder:GetAttributes() do if type(endsAt)=="number" and endsAt>workspace:GetServerTimeNow() then table.insert(boosts,name.." "..math.ceil(endsAt-workspace:GetServerTimeNow()).."s") end end end
  table.sort(boosts)
  table.insert(lines,"Admin boosts: "..(#boosts>0 and table.concat(boosts,", ") or "None active"))
  local scheduled
  for _,event in report.schedule or {} do
   if event.HasStarted and not event.HasEnded then table.insert(lines,"Active event: "..tostring(event.Title))
   elseif not event.HasEnded and (not scheduled or (event.StartTime or math.huge)<(scheduled.StartTime or math.huge)) then scheduled=event end
  end
  table.insert(lines,scheduled and ("Next event: "..tostring(scheduled.Title).." • "..math.max(0,math.ceil((scheduled.StartTime or 0)-workspace:GetServerTimeNow())).."s") or "No upcoming event reported by Roblox")
  table.insert(lines,"Jackpot / Admin controls are detected only; no spins, votes or consumables are sent.")
  if S.liveEventInfo and S.liveEventInfo.Parent then S.liveEventInfo.Text=table.concat(lines,"\n") end
 end)
end
local function exists(c)
 if c.kind=="variant" then
  local current=S.variantSpawns[c.node]
  if not current or current.generation~=c.generation or current.item~=c.name then return false end
 elseif c.visual and not c.visual:IsDescendantOf(workspace) then return false end
 if c.node then return c.node:IsDescendantOf(workspace) and c.node:GetAttribute("Occupied")==true and (c.node.Position-c.pos).Magnitude<1 end
 return rains[c.id]~=nil
end
local activeTravelTween local anchoredRoot local previousAnchored local rotateHumanoid local previousAutoRotate
local lastSafe local travelOrigin
-- A missing raycast never becomes a destination. Sample the footprint as well
-- as its centre so a tiny prop or an edge cannot be mistaken for a floor.
local function safeStanding(pos,character,human,root,ignore)
 if typeof(pos)~="Vector3" or pos.X~=pos.X or pos.Y~=pos.Y or pos.Z~=pos.Z or pos.Magnitude>1e6 then return nil end
 local height=human.RigType==Enum.HumanoidRigType.R6 and 3 or math.max(2.5,human.HipHeight+root.Size.Y/2)
 local params=RaycastParams.new() params.FilterType=Enum.RaycastFilterType.Exclude
 params.FilterDescendantsInstances=ignore and {character,ignore} or {character} params.RespectCanCollide=true params.CollisionGroup=root.CollisionGroup
 local centre=workspace:Raycast(pos+Vector3.new(0,1,0),Vector3.new(0,-height-5,0),params)
 if not centre or centre.Normal.Y<0.7 or centre.Position.Y>pos.Y+0.5 or pos.Y-centre.Position.Y>height+3 then return nil end
 if centre.Instance:IsA("BasePart") and not centre.Instance.Anchored then return nil end
 for _,offset in {Vector3.new(1,0,0),Vector3.new(-1,0,0),Vector3.new(0,0,1),Vector3.new(0,0,-1)} do
 local hit=workspace:Raycast(centre.Position+offset+Vector3.new(0,1,0),Vector3.new(0,-2,0),params)
 if not hit or hit.Normal.Y<0.7 or math.abs(hit.Position.Y-centre.Position.Y)>0.65 then return nil end
 end
 local destination=centre.Position+Vector3.new(0,height+0.15,0)
 -- Reject standing inside collidable geometry (e.g. a shop podium).
 -- Mesh bounding boxes can span the entire stadium; use actual collision rays.
 for _,offset in {Vector3.zero,Vector3.new(0.8,0,0),Vector3.new(-0.8,0,0),Vector3.new(0,0,0.8),Vector3.new(0,0,-0.8)} do
 if workspace:Raycast(centre.Position+offset+Vector3.new(0,0.2,0),Vector3.new(0,height+2,0),params) then return nil end
 end
 return destination
end
do
 (function()
  local lastWrite=0 local dirty=true
  S.travelAudit={version=S.version,placeVersion=game.PlaceVersion,moves=0,recoveries=0,events={},lastError=""}
  S.saveTravelAudit=function()
   -- Diagnostics stay in memory.
   lastWrite=os.clock() dirty=false
   return true
  end
  S.recordTravel=function(kind,from,to)
   local audit=S.travelAudit
   dirty=true
   local now=os.clock()
   local entry={kind=kind,time=workspace:GetServerTimeNow(),distance=(to-from).Magnitude,gap=audit.lastMoveAt and now-audit.lastMoveAt or nil}
   audit.lastMoveAt=now audit.moves+=1
   if kind=="emergency recovery" then audit.recoveries+=1 end
   table.insert(audit.events,entry) if #audit.events>40 then table.remove(audit.events,1) end
  end
  S.performTP=function(frame,keepGoing,reason,ignore)
   local char=P.Character local root=char and char:FindFirstChild("HumanoidRootPart") local human=char and char:FindFirstChildOfClass("Humanoid")
   local function valid()return alive() and S.enabled and not S.travelSuspended and G.BlueFarm==S and P.Character==char and root and root.Parent and human and human.Health>0 and (not keepGoing or keepGoing())end
   local queuedAt=os.clock()
   while S.tpBusy or os.clock()<(S.nextTravelTP or 0) do
    if not valid() or os.clock()-queuedAt>5 then return false end
    task.wait(0.02)
   end
   if not valid() then return false end
   local point=safeStanding(frame.Position,char,human,root,ignore)
   if not point then return false end
   if (root.Position-point).Magnitude<1 then return true end
   S.tpBusy=true
   local releaseCollision=function()end
   local ok,moved=pcall(function()
    if workspace.StreamingEnabled and (root.Position-point).Magnitude>64 then
     local streamed=false
     task.spawn(function()pcall(P.RequestStreamAroundAsync,P,point,1) streamed=true end)
     local streamDeadline=os.clock()+1.5
     repeat task.wait(0.02) until streamed or not valid() or os.clock()>=streamDeadline
    end
    if not valid() then return false end
    releaseCollision=S.beginTravelNoclip(char)
    local origin=root.Position
    root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
    char:PivotTo(CFrame.new(point)*frame.Rotation*root.CFrame:ToObjectSpace(char:GetPivot()))
    root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
    S.nextTravelTP=os.clock()+S.travelValue("collectTPDelay")
    S.recordTravel(reason or "normal TP",origin,point)
    return true
   end)
   pcall(releaseCollision) S.tpBusy=false
   if not ok then S.travelAudit.lastError=tostring(moved) return false end
   return moved==true
  end
  local ok,signal=pcall(function()return game:GetService("GuiService").ErrorMessageChanged end)
  if ok and typeof(signal)=="RBXScriptSignal" then
   local connected,connection=pcall(function()return signal:Connect(function(message)
    if type(message)~="string" or message=="" then return end
    S.travelAudit.lastError=tostring(message):sub(1,1500)
    dirty=true
    S.saveTravelAudit()
   end) end)
   if connected then table.insert(connections,connection) else S.travelAudit.errorMonitorAvailable=false end
  end
  table.insert(connections,gui.Destroying:Connect(S.saveTravelAudit))
  task.spawn(function()
   while alive() do
    if dirty and os.clock()-lastWrite>=5 then S.saveTravelAudit() end
    task.wait(1)
   end
  end)
 end)()
end
local function safeReturn(frame,character,human,root)
 local point=frame and safeStanding(frame.Position,character,human,root)
 if not point and lastSafe and lastSafe.character==character then frame=lastSafe.frame point=safeStanding(frame.Position,character,human,root) end
 if not point then
 local plots=workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("PlotModels")
 local home=plots and plots:FindFirstChild(P.Name) local spawn=home and home:FindFirstChild("SpawnPart")
 if spawn and spawn:IsA("BasePart") then frame=spawn.CFrame point=safeStanding(spawn.Position+Vector3.new(0,3,0),character,human,root) end
 end
 if not point then return false end
 S.recordTravel("emergency recovery",root.Position,point)
 S.travelSuspended=true S.travelSuspendReason="Unsupported or changed character position • Travel stopped"
 S.nextTravelTP=math.max(S.nextTravelTP or 0,os.clock()+S.travelValue("collectTPDelay"))
 root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
 root.CFrame=CFrame.new(point)*frame.Rotation
 lastSafe={character=character,frame=root.CFrame}
 return true
end
-- Shared recovery for every automated route, including graves and respawns.
-- Only known automatic safety pauses are retryable. Native scenes retain control.
do
 local reasons={
  ["Unsupported or changed character position • Travel stopped"]=true,
  ["No safe return point; travel paused"]=true,
 }
 worker("Travel recovery",0.25,function()
  if not S.travelSuspended then S.travelRecoveryState=nil return end
  if not reasons[S.travelSuspendReason] then return end
  local now=os.clock()
  local recovery=S.travelRecoveryState
  if not recovery then
   recovery={reason=S.travelSuspendReason,at=now,initialCharacter=P.Character} S.travelRecoveryState=recovery
  end
  local char=P.Character
  local root=char and char:FindFirstChild("HumanoidRootPart")
  local human=char and char:FindFirstChildOfClass("Humanoid")
  local camera=workspace.CurrentCamera
  local busy=not root or not human or human.Health<=0 or root.Anchored or human.Sit
   or S.nativeMenuRequested or S.shopOpen or S.selectingTraining
   or S.sharedTravelActive or S.tpBusy or S.tpReturnActive or S.trainingTravel
   or S.obbyTravel
   or char and char:FindFirstChild("KnockBodyPosition",true)
   or camera and camera.CameraType==Enum.CameraType.Scriptable
  if busy or manualControl() or not safeStanding(root.Position,char,human,root) then
   recovery.stableAt=nil recovery.position=nil return
  end
  if recovery.character~=char or not recovery.position or (recovery.position-root.Position).Magnitude>1 then
   recovery.character=char recovery.position=root.Position recovery.stableAt=now
  end
  if now-(recovery.stableAt or now)<2 then return end
  -- Three retries in a minute trigger a cooling period, never a permanent latch.
  local history=S.travelRecoveryHistory or {} S.travelRecoveryHistory=history
  while history[1] and now-history[1]>=60 do table.remove(history,1) end
  if #history>=3 then recovery.retryAt=history[1]+60 return end
  table.insert(history,now)
  S.lastTravelRecovery={at=now,reason=recovery.reason,respawned=recovery.character~=recovery.initialCharacter}
  S.travelSuspended=false S.travelSuspendReason=nil S.travelRecoveryState=nil
 end)
end
S.checkCollectionGround=function(pos)
 local char=P.Character local root=char and char:FindFirstChild("HumanoidRootPart") local human=char and char:FindFirstChildOfClass("Humanoid")
 return root and human and safeStanding(pos,char,human,root) or nil
end
-- Shared normal travel for Training, Obby and collection returns.
-- Recovery from unsupported ground intentionally keeps its immediate safe return.
do
 local active
 S.cancelSharedTravel=function()
  if active then active.cancelled=true if active.tween then active.tween:Cancel() end end
 end
 table.insert(connections,gui.Destroying:Connect(S.cancelSharedTravel))
 S.travelTo=function(frame,keepGoing,directTween)
  if S.collect and S.collect.walking then return false,"Collection owns character movement" end
  if S.travelSuspended then return false,"Travel is paused after a recovery" end
  if active then return false,"Another trip is active" end
  local char=P.Character local root=char and char:FindFirstChild("HumanoidRootPart") local human=char and char:FindFirstChildOfClass("Humanoid")
  if not root or not human or human.Health<=0 or human.Sit or root.Anchored then return false,"Character unavailable" end
  local destination=safeStanding(frame.Position,char,human,root)
  local origin=safeStanding(root.Position,char,human,root)
  if not destination or not origin then return false,"No safe travel endpoint" end
  local trip={root=root,cancelled=false,wasAnchored=root.Anchored,autoRotate=human.AutoRotate,origin=CFrame.new(origin)*root.CFrame.Rotation}
  active=trip S.sharedTravelActive=true
  local releaseCollision=function()end
  local mode=X.collectMode local tripStarted=os.clock()
  local function valid()
   return not trip.cancelled and not S.nativeMenuRequested and os.clock()-tripStarted<=S.travelValue("travelTimeout")+3 and alive() and S.enabled and G.BlueFarm==S and P.Character==char and root.Parent~=nil and human.Health>0 and not manualControl() and X.collectMode==mode and (not keepGoing or keepGoing())
  end
  local ok,result=pcall(function()
   if mode=="TP" then
    if not S.performTP(CFrame.new(destination)*frame.Rotation,valid,"shared travel") then return false end
   else
    local path
    if not directTween then
     path=pathfinding:CreatePath({AgentRadius=1.5,AgentHeight=5,AgentCanJump=true,WaypointSpacing=12})
     path:ComputeAsync(root.Position,destination)
     if not valid() or path.Status~=Enum.PathStatus.Success then return false end
    end
    local params=RaycastParams.new() params.FilterType=Enum.RaycastFilterType.Exclude params.FilterDescendantsInstances={char} params.RespectCanCollide=true params.CollisionGroup=root.CollisionGroup
    local height=human.RigType==Enum.HumanoidRigType.R6 and 3 or math.max(2.5,human.HipHeight+root.Size.Y/2)
    local points=path and path:GetWaypoints() or {} table.insert(points,{Position=destination-Vector3.new(0,height+0.15,0)})
    root.Anchored=true human.AutoRotate=false
    releaseCollision=S.beginTravelNoclip(char)
    local started=os.clock()
    for _,waypoint in points do
     local hit=workspace:Raycast(waypoint.Position+Vector3.new(0,height+1,0),Vector3.new(0,-height-5,0),params)
     if not hit or hit.Normal.Y<0.5 then return false end
     local point=hit.Position+Vector3.new(0,height+0.15,0)
     repeat
      if not valid() or os.clock()-started>S.travelValue("travelTimeout") then return false end
      local speed=S.travelValue("collectTweenSpeed")
      local tween=game:GetService("TweenService"):Create(root,TweenInfo.new(math.max(0.02,(root.Position-point).Magnitude/speed),Enum.EasingStyle.Linear),{CFrame=CFrame.new(point)*frame.Rotation})
      trip.tween=tween tween:Play()
      repeat task.wait(0.01) until not valid() or tween.PlaybackState~=Enum.PlaybackState.Playing or S.travelValue("collectTweenSpeed")~=speed or os.clock()-started>S.travelValue("travelTimeout")
      tween:Cancel() trip.tween=nil
     until (root.Position-point).Magnitude<=0.4
    end
   end
   releaseCollision()
   root.Anchored=trip.wasAnchored
   local finish=os.clock()+S.travelValue("travelSettle")
   repeat if not valid() then return false end task.wait(0.02) until os.clock()>=finish
   return (root.Position-destination).Magnitude<=3 and safeStanding(root.Position,char,human,root)~=nil
  end)
  if trip.tween then trip.tween:Cancel() end
  releaseCollision()
  if root.Parent and P.Character==char and human.Health>0 then
   if not safeStanding(root.Position,char,human,root) then safeReturn(trip.origin,char,human,root) end
   root.Anchored=trip.wasAnchored root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero human.AutoRotate=trip.autoRotate
  end
  if active==trip then active=nil S.sharedTravelActive=false end
  return ok and result==true,not ok and tostring(result) or nil
 end
end
S.returnTrainingSafe=function(frame,directTween)
 local char=P.Character local root=char and char:FindFirstChild("HumanoidRootPart") local human=char and char:FindFirstChildOfClass("Humanoid")
 if root and human and human.Health>0 then
 if S.travelTo and S.travelTo(frame,function()return alive() and P.Character==char end,directTween) then return true end
 if not safeStanding(root.Position,char,human,root) then return safeReturn(frame,char,human,root) end
 return false
 end
 return false
end
returnFromTP=function(received)
 local trip=tpTrip if not trip then return end
 if trip.returning then return end
 trip.returning=true S.tpReturnActive=true
 if received and trip.spawnGeneration then
  local spawn=S.variantSpawns[trip.key]
  received=spawn~=nil and spawn.generation==trip.spawnGeneration
 end
 if received then S.confirmCollectionReceipt(trip.key) end
 if P.Character~=trip.character or not trip.root.Parent or trip.human.Health<=0 then
 if trip.root.Parent then trip.root.Anchored=trip.wasAnchored end
 tpTrip=nil S.tpReturnActive=false
 return end
 trip.root.Anchored=trip.wasAnchored
 local ground=safeStanding(trip.root.Position,trip.character,trip.human,trip.root,trip.ignore)
 local stay=ground and (received and not X.collectReturnTP or not alive() or not S.enabled or manualControl())
 local restored,returned=false,false
 if stay then restored=true
 elseif not ground then restored=safeReturn(trip.origin,trip.character,trip.human,trip.root) returned=restored
 else
  restored=S.performTP(trip.origin,function()
   return P.Character==trip.character and trip.root.Parent and trip.human.Health>0 and not manualControl() and safeStanding(trip.root.Position,trip.character,trip.human,trip.root,trip.ignore)~=nil
  end,"collection return")
  returned=restored
  if not restored then
   if safeStanding(trip.root.Position,trip.character,trip.human,trip.root,trip.ignore) then restored=true
   else restored=safeReturn(trip.origin,trip.character,trip.human,trip.root) returned=restored end
  end
 end
 if tpTrip==trip then tpTrip=nil end
 S.tpReturnActive=false
