local function confirmObbyHome(char,root,human)
 if P.Character~=char or not root.Parent or human.Health<=0 then return false end
 for attempt=1,3 do
 local home=workspace.Map.PlotModels:FindFirstChild(P.Name)
 local spawn=home and home:FindFirstChild("SpawnPart")
 local point=spawn and spawn:IsA("BasePart") and safeStanding(spawn.Position+Vector3.new(0,3,0),char,human,root)
 if not point then S.obbyStatus="Home not loaded; will retry" return false end
 root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
 local moved=S.travelTo(CFrame.new(point)*spawn.CFrame.Rotation,function()return alive() and P.Character==char end,true)
 if not moved and not safeStanding(root.Position,char,human,root) then safeReturn(CFrame.new(point)*spawn.CFrame.Rotation,char,human,root) end
 local confirmed=waitFor(function()
 return P.Character~=char or human.Health<=0 or ((root.Position-point).Magnitude<=8 and not P:GetAttribute("ObbyMode"))
 end,1.25)
 if P.Character~=char or human.Health<=0 then return false end
 if confirmed and (root.Position-point).Magnitude<=8 and not P:GetAttribute("ObbyMode") then
 lastSafe={character=char,frame=root.CFrame}
 S.obbyHomeReturns=(S.obbyHomeReturns or 0)+1
 S.obbyHomeCheck={confirmed=true,attempts=attempt,distance=(root.Position-point).Magnitude,obbyMode=false}
 S.obbyStatus="Home confirmed • Obby Mode OFF"
 return true
 end
 end
 S.obbyHomeCheck={confirmed=false,obbyMode=P:GetAttribute("ObbyMode")==true}
 S.obbyStatus="Return home not confirmed; will retry"
 return false
end
S.obbyAttempts={}
worker("Auto Obby",0.15,function()
