 if now-tried>=2 and distance<nearest then target=part nearest=distance end
 end
 if part:IsA("BasePart") and part:IsDescendantOf(workspace) then discovered+=1 end
 end
 if not target then
 if not anyClaimable and P:GetAttribute("ObbyMode")==true then
 S.obbyTravel=true stopWalking()
