 S.obbyTravel=false
 if not ok then error(err) end
 else S.obbyStatus=discovered==0 and "Obby bonus platforms not loaded" or anyClaimable and "Waiting for retry cooldown" or "All bonuses on cooldown; waiting at home" end
 return
 end
 S.obbyTravel=true stopWalking()
 S.obbyAttempts[target.Name]=now
 S.obbyStatus="Travelling to "..target.Name.." • "..X.collectMode
 local origin=root.CFrame
 local ok,err=pcall(function()
 if root.Anchored or not safeStanding(origin.Position,char,human,root) then S.obbyStatus="Waiting for solid ground" return end
 local destination=safeStanding(target.Position+Vector3.new(0,4,0),char,human,root)
 if not destination then S.obbyStatus="No safe bonus platform" return end
 local before=OB.GetBonusCooldownTimeLeft(P,target.Name)
