  if OB.CanClaimBonus(P,target.Name) then R.ClaimObbyBonus:FireServer(target) end
  confirmed=waitFor(function()return OB.GetBonusCooldownTimeLeft(P,target.Name)>math.max(0,before) end,0.8)
 end
 S.obbyStatus=target.Name..(confirmed and " • Reward confirmed" or " • Reward unconfirmed")
 if confirmed then S.confirmed.obby=(S.confirmed.obby or 0)+1 end
 end)
 local rewardStatus=S.obbyStatus
