     else R.CollectItemRainItem:FireServer(target.id) end
    end)
   end
  until os.clock()>=finish
  if continuing() and ownedItem(target.name)<=before then routeBlocked[target.key]=os.clock()+S.travelValue("travelRetryDelay") end
 end
 if ownedItem(target.name)>tweenItemBefore then S.confirmCollectionReceipt(target.key) end
 stopWalking()
 if X.collectReturnTween and tweenOrigin and P.Character==character and root.Parent and human.Health>0 and S.travelTo then
