local names={'Overview','Farm','Boosts','Market','Training','Tower','Events','Travel','Setting'}
local titles={'Overview','Farm & collection','Boosts & upgrades','Market & inventory','Training & team','Infinity tower','Seasonal events','Travel & locations','Settings'}
local icons={'◈','F','B','M','T','∞','E','↗','⚙'}
