do local ok,err=xpcall(function() -- input-fix
local u=getgenv().BlueFarm.modernUI
local UIS=game:GetService('UserInputService')
local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
if u.inputConnections then for _,c in ipairs(u.inputConnections) do c:Disconnect() end end
-- Remove the fixed RightShift shortcuts installed by the earlier UI versions.
for _,c in ipairs(getconnections(UIS.InputBegan)) do
 if c.Function then
  local ok,constants=pcall(debug.getconstants,c.Function)
  if ok then for _,v in ipairs(constants) do if v=='RightShift' then c:Disconnect() break end end end
 end
end
local bind=u.pages.Setting:FindFirstChild('BindUIKey',true)
assert(bind,'UI key button missing')
local keyName=bind.Text:match('UI Key:%s*(%w+)') or 'LeftControl'
u.hotkey=Enum.KeyCode[keyName] or Enum.KeyCode.LeftControl
local function visible(v)
 u.shell.Visible=v if u.clipHost then u.clipHost.Visible=v end
end
local function toggle() visible(not u.shell.Visible) end
u.toggleVisibility=toggle
local connections={}
local waiting=false
for _,signal in ipairs({bind.Activated,bind.MouseButton1Click}) do for _,c in ipairs(getconnections(signal)) do c:Disconnect() end end
table.insert(connections,bind.Activated:Connect(function() waiting=true bind.Text='Press a key... (Esc to cancel)' end))
table.insert(connections,UIS.InputBegan:Connect(function(i,processed)
 if waiting and i.UserInputType==Enum.UserInputType.Keyboard then
  waiting=false
  if i.KeyCode~=Enum.KeyCode.Escape and i.KeyCode~=Enum.KeyCode.Unknown then u.hotkey=i.KeyCode end
  bind.Text='UI Key: '..u.hotkey.Name
  getgenv().BlueFarmUIKey=u.hotkey.Name
  return
 end
 if not processed and not UIS:GetFocusedTextBox() and i.KeyCode==u.hotkey then toggle() end
end))
local hide=u.shell.Hero:FindFirstChild('Hide')
if hide then for _,c in ipairs(getconnections(hide.Activated)) do c:Disconnect() end table.insert(connections,hide.Activated:Connect(function() visible(false) end)) end
local icon=gui:FindFirstChild('ModernLauncher')
assert(icon,'Launcher missing')
for _,c in ipairs(getconnections(icon.Activated)) do c:Disconnect() end
local pressing=false local dragged=false local origin,start,touch local lastDrag=0
table.insert(connections,icon.InputBegan:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
  pressing=true dragged=false start=i.Position origin=icon.Position touch=i.UserInputType==Enum.UserInputType.Touch and i or nil
 end
end))
table.insert(connections,UIS.InputChanged:Connect(function(i)
 if pressing and (i.UserInputType==Enum.UserInputType.MouseMovement or i==touch) then
  local d=i.Position-start
  if d.Magnitude>5 then dragged=true end
  if dragged then
   local vp=workspace.CurrentCamera.ViewportSize
   icon.Position=UDim2.fromOffset(math.clamp(origin.X.Offset+d.X,0,vp.X-icon.AbsoluteSize.X),math.clamp(origin.Y.Offset+d.Y,0,vp.Y-icon.AbsoluteSize.Y))
   lastDrag=os.clock()
  end
 end
end))
table.insert(connections,UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i==touch then pressing=false touch=nil end end))
table.insert(connections,icon.Activated:Connect(function() if not dragged and os.clock()-lastDrag>.2 then toggle() end end))
u.inputConnections=connections
u.inputReady=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="input-fix: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- modern-polish
