do local ok,err=xpcall(function() -- unified-theme
local S=getgenv().BlueFarm
local u=S.modernUI
local Tween=game:GetService('TweenService')
local palettes={Cyan=Color3.fromRGB(80,215,231),Blue=Color3.fromRGB(101,158,255),Purple=Color3.fromRGB(183,137,255),Pink=Color3.fromRGB(251,139,191),Green=Color3.fromRGB(106,224,161),Orange=Color3.fromRGB(255,180,105)}
if u.themeConnections then for _,c in ipairs(u.themeConnections) do c:Disconnect() end end
local connections={}
local current=(u.themeName~='Custom' and u.themeName) or 'Cyan'
local roles=setmetatable({},{__mode='k'})
local function mix(a,b,n) return a:Lerp(b,n) end
local function palette()
 local a=palettes[current]
 return {accent=a,light=mix(a,Color3.new(1,1,1),.62),bg=mix(Color3.fromRGB(12,15,21),a,.09),card=mix(Color3.fromRGB(19,23,31),a,.08),button=mix(Color3.fromRGB(26,31,40),a,.13),hover=mix(Color3.fromRGB(32,39,48),a,.24),border=mix(Color3.fromRGB(49,60,73),a,.38),muted=Color3.fromRGB(220,228,240)}
end
local updating=false
local function navColor(b,p)
 local selected=u.pages[b.Name] and u.pages[b.Name].Visible
 b.BackgroundColor3=selected and p.light or p.button
 local icon=b:FindFirstChild('LineIcon') local image=icon and icon:FindFirstChild('HDIcon')
 if image then image.ImageColor3=selected and mix(Color3.fromRGB(10,19,25),p.accent,.12) or p.light end
end
local function renderRole(v,role,p)
 if role=='background' then v.BackgroundColor3=p.bg
 elseif role=='card' then v.BackgroundColor3=p.card
 elseif role=='button' then local selected=v:GetAttribute('ThemeSelected') if selected==true then v.BackgroundColor3=p.light v.TextColor3=Color3.fromRGB(13,23,31) v.BackgroundTransparency=0 v.Font=Enum.Font.GothamBold elseif selected==false then v.BackgroundColor3=v:GetAttribute('ThemeHover') and p.hover or p.button v.TextColor3=p.muted v.BackgroundTransparency=.22 v.Font=Enum.Font.GothamMedium else v.BackgroundColor3=v:GetAttribute('ThemeHover') and p.hover or p.button v.TextColor3=p.light end
 elseif role=='input' then v.BackgroundColor3=mix(p.bg,p.card,.5) v.TextColor3=Color3.fromRGB(241,247,253)
 elseif role=='primary' then local fill=mix(p.accent,Color3.new(1,1,1),.22) v.BackgroundColor3=fill local lum=fill.R*.2126+fill.G*.7152+fill.B*.0722 v.TextColor3=lum>.55 and Color3.fromRGB(15,25,34) or Color3.fromRGB(250,252,255)
 elseif role=='stroke' then v.Color=p.border
 elseif role=='muted' then v.TextColor3=p.muted
 elseif role=='accentText' then v.TextColor3=p.light
 end
end
local function apply(name)
 if typeof(name)=='Color3' then palettes.Custom=name current='Custom' elseif palettes[name] then current=name end
 if updating then return end updating=true
 local p=palette()
 for v,role in pairs(roles) do if v.Parent then renderRole(v,role,p) end end
 for _,b in ipairs(u.shell.Rail:QueryDescendants('TextButton')) do navColor(b,p) end
 u.background.ImageColor3=mix(Color3.new(1,1,1),p.accent,.17)
 local lower=u.shell:FindFirstChild('LowerAtmosphere')
 if lower then local g=lower:FindFirstChildOfClass('UIGradient') if g then g.Color=ColorSequence.new(mix(p.bg,p.accent,.12),p.bg) end end
 local shade=u.shell.Hero:FindFirstChild('TextContrast') if shade then shade.BackgroundColor3=p.bg end
 local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
 local launcher=gui:FindFirstChild('ModernLauncher') if launcher then launcher.BackgroundColor3=p.light end
 local toggle=u.shell.Hero:FindFirstChild('Toggle') if toggle then renderRole(toggle,'primary',p) end
 if u.resizeGrip then u.resizeGrip.TextColor3=p.light end
 u.themeName=current
 updating=false
end
local function register(v,role,property)
 if v:FindFirstAncestor('ColorPicker') then return end
 roles[v]=role
 if property then
  table.insert(connections,v:GetPropertyChangedSignal(property):Connect(function()
   if not updating then updating=true renderRole(v,role,palette()) updating=false end
  end))
 end
end
register(u.shell,'background','BackgroundColor3')
register(u.shell.Rail,'background','BackgroundColor3')
local primary=u.shell.Hero:FindFirstChild('Toggle')
if primary then register(primary,'primary','BackgroundColor3') end
for _,page in pairs(u.pages) do
 for _,v in ipairs(page:QueryDescendants('Frame, TextButton, TextBox, TextLabel, UIStroke')) do
  if v:IsA('UIStroke') then register(v,'stroke','Color')
  elseif v:IsA('TextBox') then register(v,'input','BackgroundColor3')
  elseif v:IsA('TextButton') and v.Name~='AccordionHeader' then
   register(v,'button','BackgroundColor3')
   table.insert(connections,v:GetAttributeChangedSignal('ThemeSelected'):Connect(function() apply() end))
   table.insert(connections,v.MouseEnter:Connect(function() v:SetAttribute('ThemeHover',true) apply() end))
   table.insert(connections,v.MouseLeave:Connect(function() v:SetAttribute('ThemeHover',false) apply() end))
  elseif v:IsA('Frame') and v.BackgroundTransparency<1 and v.Name~='Switch' then register(v,'card','BackgroundColor3')
  elseif v:IsA('TextLabel') and v.Name=='Description' then register(v,'muted','TextColor3')
  end
 end
 table.insert(connections,page:GetPropertyChangedSignal('Visible'):Connect(function() if page.Visible then task.defer(apply) end end))
end
if u.sessionMetrics then register(u.sessionMetrics.fps,'accentText','TextColor3') register(u.sessionMetrics.ping,'accentText','TextColor3') end
for _,b in ipairs(u.pages.Setting:QueryDescendants('TextButton')) do
 local name=b.Text
 if palettes[name] then
  table.insert(connections,b.Activated:Connect(function() task.defer(function() apply(name) end) end))
  table.insert(connections,b.MouseButton1Click:Connect(function() task.defer(function() apply(name) end) end))
 end
end
u.applyTheme=apply
u.themeConnections=connections
apply(current)
-- Older hover effects also write icon colors; keep their final value in the palette.
for _,b in ipairs(u.shell.Rail:GetChildren()) do
 local container=b:FindFirstChild('LineIcon') local image=container and container:FindFirstChild('HDIcon')
 if image then
  local fixing=false
  table.insert(connections,image:GetPropertyChangedSignal('ImageColor3'):Connect(function()
   if fixing then return end fixing=true
   local p=palette() local selected=u.pages[b.Name] and u.pages[b.Name].Visible
   image.ImageColor3=selected and mix(Color3.fromRGB(10,19,25),p.accent,.12) or p.light
   fixing=false
  end))
 end
end
apply(current)

end,debug.traceback) if not ok then getgenv().FyrelithFullError="unified-theme: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- accordion-motion
local u=getgenv().BlueFarm.modernUI
local Tween=game:GetService('TweenService')
local patched=0
for _,page in pairs(u.pages) do
 for _,header in ipairs(page:QueryDescendants('TextButton')) do
  if header.Name=='AccordionHeader' and not header:GetAttribute('SmoothAccordion') then
   local group=header.Parent local content=group:FindFirstChild('Content')
   if content then
    header:SetAttribute('SmoothAccordion',true)
    local expanded=content.Visible
    local glyph
    for _,label in ipairs(header:GetChildren()) do
     if label:IsA('TextLabel') then
      if label.Text:lower():match('%d+%s+controls?') then
       label.Visible=false
       label:GetPropertyChangedSignal('Visible'):Connect(function() if label.Visible then label.Visible=false end end)
      elseif label.Text=='+' or label.Text=='−' or label.Text=='-' then glyph=label end
     end
    end
    for _,signal in ipairs({header.Activated,header.MouseButton1Click}) do
     for _,connection in ipairs(getconnections(signal)) do connection:Disconnect() end
    end
    local wrap=Instance.new('CanvasGroup') wrap.Name='AnimatedContent' wrap.BackgroundTransparency=1 wrap.ClipsDescendants=true wrap.Size=UDim2.new(1,0,0,0) wrap.LayoutOrder=content.LayoutOrder wrap.ZIndex=content.ZIndex wrap.Parent=group
    content.Parent=wrap content.Position=UDim2.fromOffset(0,0) content.Visible=true
    content.AutomaticSize=Enum.AutomaticSize.Y
    if glyph then glyph.Text='›' glyph.TextSize=23 glyph.TextColor3=Color3.fromRGB(199,250,229) glyph.Rotation=expanded and 90 or 0 end
    local heightTween,fadeTween,arrowTween
    local function update(animated)
     local fitHost=u.clipHost or u.shell
     local fitScale=fitHost:FindFirstChildOfClass('UIScale')
     local height=expanded and (math.ceil(content.AbsoluteSize.Y/math.max(fitScale and fitScale.Scale or 1,0.01))+4) or 0
     if heightTween then heightTween:Cancel() end
     if fadeTween then fadeTween:Cancel() end
     if arrowTween then arrowTween:Cancel() end
     if animated and not getgenv().BlueFarm.mobileLite then
      local info=TweenInfo.new(expanded and .32 or .26,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
      heightTween=Tween:Create(wrap,info,{Size=UDim2.new(1,0,0,height)}) heightTween:Play()
      fadeTween=Tween:Create(wrap,TweenInfo.new(.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{GroupTransparency=expanded and 0 or 1}) fadeTween:Play()
      if glyph then arrowTween=Tween:Create(glyph,info,{Rotation=expanded and 90 or 0}) arrowTween:Play() end
     else
      wrap.Size=UDim2.new(1,0,0,height) wrap.GroupTransparency=expanded and 0 or 1
     end
    end
    header.Activated:Connect(function() expanded=not expanded update(true) end)
    content:GetPropertyChangedSignal('AbsoluteSize'):Connect(function() if expanded then update(false) end end)
    task.defer(function() update(false) end)
    patched+=1
   end
  end
 end
end
u.smoothAccordionCount=patched

end,debug.traceback) if not ok then getgenv().FyrelithFullError="accordion-motion: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- wheel-body
local u=getgenv().BlueFarm.modernUI
local UIS=game:GetService('UserInputService')
local content=u.pages.Setting.ResponsiveColumn1.Group_1.AnimatedContent.Content
local old=content:FindFirstChild('ColorPicker')
local order=old and old.LayoutOrder or 4
if old then old:Destroy() end
if u.wheelConnections then for _,c in ipairs(u.wheelConnections) do c:Disconnect() end end
local function new(t,p,a) local v=Instance.new(t) for k,x in pairs(a) do v[k]=x end v.Parent=p return v end
local picker=new('Frame',content,{Name='ColorPicker',Size=UDim2.new(1,-6,0,224),BackgroundTransparency=1,LayoutOrder=order,ZIndex=5})
local wheel=new('ImageButton',picker,{Name='ColorWheel',Size=UDim2.fromOffset(174,174),Position=UDim2.fromOffset(8,8),Image=getgenv().FyrelithBlueLockAssets.Get('fyrelith-color-wheel.png'),BackgroundTransparency=1,AutoButtonColor=false,ZIndex=6})
local cursor=new('Frame',wheel,{Size=UDim2.fromOffset(12,12),AnchorPoint=Vector2.new(.5,.5),BackgroundColor3=Color3.new(1,1,1),ZIndex=8})
new('UICorner',cursor,{CornerRadius=UDim.new(1,0)}) new('UIStroke',cursor,{Color=Color3.fromRGB(15,20,27),Thickness=2})
local bar=new('TextButton',picker,{Name='Brightness',Text='',Position=UDim2.fromOffset(198,8),Size=UDim2.fromOffset(24,174),BackgroundColor3=Color3.new(1,1,1),AutoButtonColor=false,ZIndex=6}) new('UICorner',bar,{CornerRadius=UDim.new(0,8)})
local gradient=new('UIGradient',bar,{Rotation=90,Color=ColorSequence.new(Color3.new(1,1,1),Color3.new(0,0,0))})
local marker=new('Frame',bar,{Size=UDim2.new(1,8,0,4),Position=UDim2.fromOffset(-4,0),BorderSizePixel=0,BackgroundColor3=Color3.new(1,1,1),ZIndex=8}) new('UIStroke',marker,{Color=Color3.fromRGB(20,25,33),Thickness=1})
local hex=new('TextBox',picker,{Name='HexColor',Size=UDim2.fromOffset(150,30),Position=UDim2.fromOffset(8,190),Text='#B789FF',ClearTextOnFocus=false,Font=Enum.Font.GothamMedium,TextSize=13,TextColor3=Color3.new(1,1,1),BackgroundColor3=Color3.fromRGB(28,33,44),ZIndex=6}) new('UICorner',hex,{CornerRadius=UDim.new(0,8)})
local preview=new('Frame',picker,{Name='Preview',Size=UDim2.fromOffset(56,30),Position=UDim2.fromOffset(166,190),ZIndex=6}) new('UICorner',preview,{CornerRadius=UDim.new(0,8)})
local h,s,v=.75,.45,1
local function update()
 local color=Color3.fromHSV(h,s,v)
 cursor.Position=UDim2.fromScale(.5+math.cos(h*math.pi*2)*s*.5,.5+math.sin(h*math.pi*2)*s*.5)
 marker.Position=UDim2.new(0,-4,1-v,-2)
 gradient.Color=ColorSequence.new(Color3.fromHSV(h,s,1),Color3.new(0,0,0))
 preview.BackgroundColor3=color hex.Text='#'..color:ToHex()
 u.applyTheme(color)
end
local dragging=nil local touch
local function move(position)
 if dragging=='wheel' then
  local center=wheel.AbsolutePosition+wheel.AbsoluteSize*.5 local d=Vector2.new(position.X,position.Y)-center
  h=(math.atan2(d.Y,d.X)/(2*math.pi))%1 s=math.clamp(d.Magnitude/(wheel.AbsoluteSize.X*.5),0,1)
 elseif dragging=='brightness' then v=1-math.clamp((position.Y-bar.AbsolutePosition.Y)/bar.AbsoluteSize.Y,0,1) end
 update()
end
local connections={}
for _,entry in ipairs({{wheel,'wheel'},{bar,'brightness'}}) do
 table.insert(connections,entry[1].InputBegan:Connect(function(i)
  if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dragging=entry[2] touch=i.UserInputType==Enum.UserInputType.Touch and i or nil move(i.Position) end
 end))
end
table.insert(connections,UIS.InputChanged:Connect(function(i) if dragging and (i.UserInputType==Enum.UserInputType.MouseMovement or i==touch) then move(i.Position) end end))
table.insert(connections,UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i==touch then dragging=nil touch=nil end end))
table.insert(connections,hex.FocusLost:Connect(function()
 local ok,color=pcall(Color3.fromHex,hex.Text:gsub('#','')) if ok then h,s,v=color:ToHSV() end update()
end))
u.wheelConnections=connections
u.colorWheel={setColor=function(color) h,s,v=color:ToHSV() update() end,wheel=wheel,preview=preview}
update()

end,debug.traceback) if not ok then getgenv().FyrelithFullError="wheel-body: "..tostring(err) error(getgenv().FyrelithFullError) end end

