do local ok,err=xpcall(function() -- selection-state
local S=getgenv().BlueFarm
local u=S.modernUI
local original=S.styleSelection
S.styleSelection=function(target,selected)
 target:SetAttribute('ThemeSelected',selected==true)
 original(target,selected)
end
for _,page in pairs(u.pages) do
 for _,button in ipairs(page:QueryDescendants('TextButton')) do
  local name=button.Parent.Name
  local getter
  if name=='gradeTargets' or name=='traitTargets' then
   getter=function() return S.options[name][button.Name]==true end
  elseif name=='FarmChoices_variants' or name=='FarmChoices_boxes' then
   local key=name=='FarmChoices_variants' and 'variants' or 'boxes'
   getter=function() return S.conveyor[key][button.Name]~=false end
  end
  if getter then
   local function refresh()
    local selected=getter()
    button:SetAttribute('ThemeSelected',selected)
   end
   for _,signal in ipairs({button.Activated,button.MouseButton1Click}) do for _,connection in ipairs(getconnections(signal)) do connection:Disconnect() end end
   button.Activated:Connect(function()
    if name=='gradeTargets' or name=='traitTargets' then S.options[name][button.Name]=not getter() or nil
    else local key=name=='FarmChoices_variants' and 'variants' or 'boxes' S.conveyor[key][button.Name]=not getter() end
    refresh()
   end)
   refresh()
  end
 end
end
local color=Color3.fromRGB(S.options.themeR or 0,S.options.themeG or 0,S.options.themeB or 0)
u.applyTheme(color)
u.selectionStateReady=true
u.selectionVersion='2.1'

end,debug.traceback) if not ok then getgenv().FyrelithFullError="selection-state: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- window-reveal
if getgenv().BlueFarm.mobileLite then return end
local u=getgenv().BlueFarm.modernUI
local Tween=game:GetService('TweenService')
local host=u.clipHost or u.shell
local fitScale=host:FindFirstChildOfClass('UIScale')
if u.windowRevealConnection then u.windowRevealConnection:Disconnect() end
local fade,motion
local baseline=fitScale and fitScale.Scale or 1
local inMotion=false
local function cancel()
 if fade then fade:Cancel() fade=nil end
 if motion then motion:Cancel() motion=nil end
 if inMotion and fitScale then fitScale.Scale=baseline end
 inMotion=false
end
local function reveal()
 cancel()
 if not u.shell.Visible then host.GroupTransparency=0 return end
 baseline=fitScale and fitScale.Scale or 1
 host.GroupTransparency=1
 if fitScale then fitScale.Scale=baseline*.975 end
 inMotion=true
 local info=TweenInfo.new(.24,Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
 fade=Tween:Create(host,info,{GroupTransparency=0}) fade:Play()
 if fitScale then motion=Tween:Create(fitScale,info,{Scale=baseline}) motion:Play() end
 local current=fade
 fade.Completed:Connect(function() if fade==current then inMotion=false end end)
end
-- Remove the earlier fade listener so both effects cannot compete.
if u.motionConnections then
 for _,c in ipairs(u.motionConnections) do
  -- Only the last connection belongs to the former window reveal.
 end
 local previous=u.motionConnections[#u.motionConnections]
 if previous then previous:Disconnect() end
end
u.windowRevealConnection=u.shell:GetPropertyChangedSignal('Visible'):Connect(reveal)
local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
gui.Destroying:Connect(function() cancel() if u.windowRevealConnection then u.windowRevealConnection:Disconnect() end end)
u.windowRevealReady=true
if u.shell.Visible then reveal() end

end,debug.traceback) if not ok then getgenv().FyrelithFullError="window-reveal: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- window-close
local u=getgenv().BlueFarm.modernUI
local Tween=game:GetService('TweenService')
local UIS=game:GetService('UserInputService')
local host=u.clipHost
local scale=host:FindFirstChildOfClass('UIScale')
local closing=false
local token=0
local fade,motion
local savedScale
local function cancel()
 token+=1
 if fade then fade:Cancel() end if motion then motion:Cancel() end
 if closing and savedScale then scale.Scale=savedScale end
 closing=false
end
local function hide()
 if closing or not u.shell.Visible then return end
 cancel() closing=true local thisToken=token savedScale=scale.Scale
 local info=TweenInfo.new(.18,Enum.EasingStyle.Quad,Enum.EasingDirection.In)
 fade=Tween:Create(host,info,{GroupTransparency=1})
 motion=Tween:Create(scale,info,{Scale=savedScale*.975})
 fade:Play() motion:Play()
 fade.Completed:Connect(function(state)
  if thisToken~=token or state~=Enum.PlaybackState.Completed then return end
  u.shell.Visible=false host.Visible=false scale.Scale=savedScale host.GroupTransparency=0 closing=false
 end)
end
local function toggle()
 if closing then cancel() host.GroupTransparency=0 u.shell.Visible=false u.shell.Visible=true host.Visible=true
 elseif u.shell.Visible then hide()
 else u.shell.Visible=true host.Visible=true end
end
u.toggleVisibility=toggle
local button=u.shell.Hero.Hide
for _,c in ipairs(getconnections(button.Activated)) do c:Disconnect() end
button.Activated:Connect(hide)
-- Wrap the already-authorized hotkey and launcher handlers at their shared toggle.
-- Their original closures keep the old local toggle, so replace those routes explicitly.
local launcher=game.Players.LocalPlayer.PlayerGui.BlueFarmControls.ModernLauncher
for _,c in ipairs(getconnections(launcher.Activated)) do c:Disconnect() end
local moved=false local start local pressed=false local lastDrag=0
launcher.InputBegan:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then start=i.Position moved=false pressed=true end
end)
UIS.InputChanged:Connect(function(i)
 if pressed and start and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch) then
  if (i.Position-start).Magnitude>5 then moved=true lastDrag=os.clock() end
 end
end)
UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then pressed=false end end)
launcher.Activated:Connect(function() if not moved and os.clock()-lastDrag>.2 then toggle() end end)
-- Replace just the modern key handler while retaining key-binding behavior.
local bind=u.pages.Setting:FindFirstChild('BindUIKey',true)
local waiting=false
for _,c in ipairs(getconnections(bind.Activated)) do c:Disconnect() end
bind.Activated:Connect(function() waiting=true bind.Text='Press a key... (Esc to cancel)' end)
if u.inputConnections and u.inputConnections[2] then u.inputConnections[2]:Disconnect() end
if u.closeKeyConnection then u.closeKeyConnection:Disconnect() end
u.closeKeyConnection=UIS.InputBegan:Connect(function(i,processed)
 if waiting and i.UserInputType==Enum.UserInputType.Keyboard then
  waiting=false if i.KeyCode~=Enum.KeyCode.Escape and i.KeyCode~=Enum.KeyCode.Unknown then u.hotkey=i.KeyCode end
  bind.Text='UI Key: '..u.hotkey.Name getgenv().BlueFarm.options.uiKey=u.hotkey.Name return
 end
 if not processed and not UIS:GetFocusedTextBox() and i.KeyCode==u.hotkey then toggle() end
end)
u.closeAnimationReady=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="window-close: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- mobile-input
local u=getgenv().BlueFarm.modernUI
local UIS=game:GetService('UserInputService')
local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
if u.mobileConnections then for _,c in ipairs(u.mobileConnections) do c:Disconnect() end end
local connections={}
local function connect(signal,fn) local c=signal:Connect(fn) table.insert(connections,c) end
-- Native ScrollingFrames need active input to consume touch pans.
local function enableScroll(frame)
 if not frame:IsA('ScrollingFrame') then return end
 frame.Active=true frame.ScrollingEnabled=true frame.ElasticBehavior=Enum.ElasticBehavior.WhenScrollable
 frame.ScrollBarThickness=UIS.TouchEnabled and 6 or 4
 if u.pages[frame.Name]==frame then frame.ScrollingDirection=Enum.ScrollingDirection.Y end
end
for _,frame in ipairs(gui:QueryDescendants('ScrollingFrame')) do enableScroll(frame) end
connect(gui.DescendantAdded,enableScroll)
-- Separate window dragging from pans inside content, and track the exact finger.
if u.smoothDragConnections then for _,c in ipairs(u.smoothDragConnections) do c:Disconnect() end end
for _,c in ipairs(getconnections(u.shell.Hero.InputBegan)) do c:Disconnect() end
local host=u.clipHost or u.shell
local header=u.shell.Hero
header.Active=true
local finger,origin,start,mouse
local function finish(input)
 if input==finger or (mouse and input.UserInputType==Enum.UserInputType.MouseButton1) then finger=nil mouse=false end
end
local function move(input)
 if not finger then return end
 if input~=finger and not(mouse and input.UserInputType==Enum.UserInputType.MouseMovement) then return end
 local d=input.Position-start
 local bounds=u.mobileSafeBounds
 local view=bounds and bounds.AbsoluteSize or workspace.CurrentCamera.ViewportSize
 local anchor=host.AnchorPoint local size=host.AbsoluteSize
 local x=origin.X.Scale*view.X+origin.X.Offset+d.X
 local y=origin.Y.Scale*view.Y+origin.Y.Offset+d.Y
 -- Keep the entire outer window in the same inset-aware coordinate space.
 local margin=6
 local minX=margin+size.X*anchor.X local maxX=math.max(minX,view.X-margin-size.X*(1-anchor.X))
 local minY=margin+size.Y*anchor.Y local maxY=math.max(minY,view.Y-margin-size.Y*(1-anchor.Y))
 x=math.clamp(x,minX,maxX) y=math.clamp(y,minY,maxY)
 host.Position=UDim2.fromOffset(x,y)
end
connect(header.InputBegan,function(input)
 if finger then return end
 if input.UserInputType==Enum.UserInputType.Touch or input.UserInputType==Enum.UserInputType.MouseButton1 then
  finger=input mouse=input.UserInputType==Enum.UserInputType.MouseButton1 origin=host.Position start=input.Position
 end
end)
connect(UIS.InputChanged,move)
connect(UIS.TouchMoved,move)
connect(UIS.InputEnded,finish)
connect(UIS.TouchEnded,finish)
connect(gui.Destroying,function() for _,c in ipairs(connections) do c:Disconnect() end end)
u.mobileConnections=connections
u.mobileInputReady=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="mobile-input: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- performance-screen
local S=getgenv().BlueFarm local u=S.modernUI
local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
