local function label(p,text,y,size,height)
 return new('TextLabel',p,{BackgroundTransparency=1,Text=text,TextSize=size,TextColor3=Color3.fromRGB(235,243,250),Font=Enum.Font.GothamMedium,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,TextWrapped=true,Position=UDim2.fromOffset(16,y),Size=UDim2.new(1,-32,0,height),ZIndex=302})
end
