label(card,'Performance',14,15,24)
local function button(text,y,callback)
 local b=new('TextButton',card,{Text=text,Font=Enum.Font.GothamBold,TextSize=12,TextColor3=Color3.fromRGB(235,243,250),BackgroundColor3=Color3.fromRGB(37,44,55),Position=UDim2.fromOffset(14,y),Size=UDim2.new(1,-28,0,40),ZIndex=5}) round(b,10) b.Activated:Connect(callback) return b
end
local enabled=false local saved=setmetatable({},{__mode='k'}) local lightSaved
local function remember(object,property,value)
 local props=saved[object] if not props then props={} saved[object]=props end
 if props[property]==nil then local ok,before=pcall(function() return object[property] end) if ok then props[property]=before end end
 pcall(function() object[property]=value end)
end
local function simplify(object)
 if object:IsA('ParticleEmitter') or object:IsA('Trail') or object:IsA('Beam') or object:IsA('Smoke') or object:IsA('Fire') or object:IsA('Sparkles') or object:IsA('Light') or object:IsA('PostEffect') or object:IsA('Clouds') then remember(object,'Enabled',false)
 elseif object:IsA('BasePart') then remember(object,'CastShadow',false) remember(object,'Reflectance',0) end
end
local function extras(on)
 enabled=on
 if on then
  remember(Lighting,'GlobalShadows',false) remember(Lighting,'EnvironmentDiffuseScale',0) remember(Lighting,'EnvironmentSpecularScale',0)
  task.spawn(function()
   for _,root in ipairs({workspace,Lighting}) do
    local items=root:QueryDescendants('BasePart, ParticleEmitter, Trail, Beam, Smoke, Fire, Sparkles, Light, PostEffect, Clouds')
    for i,object in ipairs(items) do if not enabled then return end simplify(object) if i%120==0 then task.wait() end end
   end
  end)
 else
  for object,props in pairs(saved) do for property,value in pairs(props) do pcall(function() object[property]=value end) end saved[object]=nil end
 end
end
local added=workspace.DescendantAdded:Connect(function(v) if enabled then task.defer(function() if enabled then simplify(v) end end) end end)
local effectAdded=Lighting.DescendantAdded:Connect(function(v) if enabled then simplify(v) end end)
local boost
boost=button('Boost FPS: OFF',48,function() S.options.boostFPS=not S.options.boostFPS extras(S.options.boostFPS) boost.Text=S.options.boostFPS and 'Boost FPS: ON' or 'Boost FPS: OFF' end)
-- Existing switch controls the same option, including the original reversible texture simplifier.
local started=os.clock() local gained={} local previous={} local initialized=false
local dataModule=require(game.ReplicatedStorage.Client.Data.ClientDataManager)
local function snapshot()
 local data=dataModule.GetData() local out={}
 local function walk(node,path,depth)
  if depth>5 or type(node)~='table' then return end
  if type(node.Amount)=='number' then out[path]=node.Amount return end
  for key,value in pairs(node) do
   if type(value)=='table' then walk(value,path=='' and tostring(key) or path..' / '..tostring(key),depth+1) end
  end
 end
 for category,items in pairs(data.Inventory or {}) do if category~='FavoritedBallSkins' then walk(items,category,0) end end
 for _,unit in pairs(data.PlayerUnits or {}) do if type(unit)=='table' and unit.PlayerUnitName then local key='Striker / '..unit.PlayerUnitName..' / '..tostring(unit.Variant or 'Normal') out[key]=(out[key] or 0)+1 end end
 return out
end
local ok,baseline=pcall(snapshot) if ok then previous=baseline initialized=true end
local overlay=new('ScreenGui',game.Players.LocalPlayer.PlayerGui,{Name='FyrelithBlackScreen',ResetOnSpawn=false,IgnoreGuiInset=true,DisplayOrder=500,Enabled=false})
local black=new('Frame',overlay,{Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(0,0,0),BorderSizePixel=0})
local panel=new('Frame',black,{Size=UDim2.new(.9,0,.86,0),Position=UDim2.fromScale(.5,.5),AnchorPoint=Vector2.new(.5,.5),BackgroundTransparency=1})
label(panel,'FYRELITH  /  BLACK SCREEN',0,20,32)
local status=label(panel,'',48,13,110)
label(panel,'ITEMS GAINED SINCE START',164,13,25)
local list=new('ScrollingFrame',panel,{Position=UDim2.fromOffset(16,197),Size=UDim2.new(1,-32,1,-257),BackgroundTransparency=1,BorderSizePixel=0,Active=true,ScrollingEnabled=true,AutomaticCanvasSize=Enum.AutomaticSize.Y,CanvasSize=UDim2.new(),ScrollBarThickness=4})
local items=new('TextLabel',list,{Size=UDim2.new(1,-8,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,TextColor3=Color3.fromRGB(202,222,215),TextSize=13,Font=Enum.Font.Gotham,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,TextWrapped=true,Text='No new items observed yet.'})
local screenEnabled=false local screenButton
local function screen(on)
 screenEnabled=on overlay.Enabled=on
 local success,err=pcall(function() Run:Set3dRenderingEnabled(not on) end)
 if not success then S.blackScreenRenderError=tostring(err) else S.blackScreenRenderError=nil end
 if screenButton then screenButton.Text=on and 'Black Screen: ON' or 'Black Screen: OFF' end
end
screenButton=button('Black Screen: OFF',96,function() screen(not screenEnabled) end)
label(card,'Hide the 3D scene; keep automation and live item tracking.',150,11,42)
local exit=new('TextButton',panel,{Text='Back to game / ปิด Black Screen',Font=Enum.Font.GothamBold,TextSize=13,TextColor3=Color3.fromRGB(235,243,250),BackgroundColor3=Color3.fromRGB(32,39,48),Position=UDim2.new(0,16,1,-46),Size=UDim2.new(1,-32,0,42)}) round(exit,10) exit.Activated:Connect(function() screen(false) end)
u.setBlackScreen=screen
u.performance={card=card,overlay=overlay,gained=gained,started=started}
task.spawn(function()
 while S.running and gui.Parent do
  if enabled~=S.options.boostFPS then extras(S.options.boostFPS) end
  boost.Text=S.options.boostFPS and 'Boost FPS: ON' or 'Boost FPS: OFF'
  local good,now=false,nil
  if not S.mobileLite or screenEnabled then good,now=pcall(snapshot) end
  if good then
   if initialized then for key,amount in pairs(now) do local delta=amount-(previous[key] or 0) if delta>0 then gained[key]=(gained[key] or 0)+delta end end end
   previous=now initialized=true
  end
  if screenEnabled then
   local elapsed=math.floor(os.clock()-started)
   status.Text=string.format('%s  •  %dm %02ds\nOpened %d  |  Bought %d  |  Sold %d  |  Errors %d\n%s\n%s',S.enabled and 'RUNNING' or 'PAUSED',elapsed//60,elapsed%60,S.opened or 0,S.bought or 0,S.sold or 0,S.errors or 0,tostring(S.buyStatus or ''),tostring(S.obbyStatus or ''))
   local rows={} for key,amount in pairs(gained) do table.insert(rows,'+'..amount..'   '..key) end table.sort(rows) items.Text=#rows>0 and table.concat(rows,'\n') or 'No new items observed yet.'
  end
  task.wait(1)
 end
end)
gui.Destroying:Connect(function() screen(false) extras(false) added:Disconnect() effectAdded:Disconnect() overlay:Destroy() end)
local reset=S.resetConfig S.resetConfig=function() screen(false) extras(false) return reset() end
u.reflow()

end,debug.traceback) if not ok then getgenv().FyrelithFullError="performance-screen: "..tostring(err) error(getgenv().FyrelithFullError) end end

