do local ok,err=xpcall(function() -- filter-window-motion
if getgenv().BlueFarm.mobileLite then return end
local S=getgenv().BlueFarm local u=S.modernUI
local Tween=game:GetService('TweenService')
local popup=u.shell.EventSelector local dialog=popup.Dialog
if u.filterWindowConnections then for _,c in ipairs(u.filterWindowConnections) do c:Disconnect() end end
local group=popup:FindFirstChild('DialogMotion')
if not group then
 group=Instance.new('CanvasGroup') group.Name='DialogMotion' group.BackgroundTransparency=1 group.Size=UDim2.fromScale(1,1) group.ZIndex=101 group.Parent=popup
 dialog.Parent=group
end
local base=dialog.Position local generation=0 local fade,slide local closing=false
local function cancel()
 generation+=1 if fade then fade:Cancel() end if slide then slide:Cancel() end
end
local function openMotion()
 cancel() closing=false group.GroupTransparency=1
 dialog.Position=base+UDim2.fromOffset(0,12)
 local info=TweenInfo.new(.24,Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
 fade=Tween:Create(group,info,{GroupTransparency=0}) slide=Tween:Create(dialog,info,{Position=base}) fade:Play() slide:Play()
end
local function closeMotion()
 if closing or not popup.Visible then return end
 cancel() closing=true local token=generation
 local info=TweenInfo.new(.17,Enum.EasingStyle.Quad,Enum.EasingDirection.In)
 fade=Tween:Create(group,info,{GroupTransparency=1}) slide=Tween:Create(dialog,info,{Position=base+UDim2.fromOffset(0,8)})
 fade.Completed:Connect(function(state)
  if token==generation and state==Enum.PlaybackState.Completed then popup.Visible=false dialog.Search:ReleaseFocus() dialog.Position=base group.GroupTransparency=0 closing=false end
 end)
 fade:Play() slide:Play()
end
local connections={}
table.insert(connections,popup:GetPropertyChangedSignal('Visible'):Connect(function() if popup.Visible then openMotion() else cancel() closing=false end end))
for _,c in ipairs(getconnections(popup.Activated)) do c:Disconnect() end
for _,c in ipairs(getconnections(popup.MouseButton1Click)) do c:Disconnect() end
for _,button in ipairs({dialog.Close,dialog.Done}) do
 for _,c in ipairs(getconnections(button.Activated)) do c:Disconnect() end
 table.insert(connections,button.Activated:Connect(closeMotion))
end
-- Keep references usable by modules that locate the original dialog by name.
u.filterDialog=dialog u.filterWindowConnections=connections
u.filterOpenAnimation=true u.closeFilter=closeMotion
if popup.Visible then openMotion() end

end,debug.traceback) if not ok then getgenv().FyrelithFullError="filter-window-motion: "..tostring(err) error(getgenv().FyrelithFullError) end end
-- Fyrelith: bridge legacy native-menu actions to the current Modern UI.
do
 local S=getgenv().BlueFarm
 local u=S and S.modernUI
 if u and u.shell and type(S.requestGameMenu)=='function' then
  local player=game:GetService('Players').LocalPlayer
  local gui=player.PlayerGui:FindFirstChild('BlueFarmControls')
  local shell=u.shell
  local host=u.clipHost or shell
  local active=nil
  local disposed=false
  local connections={}
  local targets={
   {'BallSkinGui','MainFrame'}, {'SelectGui','MainFrame'},
   {'InfinityTowerGui','FloorSelectionMainFrame'},
   {'InfinityTowerGui','UnitsSelectionMainFrame'},
   {'InfinityTowerGui','BattleMainFrame'}, {'HalloweenShopGui','MainFrame'},
  }
  local function nativeVisible()
   for _,entry in ipairs(targets) do
    local native=player.PlayerGui:FindFirstChild(entry[1])
    local frame=native and native:FindFirstChild(entry[2])
    if frame and frame:IsA('GuiObject') and frame.Visible then
     local visible=not native:IsA('ScreenGui') or native.Enabled
     local ancestor=frame.Parent
     while visible and ancestor and ancestor~=native do
      if ancestor:IsA('GuiObject') and not ancestor.Visible then visible=false end
      ancestor=ancestor.Parent
     end
     if visible then return true end
    end
   end
   return false
  end
  local function hide()
   if shell.Parent and shell.Visible then shell.Visible=false end
   if host.Parent and host.Visible then host.Visible=false end
  end
  local function finish(session)
   if active~=session then return end
   active=nil
   if disposed or not shell.Parent or not host.Parent then return end
   -- Keep the same UI instances: selected tab, scroll offsets and position survive.
   shell.Visible=session.shellVisible
   host.Visible=session.hostVisible
  end
  local function begin()
   if active then return active end
   local session={shellVisible=shell.Visible,hostVisible=host.Visible,
    started=os.clock(),seen=false,quiet=nil,callbackDone=false}
   active=session
   hide()
   task.spawn(function()
    while active==session and not disposed and shell.Parent and host.Parent do
     local now=os.clock()
     local busy=S.nativeMenuRequested or S.shopOpen or S.selectingTraining or nativeVisible()
     if busy then session.seen=true session.quiet=nil
     elseif session.callbackDone then
      session.quiet=session.quiet or now
      if session.seen and now-session.quiet>=0.4
       or not session.seen and now-session.started>=5 then break end
     end
     hide()
     task.wait(0.05)
    end
    finish(session)
   end)
   return session
  end
  local original=S.requestGameMenu
  local bridge
  bridge=function(button,callback)
   if disposed then return original(button,callback) end
   -- Preserve the original guards; only accepted callbacks hide the dashboard.
   return original(button,function(...)
    local session=begin()
    local args=table.pack(...)
    local result=table.pack(pcall(function()
     return callback(table.unpack(args,1,args.n))
    end))
    session.callbackDone=true
    if not result[1] then
     finish(session)
     error(result[2],0)
    end
    return table.unpack(result,2,result.n)
   end)
  end
  S.requestGameMenu=bridge
  -- Legacy restore callbacks must not reveal the modern window mid-selection.
  table.insert(connections,shell:GetPropertyChangedSignal('Visible'):Connect(function()
   if active and shell.Visible then hide() end
  end))
  if host~=shell then
   table.insert(connections,host:GetPropertyChangedSignal('Visible'):Connect(function()
    if active and host.Visible then hide() end
   end))
  end
  if gui then
   table.insert(connections,gui.Destroying:Connect(function()
    disposed=true active=nil
    if S.requestGameMenu==bridge then S.requestGameMenu=original end
    for _,connection in ipairs(connections) do connection:Disconnect() end
   end))
  end
  u.nativeMenuBridgeVersion='1.0'
 end
end
-- Balanced startup size; always start centered, independent of saved legacy position.
do
 local S=getgenv().BlueFarm
 local u=S and S.modernUI
 if u and u.clipHost then
  local host=u.clipHost
  local view=workspace.CurrentCamera.ViewportSize
  host.AnchorPoint=Vector2.new(0.5,0.5)
  host.Position=UDim2.fromScale(0.5,0.5)
  host.Size=UDim2.fromOffset(view.X<760 and 680 or 1060,700)
  if u.reflow then u.reflow() end
  local scale=host:FindFirstChildOfClass('UIScale')
  if scale then
   scale.Scale=math.max(0.01,math.min(1,view.X*0.86/host.Size.X.Offset,view.Y*0.78/host.Size.Y.Offset))
  end
  u.startupLayoutVersion='reference-clean-2'
 end
end
-- Re-measure expanded cards after startup scaling and deferred layout have settled.
do
 local S=getgenv().BlueFarm
 local u=S and S.modernUI
 if u and u.clipHost then
  local scale=u.clipHost:FindFirstChildOfClass('UIScale')
  for _,page in pairs(u.pages) do
   page.Active=true
   page.ScrollingEnabled=true
   page.AutomaticCanvasSize=Enum.AutomaticSize.Y
   page.ScrollingDirection=Enum.ScrollingDirection.Y
   page.CanvasSize=UDim2.new()
   page.ScrollBarThickness=6
   for _,header in ipairs(page:QueryDescendants('#AccordionHeader')) do
    local card=header.Parent
    local wrap=card:FindFirstChild('AnimatedContent')
    local content=wrap and wrap:FindFirstChild('Content')
    if content then
     local function measure()
      if not wrap.Parent or wrap.Size.Y.Offset<=0 then return end
      local height=math.ceil(content.AbsoluteSize.Y/math.max(scale.Scale,.01))+4
      if math.abs(wrap.Size.Y.Offset-height)>1 then wrap.Size=UDim2.new(1,0,0,height) end
     end
     content:GetPropertyChangedSignal('AbsoluteSize'):Connect(function() task.defer(measure) end)
     local layout=content:FindFirstChildOfClass('UIListLayout')
     if layout then layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function() task.defer(measure) end) end
     scale:GetPropertyChangedSignal('Scale'):Connect(function() task.defer(measure) end)
     task.defer(measure)
    end
   end
  end
  u.cardLayoutVersion='content-height-1'
 end
end
-- Keep mobile rendering lightweight without changing the controls or farm options.
do
 local S=getgenv().BlueFarm
 if S and S.mobileLite and S.modernUI then
  local shell=S.modernUI.shell
  for _,v in shell:QueryDescendants("UIGradient, GuiObject") do
   if v:IsA("UIGradient") then
    local parent=v.Parent
    -- Surface shading and the brightness control must remain functional in lite mode.
    local required=parent and (parent.Name=="LowerAtmosphere" or parent.Name=="Brightness" or parent.Name=="TextContrast" or parent.Name=="SharedArtwork")
    v.Enabled=required==true
   elseif v.Name:lower():find("shadow",1,true) or v.Name:lower():find("glow",1,true) then v.Visible=false end
  end
  S.mobileOptimizationsApplied=true
 end
end

-- Match the lower surface to the active theme, including when gradients are disabled.
do
 local S=getgenv().BlueFarm
 local u=S and S.modernUI
 if u and u.shell then
  local lower=u.shell:FindFirstChild("LowerAtmosphere")
  if lower then
   local function syncSurface() lower.BackgroundColor3=u.shell.BackgroundColor3 end
   syncSurface()
   if u.mobileSurfaceConnection then u.mobileSurfaceConnection:Disconnect() end
   u.mobileSurfaceConnection=u.shell:GetPropertyChangedSignal("BackgroundColor3"):Connect(syncSurface)
  end
  u.mobileSurfaceFix="surface-1"
 end
end

-- Mobile controls: remove the color picker, fit complete logos and expose resize grip.
do local ok,err=xpcall(function()
 local S=getgenv().BlueFarm local u=S and S.modernUI
 if not u then return end
 local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
 if u.wheelConnections then for _,c in u.wheelConnections do c:Disconnect() end u.wheelConnections=nil end
 for _,picker in u.shell:QueryDescendants('#ColorPicker') do picker:Destroy() end
 for _,label in u.shell:QueryDescendants('TextLabel') do
  if label.Text:find('UI Color',1,true) or label.Text:find('Drag to choose color',1,true) then label:Destroy() end
 end
 -- Retain reset/config compatibility after the visual picker is removed.
 u.colorWheel={setColor=function(color) if typeof(color)=='Color3' then u.applyTheme(color) end end}
 local function fitLogo(image)
  if not image then return end
  image.AnchorPoint=Vector2.new(.5,.5) image.Position=UDim2.fromScale(.5,.5)
  image.Size=UDim2.new(1,-8,1,-8) image.ScaleType=Enum.ScaleType.Fit
  image.ImageRectOffset=Vector2.zero image.ImageRectSize=Vector2.zero
 end
 local brand=u.shell.Rail:FindFirstChild('BrandLogo')
 if brand then
  if S.mobileLite and not S.referenceLayout then brand.AnchorPoint=Vector2.zero brand.Position=UDim2.fromOffset(7,4) brand.Size=UDim2.fromOffset(46,42) end
  fitLogo(brand:FindFirstChild('LogoImage'))
 end
 local launcher=gui:FindFirstChild('ModernLauncher')
 if launcher then fitLogo(launcher:FindFirstChild('LogoImage')) end
 local grip=u.resizeGrip
 if grip then
  grip.Visible=true grip.Active=true grip.Text='' grip.AutoButtonColor=false grip.Font=Enum.Font.GothamBold grip.TextSize=24
  grip.TextTransparency=0 grip.TextColor3=Color3.fromRGB(225,240,250)
  grip.BackgroundColor3=Color3.fromRGB(35,45,60) grip.BackgroundTransparency=1
  grip.Size=UDim2.fromOffset(36,36) grip.Position=UDim2.new(1,-42,1,-42) grip.ZIndex=100
  for _,v in grip:QueryDescendants('ImageLabel, ImageButton, UIStroke') do if v:IsA('UIStroke') then v.Enabled=false else v.Visible=false end end
  local corner=grip:FindFirstChildOfClass('UICorner') or Instance.new('UICorner',grip)
  corner.CornerRadius=UDim.new(0,8)
 end
 local reset=gui:FindFirstChild('ResetWindowSize',true)
 if reset then
  reset.Activated:Connect(function() u.mobileUserSize=nil if u.reflow then u.reflow() end end)
 end
 if u.reflow then u.reflow() end
 u.mobileControlsVersion='invisible-resize-2'
end,debug.traceback)
 if not ok then getgenv().FyrelithFullError='Mobile controls: '..tostring(err) warn(getgenv().FyrelithFullError) end
end

-- Respect the script language selector; do not apply Roblox automatic UI translation.
do
 local S=getgenv().BlueFarm
 local gui=game.Players.LocalPlayer.PlayerGui:FindFirstChild("BlueFarmControls")
 if S and gui then
  pcall(function() gui.AutoLocalize=false end)
  for _,v in gui:QueryDescendants("GuiObject") do v.AutoLocalize=false end
  local connection=gui.DescendantAdded:Connect(function(v)
   if v:IsA("GuiObject") then v.AutoLocalize=false end
  end)
  gui.Destroying:Connect(function() connection:Disconnect() end)
  S.manualUILanguage=true
 end
end
-- Reference composition: fit the entire two-column window once at startup.
do
 local S=getgenv().BlueFarm local u=S and S.modernUI
 if u then
  local host=u.clipHost
  host.Size=UDim2.fromOffset(1060,700)
  host.AnchorPoint=Vector2.new(.5,.5)
  host.Position=UDim2.fromScale(.5,.5)
  u.reflow()
  task.defer(function()
   game:GetService('RunService').Heartbeat:Wait()
   if S.running and host.Parent then
    u.reflow()
    host.AnchorPoint=Vector2.new(.5,.5)
    host.Position=UDim2.fromScale(.5,.5)
   end
  end)
 end
end
do
 local S=getgenv().BlueFarm local u=S and S.modernUI
 if not u then return end
 local host=u.clipHost local scale=host:FindFirstChildOfClass('UIScale')
 local bg=u.background
 local assets=getgenv().FyrelithBlueLockAssets
 local file=assets.Root..'/fyrelith-background.png'
 local ok,data=pcall(readfile,file)
 if ok and #data>=24 and data:sub(1,8)=='\137PNG\13\10\26\10' then
  local function integer(index)
   local a,b,c,d=string.byte(data,index,index+3)
   return ((a*256+b)*256+c)*256+d
  end
  local width,height=integer(17),integer(21)
  bg.ImageRectOffset=Vector2.new(0,math.floor(height*95/490+.5))
  bg.ImageRectSize=Vector2.new(width,math.floor(height*303/490+.5))
 end
 -- Disconnect the old handler that changes the logical canvas and forces it back.
 if u.resizeConnections then for _,c in u.resizeConnections do c:Disconnect() end end
 local grip=u.resizeGrip local input=game:GetService('UserInputService')
 local connections={} local finger,origin,startScale
 grip.Visible=true grip.Active=true grip.Text='◢' grip.TextTransparency=.2
 grip.Size=UDim2.fromOffset(42,42) grip.Position=UDim2.new(1,-44,1,-44)
 grip.ZIndex=100
 local function area()
  local b=u.mobileSafeBounds
  return b and b.AbsoluteSize or workspace.CurrentCamera.ViewportSize
 end
 local function apply(value)
  local bounds=area() local p=host.Position
  local x=p.X.Scale*bounds.X+p.X.Offset
  local y=p.Y.Scale*bounds.Y+p.Y.Offset
  local upper=math.min((bounds.X-6-x)/1060,(bounds.Y-6-y)/700)
  upper=math.max(.01,upper)
  local nextScale=math.clamp(value,math.min(.2,upper),upper)
  u.manualScale=nextScale scale.Scale=nextScale
 end
 u.setWindowScale=apply
 local oldReflow=u.reflow
 u.reflow=function(...)
  local result=oldReflow(...)
  if u.manualScale then scale.Scale=u.manualScale end
  return result
 end
 S.reflowResponsive=u.reflow
 table.insert(connections,grip.InputBegan:Connect(function(i)
  if finger or (i.UserInputType~=Enum.UserInputType.MouseButton1 and i.UserInputType~=Enum.UserInputType.Touch) then return end
  local bounds=u.mobileSafeBounds
  local p=host.AbsolutePosition-(bounds and bounds.AbsolutePosition or Vector2.zero)
  host.AnchorPoint=Vector2.zero host.Position=UDim2.fromOffset(p.X,p.Y)
  finger=i origin=i.Position startScale=scale.Scale
 end))
 table.insert(connections,input.InputChanged:Connect(function(i)
  if not finger then return end
  if i~=finger and not(finger.UserInputType==Enum.UserInputType.MouseButton1 and i.UserInputType==Enum.UserInputType.MouseMovement) then return end
  local d=i.Position-origin
  apply(startScale+(d.X*1060+d.Y*700)/(1060*1060+700*700))
 end))
 table.insert(connections,input.InputEnded:Connect(function(i)
  if i==finger or (finger and finger.UserInputType==Enum.UserInputType.MouseButton1 and i.UserInputType==Enum.UserInputType.MouseButton1) then finger=nil end
 end))
 local gui=host:FindFirstAncestorOfClass('ScreenGui')
 gui.Destroying:Connect(function() for _,c in connections do c:Disconnect() end end)
 u.resizeConnections=connections u.artworkResizeVersion='cache-aware-3'
end

-- Show the complete artwork region without a second crop or a hard lower cover.
do
 local S=getgenv().BlueFarm local u=S and S.modernUI
 if u and u.background then
  local bg=u.background
  bg.ScaleType=Enum.ScaleType.Fit
  bg.Position=UDim2.fromOffset(76,0)
  bg.Size=UDim2.new(1,-76,0,0)
  local aspect=bg:FindFirstChild('ArtworkAspect') or Instance.new('UIAspectRatioConstraint')
  aspect.Name='ArtworkAspect'
  aspect.AspectRatio=735/303
  aspect.DominantAxis=Enum.DominantAxis.Width
  aspect.AspectType=Enum.AspectType.ScaleWithParentSize
  aspect.Parent=bg
  bg.ImageTransparency=.1
  local fade=bg:FindFirstChildOfClass('UIGradient') or Instance.new('UIGradient',bg)
  fade.Enabled=true fade.Rotation=90
  fade.Transparency=NumberSequence.new({
   NumberSequenceKeypoint.new(0,0),
   NumberSequenceKeypoint.new(.4,0),
   NumberSequenceKeypoint.new(.65,.22),
   NumberSequenceKeypoint.new(.85,.7),
   NumberSequenceKeypoint.new(1,1)
  })
  local lower=u.shell:FindFirstChild('LowerAtmosphere')
  if lower then lower.Visible=false end
  u.shell.Hero.BackgroundTransparency=1
  u.artworkDisplayVersion='full-region-soft-fade-4'
 end
end

do
 local S=getgenv().BlueFarm local u=S and S.modernUI
 if u then
  local shade=u.shell.Hero:FindFirstChild('TextContrast')
  local gradient=shade and shade:FindFirstChildOfClass('UIGradient')
  if gradient then
   gradient.Enabled=true
   gradient.Rotation=0
   gradient.Transparency=NumberSequence.new({
    NumberSequenceKeypoint.new(0,.12),
    NumberSequenceKeypoint.new(.5,.36),
    NumberSequenceKeypoint.new(.78,.88),
    NumberSequenceKeypoint.new(1,.78)
   })
  end
  u.headerArtworkVersion='transparent-shade-5'
 end
end
